export type Instrument = 'Violão' | 'Piano';
export type Level = 'NZ' | 'N1' | 'N2' | 'N3';
export type UserRole = 'ADMIN' | 'STUDENT';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  instrument?: Instrument;
  level?: Level;
  avatar?: string;
}

export interface Course {
  id: string;
  title: string;
  instrument: Instrument;
  level: Level;
  description: string;
  lessons: Lesson[];
}

export interface Lesson {
  id: string;
  title: string;
  videoUrl?: string;
  description: string;
  courseId: string;
}

export interface ScheduledClass {
  id: string;
  studentId: string;
  teacherId: string;
  date: string;
  time: string;
  status: 'PENDING' | 'CONFIRMED' | 'CANCELLED';
  instrument: Instrument;
}

export interface Material {
  id: string;
  title: string;
  fileUrl: string;
  instrument: Instrument;
  level: Level;
}

export interface Payment {
  id: string;
  studentId: string;
  amount: number;
  status: 'PAID' | 'PENDING' | 'OVERDUE';
  dueDate: string;
}

