        </div>
        <div className="p-8">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700">Acessar como</label>
              <div className="mt-2 grid grid-cols-2 gap-3">
                <button
                  type="button"
                  onClick={() => setRole('STUDENT')}
                  className={`py-2 px-4 text-sm font-medium rounded-lg border ${
                    role === 'STUDENT' ? 'bg-red-600 text-white border-red-600' : 'bg-white text-gray-700 border-gray-200'
                  } transition-all duration-200`}
                >
                  Aluno
                </button>
                <button
                  type="button"
                  onClick={() => setRole('ADMIN')}
                  className={`py-2 px-4 text-sm font-medium rounded-lg border ${
                    role === 'ADMIN' ? 'bg-red-600 text-white border-red-600' : 'bg-white text-gray-700 border-gray-200'
                  } transition-all duration-200`}
                >
                  Administrador
                </button>
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700">E-mail</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-red-500 focus:border-red-500"
                placeholder={role === 'ADMIN' ? 'admin@comotocarhinos.com' : 'seu@email.com'}
              />
            </div>

            <button
              type="submit"
              className="w-full flex justify-center py-3 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 transition-colors"
            >
              Entrar na Plataforma
            </button>
            <p className="text-center text-xs text-gray-400 mt-4">
              Demo: Alunos (joao@email.com, maria@email.com) ou Admin
            </p>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level } from '../types';
import { MOCK_STUDENTS, MOCK_COURSES, MOCK_SCHEDULES, MOCK_PAYMENTS, MOCK_MATERIALS } from '../constants';
import { generateLessonDescription } from '../services/geminiService';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments' | 'materials';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user, onLogout }) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [courses, setCourses] = useState<Course[]>(MOCK_COURSES);
  const [schedules, setSchedules] = useState<ScheduledClass[]>(MOCK_SCHEDULES);
  const [payments, setPayments] = useState<Payment[]>(MOCK_PAYMENTS);
  const [materials, setMaterials] = useState<Material[]>(MOCK_MATERIALS);
  const [isGenerating, setIsGenerating] = useState(false);

  const stats = [
    { name: 'Alunos Ativos', value: MOCK_STUDENTS.length },
    { name: 'Aulas Hoje', value: 2 },
    { name: 'Cursos', value: courses.length },
    { name: 'Pagamentos Pendentes', value: payments.filter(p => p.status === 'PENDING').length },
  ];

  const handleGenerateDesc = async (index: number) => {
    setIsGenerating(true);
    const course = courses[index];
    const newDesc = await generateLessonDescription(course.title, course.instrument, course.level);
    const updatedCourses = [...courses];
    updatedCourses[index] = { ...course, description: newDesc };
    setCourses(updatedCourses);
    setIsGenerating(false);
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      {/* Sidebar */}
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800">
        <div className="p-6">
          <h2 className="text-xl font-bold text-red-600">Painel Admin</h2>
          <p className="text-xs text-gray-400 mt-1">Gerenciamento Escolar</p>
        </div>
        <nav className="flex-1 px-4 space-y-1 mt-4">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎸" label="Cursos & Aulas" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agendamentos" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Pagamentos" />
          <SidebarLink active={activeView === 'materials'} onClick={() => setActiveView('materials')} icon="📚" label="Materiais" />
        </nav>
        <div className="p-4 border-t border-gray-800">
          <button onClick={onLogout} className="w-full flex items-center px-4 py-2 text-sm text-gray-400 hover:text-white hover:bg-red-600 rounded-lg transition-colors">
            <span className="mr-2">🚪</span> Sair
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Bem-vindo, {user.name}</h1>
            <p className="text-gray-500">Administrando a "Como Tocar Hinos"</p>
          </div>
          <div className="flex items-center space-x-4">
             <div className="text-right hidden sm:block">
                <p className="text-sm font-medium">{user.email}</p>
                <p className="text-xs text-red-600">Acesso Restrito</p>
             </div>
             <img src={user.avatar} className="w-10 h-10 rounded-full border-2 border-red-600" alt="Avatar" />
          </div>
        </header>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
          {stats.map((stat) => (
            <div key={stat.name} className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
              <p className="text-sm font-medium text-gray-500">{stat.name}</p>
              <p className="text-2xl font-bold text-gray-900 mt-1">{stat.value}</p>
            </div>
          ))}
        </div>

        {/* Dynamic View */}
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
          {activeView === 'students' && (
            <div className="p-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-lg font-semibold">Alunos Cadastrados</h3>
                <button className="bg-red-600 text-white px-4 py-2 rounded-lg text-sm hover:bg-red-700 transition-colors">+ Novo Aluno</button>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="border-b text-gray-500 text-sm">
                      <th className="pb-3 font-medium">Nome</th>
                      <th className="pb-3 font-medium">Instrumento</th>
                      <th className="pb-3 font-medium">Nível</th>
                      <th className="pb-3 font-medium text-right">Ações</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y text-sm">
                    {MOCK_STUDENTS.map(student => (
                      <tr key={student.id} className="hover:bg-gray-50 transition-colors">
                        <td className="py-4 font-medium">{student.name}</td>
                        <td className="py-4">{student.instrument}</td>
                        <td className="py-4"><span className="px-2 py-1 bg-red-100 text-red-700 rounded text-xs font-bold">{student.level}</span></td>
                        <td className="py-4 text-right">
                          <button className="text-blue-600 hover:underline mr-2">Editar</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {activeView === 'courses' && (
            <div className="p-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-lg font-semibold">Gerenciar Cursos</h3>
                <button className="bg-red-600 text-white px-4 py-2 rounded-lg text-sm hover:bg-red-700 transition-colors">+ Criar Curso</button>
              </div>
              <div className="grid grid-cols-1 gap-4">
                {courses.map((course, idx) => (
                  <div key={course.id} className="p-4 border rounded-lg flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div className="flex-1">
                      <div className="flex items-center space-x-2">
                        <h4 className="font-bold">{course.title}</h4>
                        <span className="text-xs bg-gray-100 px-2 py-1 rounded">{course.instrument}</span>
                      </div>
                      <p className="text-sm text-gray-500 mt-1">{course.description}</p>
                    </div>
                    <div className="flex items-center space-x-2">
                      <button 
                        onClick={() => handleGenerateDesc(idx)}
                        disabled={isGenerating}
                        className="text-xs border border-red-600 text-red-600 px-3 py-1 rounded hover:bg-red-50 disabled:opacity-50"
                      >
                        {isGenerating ? 'IA Pensando...' : '✨ IA: Gerar Descrição'}
                      </button>
                      <button className="text-xs bg-black text-white px-3 py-1 rounded hover:bg-gray-800">Aulas</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeView === 'schedules' && (
             <div className="p-6">
                <h3 className="text-lg font-semibold mb-4">Aulas Agendadas</h3>
                <div className="space-y-4">
                   {schedules.map(sc => {
                     const student = MOCK_STUDENTS.find(s => s.id === sc.studentId);
                     return (
                        <div key={sc.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
                           <div>
                              <p className="font-bold">{student?.name} - {sc.instrument}</p>
                              <p className="text-sm text-gray-500">{new Date(sc.date).toLocaleDateString('pt-BR')} às {sc.time}</p>
                           </div>
                           <span className={`px-3 py-1 rounded-full text-xs font-bold ${sc.status === 'CONFIRMED' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                              {sc.status === 'CONFIRMED' ? 'Confirmada' : 'Pendente'}
                           </span>
