                     )
                   })}
                </div>
             </div>
          )}

          {activeView === 'payments' && (
             <div className="p-6">
                <h3 className="text-lg font-semibold mb-4">Controle Financeiro</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="border-b text-gray-500 text-sm">
                        <th className="pb-3">Aluno</th>
                        <th className="pb-3">Valor</th>
                        <th className="pb-3">Vencimento</th>
                        <th className="pb-3">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y text-sm">
                      {payments.map(p => {
                        const student = MOCK_STUDENTS.find(s => s.id === p.studentId);
                        return (
                          <tr key={p.id}>
                            <td className="py-4">{student?.name}</td>
                            <td className="py-4">R$ {p.amount.toFixed(2)}</td>
                            <td className="py-4">{new Date(p.dueDate).toLocaleDateString('pt-BR')}</td>
                            <td className="py-4">
                              <span className={`px-2 py-1 rounded text-xs font-bold ${p.status === 'PAID' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                {p.status === 'PAID' ? 'Pago' : 'Pendente'}
                              </span>
                            </td>
                          </tr>
                        )
                      })}
                    </tbody>
                  </table>
                </div>
             </div>
          )}

          {activeView === 'materials' && (
             <div className="p-6">
                <div className="flex justify-between items-center mb-4">
                   <h3 className="text-lg font-semibold">Materiais para Download</h3>
                   <button className="bg-black text-white px-4 py-2 rounded-lg text-sm hover:bg-gray-800 transition-colors">+ Subir Arquivo</button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   {materials.map(m => (
                      <div key={m.id} className="p-4 border rounded-lg flex items-center justify-between">
                         <div className="flex items-center space-x-3">
                            <span className="text-2xl">📄</span>
                            <div>
                               <p className="font-bold text-sm">{m.title}</p>
                               <p className="text-xs text-gray-500">{m.instrument} - {m.level}</p>
                            </div>
                         </div>
                         <button className="text-red-600 hover:underline text-sm">Remover</button>
                      </div>
                   ))}
                </div>
             </div>
          )}
        </div>
      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
