interface StudentDashboardProps {
  user: User;
  onLogout: () => void;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ user, onLogout }) => {
  const [exercises, setExercises] = useState<string>('');
  const [loadingAI, setLoadingAI] = useState(false);

  // Filter content based on student profile (Instrument & Level)
  const myCourses = MOCK_COURSES.filter(c => c.instrument === user.instrument && c.level === user.level);
  const mySchedules = MOCK_SCHEDULES.filter(s => s.studentId === user.id);
  const myMaterials = MOCK_MATERIALS.filter(m => m.instrument === user.instrument && m.level === user.level);
  const myPayment = MOCK_PAYMENTS.find(p => p.studentId === user.id);

  useEffect(() => {
    const fetchAI = async () => {
      setLoadingAI(true);
      if (user.level && user.instrument) {
        const suggs = await suggestExercises(user.level, user.instrument);
        setExercises(suggs);
      }
      setLoadingAI(false);
    };
    fetchAI();
  }, [user.level, user.instrument]);

  return (
    <div className="min-h-screen bg-white">
