import React, { useState, useEffect } from 'react';
import { User, UserRole } from './types';
import { MOCK_ADMIN, MOCK_STUDENTS } from './constants';
import AdminDashboard from './components/AdminDashboard';
import StudentDashboard from './components/StudentDashboard';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    setLoading(false);
  }, []);

  const handleLogin = (email: string, password: string, role: UserRole) => {
    let loggedUser: User | undefined;

    if (role === 'ADMIN') {
      if (MOCK_ADMIN.email === email && MOCK_ADMIN.password === password) {
        loggedUser = MOCK_ADMIN;
      }
    } else {
      loggedUser = MOCK_STUDENTS.find(s => s.email === email && s.password === password);
    }

    if (loggedUser) {
      setUser(loggedUser);
      localStorage.setItem('user', JSON.stringify(loggedUser));
    } else {
      alert("E-mail ou senha incorretos para este tipo de acesso!");
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('user');
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-white">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red-600"></div>
      </div>
    );
  }

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard user={user} onLogout={handleLogout} />
      ) : (
        <StudentDashboard user={user} onLogout={handleLogout} />
      )}
    </div>
  );
};

export default App;

