import React, { useState, useEffect } from 'react';
import { User, UserRole, Course, ScheduledClass, Payment, Material } from './types';
import { MOCK_ADMIN, MOCK_STUDENTS, MOCK_COURSES, MOCK_SCHEDULES, MOCK_PAYMENTS, MOCK_MATERIALS } from './constants';
import AdminDashboard from './components/AdminDashboard';
import StudentDashboard from './components/StudentDashboard';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Estados globais (Simulando o Banco de Dados)
  const [students, setStudents] = useState<User[]>(MOCK_STUDENTS);
  const [courses, setCourses] = useState<Course[]>(MOCK_COURSES.map(c => ({...c, studentIds: ['std-1', 'std-2', 'std-3']}))); // Todos iniciam com acesso
  const [schedules, setSchedules] = useState<ScheduledClass[]>(MOCK_SCHEDULES);
  const [payments, setPayments] = useState<Payment[]>(MOCK_PAYMENTS);
  const [materials, setMaterials] = useState<Material[]>(MOCK_MATERIALS);

  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    setLoading(false);
  }, []);

  const handleLogin = (email: string, role: UserRole) => {
    let loggedUser: User | undefined;
    if (role === 'ADMIN') {
      if (MOCK_ADMIN.email === email) loggedUser = MOCK_ADMIN;
    } else {
      loggedUser = students.find(s => s.email === email);
    }

    if (loggedUser) {
      setUser(loggedUser);
      localStorage.setItem('user', JSON.stringify(loggedUser));
    } else {
      alert("Usuário não encontrado!");
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('user');
  };

  // Funções de Gerenciamento (Actions)
  const addSchedule = (newClass: ScheduledClass) => setSchedules(prev => [...prev, newClass]);
  const updateCourseAccess = (courseId: string, studentIds: string[]) => {
    setCourses(prev => prev.map(c => c.id === courseId ? { ...c, studentIds } : c));
  };
  const addPayment = (p: Payment) => setPayments(prev => [...prev, p]);

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-white">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red-600"></div>
      </div>
    );
  }

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard 
          user={user} 
          onLogout={handleLogout}
          students={students}
          courses={courses}
          schedules={schedules}
          payments={payments}
          materials={materials}
          onAddSchedule={addSchedule}
          onUpdateCourse={updateCourseAccess}
        />
      ) : (
        <StudentDashboard 
          user={user} 
          onLogout={handleLogout}
          courses={courses}
          schedules={schedules}
          materials={materials}
          payments={payments}
        />
      )}
    </div>
  );
};

export default App;

