import React, { useState, useEffect } from 'react';
import { User, UserRole, Course, ScheduledClass, Payment, Material } from './types';
import { MOCK_ADMIN, MOCK_STUDENTS, MOCK_COURSES, MOCK_SCHEDULES, MOCK_PAYMENTS, MOCK_MATERIALS } from './constants';
import AdminDashboard from './components/AdminDashboard';
import StudentDashboard from './components/StudentDashboard';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Estados principais com persistência no LocalStorage
  const [students, setStudents] = useState<User[]>(() => {
    const saved = localStorage.getItem('hinos_students');
    return saved ? JSON.parse(saved) : MOCK_STUDENTS;
  });

  const [courses, setCourses] = useState<Course[]>(() => {
    const saved = localStorage.getItem('hinos_courses');
    return saved ? JSON.parse(saved) : MOCK_COURSES;
  });

  const [schedules, setSchedules] = useState<ScheduledClass[]>(() => {
    const saved = localStorage.getItem('hinos_schedules');
    return saved ? JSON.parse(saved) : MOCK_SCHEDULES;
  });

  const [payments, setPayments] = useState<Payment[]>(() => {
    const saved = localStorage.getItem('hinos_payments');
    return saved ? JSON.parse(saved) : MOCK_PAYMENTS;
  });

  const [materials, setMaterials] = useState<Material[]>(() => {
    const saved = localStorage.getItem('hinos_materials');
    return saved ? JSON.parse(saved) : MOCK_MATERIALS;
  });

  // Efeito para salvar sempre que houver mudanças (Simulando o Banco)
  useEffect(() => {
    localStorage.setItem('hinos_students', JSON.stringify(students));
    localStorage.setItem('hinos_courses', JSON.stringify(courses));
    localStorage.setItem('hinos_schedules', JSON.stringify(schedules));
    localStorage.setItem('hinos_payments', JSON.stringify(payments));
    localStorage.setItem('hinos_materials', JSON.stringify(materials));
  }, [students, courses, schedules, payments, materials]);

  useEffect(() => {
    const savedUser = localStorage.getItem('hinos_current_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    setLoading(false);
  }, []);

  const handleLogin = (email: string, role: UserRole) => {
    let loggedUser: User | undefined;
    if (role === 'ADMIN') {
      if (MOCK_ADMIN.email === email) loggedUser = MOCK_ADMIN;
    } else {
      loggedUser = students.find(s => s.email.toLowerCase() === email.toLowerCase());
    }

    if (loggedUser) {
      setUser(loggedUser);
      localStorage.setItem('hinos_current_user', JSON.stringify(loggedUser));
    } else {
      alert("E-mail não cadastrado!");
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('hinos_current_user');
  };

  // Funções Administrativas
  const addStudent = (newStudent: User) => setStudents(prev => [...prev, newStudent]);

  const addSchedule = (newClass: ScheduledClass) => setSchedules(prev => [...prev, newClass]);

  const updateCourseAccess = (courseId: string, studentIds: string[]) => {
    setCourses(prev => prev.map(c => c.id === courseId ? { ...c, studentIds } : c));
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-white">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red-600"></div>
      </div>
    );
  }

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard 
          user={user} 
          onLogout={handleLogout}
          students={students}
          courses={courses}
          schedules={schedules}
          payments={payments}
          materials={materials}
          onAddStudent={addStudent}
          onAddSchedule={addSchedule}
          onUpdateCourse={updateCourseAccess}
        />
      ) : (
        <StudentDashboard 
          user={user} 
          onLogout={handleLogout}
          courses={courses}
          schedules={schedules}
          materials={materials}
          payments={payments}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level } from '../types';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => void;
  onAddSchedule: (sc: ScheduledClass) => void;
  onUpdateCourse: (id: string, ids: string[]) => void;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments' | 'materials';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, onAddStudent, onAddSchedule, onUpdateCourse 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');

  // States para Formulários
  const [showAddStudent, setShowAddStudent] = useState(false);
  const [newStudent, setNewStudent] = useState<Partial<User>>({
    name: '', email: '', instrument: 'Violão', level: 'NZ'
  });

  const [showAddClass, setShowAddClass] = useState(false);
  const [newClass, setNewClass] = useState<Partial<ScheduledClass>>({
    studentId: '', date: '', time: '', instrument: 'Violão'
  });

  const handleCreateStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.name || !newStudent.email) return alert("Preencha os dados básicos");

    onAddStudent({
      id: `std-${Date.now()}`,
      name: newStudent.name!,
      email: newStudent.email!,
      role: 'STUDENT',
      instrument: newStudent.instrument as Instrument,
      level: newStudent.level as Level,
      avatar: `https://picsum.photos/seed/${newStudent.email}/200`
    });
    setShowAddStudent(false);
    setNewStudent({ name: '', email: '', instrument: 'Violão', level: 'NZ' });
    alert("Aluno cadastrado com sucesso!");
  };

  const handleAddClass = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newClass.studentId || !newClass.date || !newClass.time) return alert("Preencha tudo");

    onAddSchedule({
      id: `sc-${Date.now()}`,
      studentId: newClass.studentId!,
      teacherId: user.id,
      date: newClass.date!,
      time: newClass.time!,
      status: 'CONFIRMED',
      instrument: newClass.instrument as Instrument
    });
    setShowAddClass(false);
    alert("Aula agendada!");
  };

  const toggleCourseStudent = (courseId: string, studentId: string) => {
    const course = courses.find(c => c.id === courseId);
    if (!course) return;
    let newIds = [...(course.studentIds || [])];
    if (newIds.includes(studentId)) {
      newIds = newIds.filter(id => id !== studentId);
    } else {
      newIds.push(studentId);
    }
    onUpdateCourse(courseId, newIds);
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800 shrink-0">
        <div className="p-6">
          <h2 className="text-xl font-bold text-red-600">HINOS ADMIN</h2>
          <div className="flex items-center mt-4 p-2 bg-gray-900 rounded-lg">
             <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2"></div>
             <span className="text-[10px] font-bold uppercase text-gray-400 tracking-widest">Base de Dados Online</span>
          </div>
        </div>
        <nav className="flex-1 px-4 space-y-1 mt-4">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-4 border-t border-gray-800">
          <button onClick={onLogout} className="w-full flex items-center px-4 py-2 text-sm text-gray-400 hover:text-white hover:bg-red-600 rounded-lg transition-colors">
            🚪 Sair do Sistema
          </button>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <header className="flex justify-between items-center mb-8 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div>
            <h1 className="text-2xl font-black text-gray-900 uppercase">Gestão da Escola</h1>
            <p className="text-gray-500 text-sm">Organize aulas, alunos e acessos de forma centralizada.</p>
          </div>
          <div className="flex items-center space-x-3">
             <div className="text-right">
                <p className="text-xs font-black uppercase text-red-600">Administrador</p>
                <p className="text-sm font-bold text-gray-900">{user.name}</p>
             </div>
             <img src={user.avatar} className="w-12 h-12 rounded-full border-2 border-black" alt="Avatar" />
          </div>
        </header>

        <div className="bg-white rounded-3xl border border-gray-100 shadow-xl overflow-hidden">
          {activeView === 'students' && (
            <div className="p-8">
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-xl font-black uppercase">Cadastro de Alunos</h3>
                <button 
                  onClick={() => setShowAddStudent(!showAddStudent)}
                  className="bg-red-600 text-white px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-black transition-all"
                >
                  {showAddStudent ? 'Fechar' : '+ Novo Aluno'}
                </button>
              </div>

              {showAddStudent && (
                <form onSubmit={handleCreateStudent} className="mb-10 p-8 bg-gray-50 border-2 border-dashed border-gray-200 rounded-3xl grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-in fade-in slide-in-from-top-4 duration-300">
                  <div>
                    <label className="block text-[10px] font-black uppercase text-gray-500 mb-1">Nome Completo</label>
                    <input required type="text" className="w-full bg-white border border-gray-200 p-3 rounded-xl text-sm" placeholder="Ex: João Silva" onChange={e => setNewStudent({...newStudent, name: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase text-gray-500 mb-1">E-mail de Acesso</label>
                    <input required type="email" className="w-full bg-white border border-gray-200 p-3 rounded-xl text-sm" placeholder="joao@email.com" onChange={e => setNewStudent({...newStudent, email: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase text-gray-500 mb-1">Instrumento</label>
                    <select className="w-full bg-white border border-gray-200 p-3 rounded-xl text-sm" onChange={e => setNewStudent({...newStudent, instrument: e.target.value as Instrument})}>
                      <option value="Violão">Violão</option>
                      <option value="Piano">Piano</option>
                    </select>
                  </div>
                  <div className="flex items-end">
                    <button type="submit" className="w-full bg-black text-white p-3 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-red-600 transition-colors">Cadastrar Aluno</button>
                  </div>
                </form>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {students.map(s => (
                  <div key={s.id} className="p-6 border border-gray-100 rounded-3xl bg-white hover:border-red-600 transition-all shadow-sm">
                    <div className="flex items-center space-x-4 mb-4">
                       <img src={s.avatar} className="w-12 h-12 rounded-full border" alt="" />
                       <div>
                          <p className="font-black text-sm uppercase">{s.name}</p>
                          <p className="text-[10px] text-gray-500">{s.email}</p>
                       </div>
                    </div>
                    <div className="flex justify-between items-center pt-4 border-t border-gray-50">
                       <span className="text-[10px] font-black uppercase bg-red-50 text-red-600 px-2 py-1 rounded">{s.instrument}</span>
                       <span className="text-[10px] font-black uppercase bg-gray-900 text-white px-2 py-1 rounded">Nível {s.level}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeView === 'courses' && (
            <div className="p-8">
              <h3 className="text-xl font-black uppercase mb-8">Atribuição de Cursos</h3>
              <div className="space-y-6">
                {courses.map(course => (
                  <div key={course.id} className="border-2 border-gray-100 rounded-3xl p-6 bg-gray-50">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                       <div>
                          <h4 className="font-black text-lg uppercase leading-none">{course.title}</h4>
                          <p className="text-xs text-red-600 font-bold mt-1 uppercase tracking-tighter">{course.instrument} | {course.level}</p>
                       </div>
                       <div className="text-[10px] font-black uppercase bg-black text-white px-3 py-1 rounded-full">
                          {course.studentIds.length} ALUNOS COM ACESSO
                       </div>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-2">
                      {students.map(student => (
                        <button
                          key={student.id}
                          onClick={() => toggleCourseStudent(course.id, student.id)}
                          className={`text-[10px] p-3 rounded-xl border-2 transition-all font-black uppercase truncate ${
                            course.studentIds.includes(student.id) 
                              ? 'bg-red-600 border-red-600 text-white' 
                              : 'bg-white border-gray-200 text-gray-400 hover:border-red-300'
                          }`}
                        >
                          {student.name}
                        </button>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeView === 'schedules' && (
            <div className="p-8">
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-xl font-black uppercase tracking-tight">Agenda de Aulas</h3>
                <button 
                  onClick={() => setShowAddClass(!showAddClass)}
                  className="bg-black text-white px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest"
                >
                  {showAddClass ? 'Cancelar' : '+ Marcar Horário'}
                </button>
              </div>

              {showAddClass && (
                <form onSubmit={handleAddClass} className="mb-10 p-8 bg-red-50 border-2 border-red-100 rounded-3xl grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div>
                    <label className="block text-[10px] font-black uppercase text-red-600 mb-1">Escolher Aluno</label>
                    <select 
                      required
                      className="w-full bg-white border border-red-200 p-3 rounded-xl text-sm font-bold"
                      value={newClass.studentId}
                      onChange={e => setNewClass({...newClass, studentId: e.target.value})}
                    >
                      <option value="">Selecione...</option>
                      {students.map(s => <option key={s.id} value={s.id}>{s.name} ({s.instrument})</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase text-red-600 mb-1">Data da Aula</label>
                    <input required type="date" className="w-full bg-white border border-red-200 p-3 rounded-xl text-sm" onChange={e => setNewClass({...newClass, date: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase text-red-600 mb-1">Hora</label>
                    <input required type="time" className="w-full bg-white border border-red-200 p-3 rounded-xl text-sm" onChange={e => setNewClass({...newClass, time: e.target.value})} />
                  </div>
                  <button type="submit" className="md:col-span-3 bg-red-600 text-white py-4 rounded-xl text-sm font-black uppercase tracking-widest hover:bg-black transition-colors shadow-lg">Confirmar Aula na Agenda do Aluno</button>
                </form>
              )}

              <div className="space-y-4">
                {schedules.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(sc => {
                  const s = students.find(std => std.id === sc.studentId);
                  return (
                    <div key={sc.id} className="flex flex-col sm:flex-row items-center justify-between p-6 border-2 border-gray-50 rounded-3xl hover:bg-gray-50 transition-all group">
