);

export default AdminDashboard;

export type Instrument = 'Violão' | 'Piano';
export type Level = 'NZ' | 'N1' | 'N2' | 'N3';
export type UserRole = 'ADMIN' | 'STUDENT';

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  role: UserRole;
  instrument?: Instrument;
  level?: Level;
  avatar?: string;
}

export interface Lesson {
  id: string;
  title: string;
  videoArranjoUrl: string; // Link do YouTube
  videoAoVivoUrl: string;  // Link do YouTube
  description: string;
}

export interface Module {
  id: string;
  title: string;
  lessons: Lesson[];
}

export interface Course {
  id: string;
  title: string;
  instrument: Instrument;
  level: Level;
  description: string;
  modules: Module[];
  studentIds: string[];
}

export interface ScheduledClass {
  id: string;
  studentId: string;
  teacherId: string;
  date: string;
  time: string;
  status: 'PENDING' | 'CONFIRMED' | 'CANCELLED';
  instrument: Instrument;
}

export interface Material {
  id: string;
  title: string;
  fileUrl: string;
  instrument: Instrument;
  level: Level;
  studentIds?: string[];
}

export interface Payment {
  id: string;
