  user, onLogout, courses, schedules, materials, payments, onUpdateProfile 
}) => {
  const [exercises, setExercises] = useState<string>('');
  const [loadingAI, setLoadingAI] = useState(false);
  const [viewingCourse, setViewingCourse] = useState<Course | null>(null);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileForm, setProfileForm] = useState<User>(user);

  const myCourses = courses.filter(c => c.studentIds.includes(user.id));
  const mySchedules = schedules.filter(s => s.studentId === user.id);
  const myMaterials = materials.filter(m => m.instrument === user.instrument && m.level === user.level);
  const myPayment = payments.find(p => p.studentId === user.id);

  useEffect(() => {
    const fetchAI = async () => {
      setLoadingAI(true);
      if (user.level && user.instrument) {
        const suggs = await suggestExercises(user.level, user.instrument);
        setExercises(suggs);
      }
      setLoadingAI(false);
