              ) : (
                <div className="text-xs font-bold leading-relaxed opacity-90 relative z-10 whitespace-pre-wrap">
                  {exercises}
                </div>
              )}
            </div>

            <section className="bg-white border-2 border-gray-100 p-8 rounded-[3rem]">
              <h3 className="text-xs font-black uppercase mb-6 tracking-widest text-gray-400">Bibliotecas Digitais</h3>
              <div className="space-y-3">
                {myMaterials.map(m => (
                  <a key={m.id} href={m.fileUrl} className="flex items-center p-4 bg-gray-50 rounded-2xl hover:bg-black hover:text-white transition-all group">
                    <span className="text-xl mr-3 group-hover:scale-110 transition-transform">📄</span>
                    <span className="flex-1 text-[11px] font-black uppercase tracking-tight">{m.title}</span>
                  </a>
                ))}
              </div>
            </section>

            {myPayment && (
              <section className="bg-black text-white p-8 rounded-[3rem] relative overflow-hidden">
                <div className={`absolute top-0 right-0 p-6 text-[10px] font-black uppercase ${myPayment.status === 'PAID' ? 'text-green-500' : 'text-red-500 animate-pulse'}`}>
                  {myPayment.status === 'PAID' ? '● Pago' : '● Pendente'}
                </div>
                <h3 className="text-xs font-black uppercase mb-4 opacity-50 tracking-widest">Financeiro</h3>
                <p className="text-[10px] font-bold uppercase text-gray-400">Próximo Vencimento</p>
                <p className="text-3xl font-black mt-1">R$ {myPayment.amount.toFixed(2)}</p>
                <p className="text-[10px] font-black uppercase text-red-600 mt-2">{new Date(myPayment.dueDate).toLocaleDateString()}</p>
              </section>
            )}
          </div>

        </div>
      </main>
    </div>
  );
};

