                    {/* Seção de Conclusão de Aulas */}
                    <div className="md:col-span-2 mt-4">
                       <h4 className="text-[10px] font-black uppercase text-red-600 mb-4 tracking-widest border-b pb-2">Ciclo de 4 Aulas Atual</h4>
                       <div className="space-y-3">
                         {editingStudent.currentCycle?.map(lesson => (
                           <div key={lesson.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl">
                             <span className="text-xs font-bold uppercase">{lesson.title}</span>
