import React, { useState, useEffect } from 'react';
import { User, UserRole, Course, ScheduledClass, Payment, Material } from './types';
import { MOCK_ADMIN, MOCK_STUDENTS, MOCK_COURSES, MOCK_SCHEDULES, MOCK_PAYMENTS, MOCK_MATERIALS } from './constants';
import AdminDashboard from './components/AdminDashboard';
import StudentDashboard from './components/StudentDashboard';
import Login from './components/Login';
import { supabase } from './services/supabase';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Estados principais
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [schedules, setSchedules] = useState<ScheduledClass[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);

  // Sincronização inicial com Supabase
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        // Busca de alunos/perfis
        const { data: profiles, error: pError } = await supabase.from('profiles').select('*');
        if (profiles) setStudents(profiles as User[]);
        else setStudents(MOCK_STUDENTS);

        // Busca de cursos
        const { data: dbCourses, error: cError } = await supabase.from('courses').select('*');
        if (dbCourses) setCourses(dbCourses as Course[]);
        else setCourses(MOCK_COURSES);

        // Busca de agendamentos
        const { data: dbSchedules, error: sError } = await supabase.from('schedules').select('*');
        if (dbSchedules) setSchedules(dbSchedules as ScheduledClass[]);
        else setSchedules(MOCK_SCHEDULES);

        // Busca de pagamentos
        const { data: dbPayments, error: payError } = await supabase.from('payments').select('*');
        if (dbPayments) setPayments(dbPayments as Payment[]);
        else setPayments(MOCK_PAYMENTS);

        // Busca de materiais
        const { data: dbMaterials, error: mError } = await supabase.from('materials').select('*');
        if (dbMaterials) setMaterials(dbMaterials as Material[]);
        else setMaterials(MOCK_MATERIALS);

      } catch (err) {
        console.error("Erro ao sincronizar com Supabase:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem('hinos_current_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  const handleLogin = (email: string, role: UserRole) => {
    let loggedUser: User | undefined;
    if (role === 'ADMIN') {
      if (MOCK_ADMIN.email === email) loggedUser = MOCK_ADMIN;
    } else {
      loggedUser = students.find(s => s.email.toLowerCase() === email.toLowerCase());
    }

    if (loggedUser) {
      setUser(loggedUser);
      localStorage.setItem('hinos_current_user', JSON.stringify(loggedUser));
    } else {
      alert("E-mail não cadastrado ou erro na sincronização!");
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('hinos_current_user');
  };

  // Operações de Escrita (Sincronizadas com Supabase)
  const addStudent = async (newStudent: User) => {
    const { error } = await supabase.from('profiles').insert([newStudent]);
    if (!error) setStudents(prev => [...prev, newStudent]);
  };

  const updateStudent = async (updatedUser: User) => {
    const { error } = await supabase.from('profiles').update(updatedUser).eq('id', updatedUser.id);
    if (!error) {
      setStudents(prev => prev.map(s => s.id === updatedUser.id ? updatedUser : s));
      if (user && user.id === updatedUser.id) {
        setUser(updatedUser);
        localStorage.setItem('hinos_current_user', JSON.stringify(updatedUser));
      }
    }
  };

  const addSchedule = async (newClass: ScheduledClass) => {
    const { error } = await supabase.from('schedules').insert([newClass]);
    if (!error) setSchedules(prev => [...prev, newClass]);
  };

  const updateCourseAccess = async (courseId: string, studentIds: string[]) => {
    const { error } = await supabase.from('courses').update({ studentIds }).eq('id', courseId);
    if (!error) {
      setCourses(prev => prev.map(c => c.id === courseId ? { ...c, studentIds } : c));
    }
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-white">
        <div className="flex flex-col items-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red-600 mb-4"></div>
          <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Sincronizando com Supabase...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard 
          user={user} 
          onLogout={handleLogout}
          students={students}
          courses={courses}
          schedules={schedules}
          payments={payments}
          materials={materials}
          onAddStudent={addStudent}
          onUpdateStudent={updateStudent}
          onAddSchedule={addSchedule}
          onUpdateCourse={updateCourseAccess}
        />
      ) : (
        <StudentDashboard 
          user={user} 
          onLogout={handleLogout}
          courses={courses}
          schedules={schedules}
          materials={materials}
          payments={payments}
          onUpdateProfile={updateStudent}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level, CycleLesson } from '../types';
import { supabase } from '../services/supabase';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => Promise<void>;
  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onUpdateCourse: (id: string, ids: string[]) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments' | 'materials';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, onAddStudent, onUpdateStudent, onAddSchedule, onUpdateCourse 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [editingStudent, setEditingStudent] = useState<User | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  const [showAddStudent, setShowAddStudent] = useState(false);
  const [newStudent, setNewStudent] = useState<Partial<User>>({
    name: '', email: '', instrument: 'Violão', level: 'NZ'
  });

  const handleCreateStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.name || !newStudent.email) return alert("Preencha os dados básicos");

    setIsSyncing(true);
    await onAddStudent({
      id: `std-${Date.now()}`,
      name: newStudent.name!,
      email: newStudent.email!,
      role: 'STUDENT',
      instrument: newStudent.instrument as Instrument,
      level: newStudent.level as Level,
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${newStudent.name}&backgroundColor=b6e3f4`,
      currentCycle: [
        { id: 'l1', title: 'Aula 1', completed: false },
        { id: 'l2', title: 'Aula 2', completed: false },
        { id: 'l3', title: 'Aula 3', completed: false },
        { id: 'l4', title: 'Aula 4', completed: false },
      ]
    });
    setIsSyncing(false);
    setShowAddStudent(false);
    setNewStudent({ name: '', email: '', instrument: 'Violão', level: 'NZ' });
  };

  const handleUpdateStudentProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudent) {
      setIsSyncing(true);
      await onUpdateStudent(editingStudent);
      setIsSyncing(false);
      setEditingStudent(null);
    }
  };

  const toggleCycleLesson = (lessonId: string) => {
    if (!editingStudent || !editingStudent.currentCycle) return;
    const newCycle = editingStudent.currentCycle.map(l => 
      l.id === lessonId ? { ...l, completed: !l.completed } : l
    );
    setEditingStudent({ ...editingStudent, currentCycle: newCycle });
  };

  const toggleCourseStudent = async (courseId: string, studentId: string) => {
    const course = courses.find(c => c.id === courseId);
    if (!course) return;
    let newIds = [...(course.studentIds || [])];
    if (newIds.includes(studentId)) {
      newIds = newIds.filter(id => id !== studentId);
    } else {
      newIds.push(studentId);
    }
    setIsSyncing(true);
    await onUpdateCourse(courseId, newIds);
    setIsSyncing(false);
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800 shrink-0">
        <div className="p-6">
          <h2 className="text-xl font-bold text-red-600 tracking-tighter uppercase">HINOS ADMIN</h2>
          <div className="flex items-center mt-4 p-2 bg-gray-900 rounded-lg">
             <div className={`w-2 h-2 ${isSyncing ? 'bg-yellow-500 animate-spin' : 'bg-green-500'} rounded-full mr-2`}></div>
             <span className="text-[10px] font-bold uppercase text-gray-400 tracking-widest">
               {isSyncing ? 'Sincronizando...' : 'Supabase Conectado'}
             </span>
          </div>
        </div>
        <nav className="flex-1 px-4 space-y-1 mt-4">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-4 border-t border-gray-800">
          <button onClick={onLogout} className="w-full flex items-center px-4 py-2 text-sm text-gray-400 hover:text-white hover:bg-red-600 rounded-lg transition-colors">
            🚪 Sair do Sistema
          </button>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <header className="flex justify-between items-center mb-8 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div>
            <h1 className="text-2xl font-black text-gray-900 uppercase tracking-tighter">Gestão Escolares</h1>
            <p className="text-gray-500 text-sm">Controle total sincronizado via Supabase.</p>
          </div>
          <div className="flex items-center space-x-3">
             <div className="text-right">
                <p className="text-xs font-black uppercase text-red-600">Admin Master</p>
                <p className="text-sm font-bold text-gray-900">{user.name}</p>
             </div>
             <img src={user.avatar} className="w-12 h-12 rounded-full border-2 border-black" alt="Avatar" />
          </div>
        </header>

        <div className="bg-white rounded-3xl border border-gray-100 shadow-xl overflow-hidden">
          {activeView === 'students' && (
            <div className="p-8">
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-xl font-black uppercase tracking-tight">Alunos na Nuvem</h3>
                <button 
                  onClick={() => setShowAddStudent(!showAddStudent)}
                  className="bg-red-600 text-white px-6 py-2 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-black transition-all"
                >
                  {showAddStudent ? 'Fechar' : '+ Novo Aluno'}
                </button>
              </div>

              {showAddStudent && (
                <form onSubmit={handleCreateStudent} className="mb-10 p-8 bg-gray-50 border-2 border-dashed border-gray-200 rounded-3xl grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-in fade-in slide-in-from-top-4 duration-300">
                  <div className="md:col-span-1">
                    <label className="block text-[10px] font-black uppercase text-gray-500 mb-1">Nome Completo</label>
                    <input required type="text" className="w-full bg-white border border-gray-200 p-3 rounded-xl text-sm" placeholder="Ex: João Silva" onChange={e => setNewStudent({...newStudent, name: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase text-gray-500 mb-1">E-mail</label>
                    <input required type="email" className="w-full bg-white border border-gray-200 p-3 rounded-xl text-sm" placeholder="joao@email.com" onChange={e => setNewStudent({...newStudent, email: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase text-gray-500 mb-1">Instrumento</label>
                    <select className="w-full bg-white border border-gray-200 p-3 rounded-xl text-sm" onChange={e => setNewStudent({...newStudent, instrument: e.target.value as Instrument})}>
