                         ✏️
                       </button>
                    </div>

                    <div className="flex space-x-1 mb-4">
                       {s.currentCycle?.map(l => (
                         <div key={l.id} title={l.title} className={`h-1 flex-1 rounded-full ${l.completed ? 'bg-green-500' : 'bg-gray-200'}`}></div>
                       ))}
                    </div>

                    <div className="grid grid-cols-2 gap-2">
                       <a href={`mailto:${s.email}`} className="text-[10px] font-black uppercase bg-gray-50 py-2 rounded-lg text-center hover:bg-black hover:text-white transition-colors">E-mail</a>
                       {s.whatsapp && (
                         <a href={`https://wa.me/${s.whatsapp}`} target="_blank" rel="noreferrer" className="text-[10px] font-black uppercase bg-green-50 text-green-600 py-2 rounded-lg text-center hover:bg-green-600 hover:text-white transition-colors">WhatsApp</a>
                       )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {editingStudent && (
            <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
                <div className="p-8 bg-red-600 text-white flex justify-between items-center">
                  <h3 className="text-xl font-black uppercase tracking-tighter">Gerenciar Aluno</h3>
                  <button onClick={() => setEditingStudent(null)} className="text-2xl font-black">&times;</button>
                </div>
                <div className="p-8 max-h-[70vh] overflow-y-auto custom-scrollbar">
                  <form onSubmit={handleUpdateStudentProfile} className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
                    <div className="md:col-span-2 flex justify-center mb-4">
                       <img src={editingStudent.avatar} className="w-20 h-20 rounded-full border-4 border-red-600" alt="" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Nome</label>
                      <input type="text" className="w-full border-2 border-gray-100 p-3 rounded-xl text-sm font-bold" value={editingStudent.name} onChange={e => setEditingStudent({...editingStudent, name: e.target.value})} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">WhatsApp</label>
                      <input type="text" className="w-full border-2 border-gray-100 p-3 rounded-xl text-sm font-bold" value={editingStudent.whatsapp || ''} onChange={e => setEditingStudent({...editingStudent, whatsapp: e.target.value})} />
                    </div>

                    <div className="md:col-span-2 mt-4">
                       <h4 className="text-[10px] font-black uppercase text-red-600 mb-4 tracking-widest border-b pb-2">Ciclo de 4 Aulas Atual</h4>
                       <div className="space-y-3">
                         {editingStudent.currentCycle?.map(lesson => (
                           <div key={lesson.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl">
                             <span className="text-xs font-bold uppercase">{lesson.title}</span>
                             <button
                               type="button"
                               onClick={() => toggleCycleLesson(lesson.id)}
                               className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${
                                 lesson.completed ? 'bg-green-600 text-white' : 'bg-gray-200 text-gray-500'
                               }`}
                             >
                               {lesson.completed ? 'Concluída' : 'Marcar Concluída'}
                             </button>
                           </div>
                         ))}
                       </div>
                    </div>

                    <div className="md:col-span-2 pt-4">
                      <button disabled={isSyncing} type="submit" className="w-full bg-black text-white py-4 rounded-2xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-red-600 transition-all disabled:opacity-50">
                        {isSyncing ? 'Sincronizando...' : 'Atualizar Cadastro e Ciclo'}
                      </button>
                    </div>
                  </form>
                </div>
              </div>
            </div>
          )}

          {activeView === 'courses' && (
            <div className="p-8">
              <h3 className="text-xl font-black uppercase mb-8 tracking-tighter">Matrícula em Cursos</h3>
              <div className="space-y-6">
                {courses.map(course => (
                  <div key={course.id} className="border-2 border-gray-50 rounded-[2rem] p-8 bg-gray-50/50">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8">
                       <div>
                          <h4 className="font-black text-xl uppercase tracking-tighter">{course.title}</h4>
                          <p className="text-xs text-red-600 font-bold uppercase tracking-widest">{course.instrument} • Módulo {course.level}</p>
                       </div>
                       <div className="bg-black text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest mt-4 md:mt-0">
                          {course.studentIds.length} Alunos Inscritos
                       </div>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
                      {students.map(student => (
                        <button
                          key={student.id}
                          disabled={isSyncing}
                          onClick={() => toggleCourseStudent(course.id, student.id)}
                          className={`text-[10px] p-4 rounded-xl border-2 transition-all font-black uppercase ${
                            course.studentIds.includes(student.id) 
                              ? 'bg-red-600 border-red-600 text-white shadow-lg' 
                              : 'bg-white border-gray-100 text-gray-400 hover:border-red-300'
                          } disabled:opacity-50`}
                        >
                          {student.name}
                        </button>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center px-4 py-4 text-xs font-black uppercase tracking-widest rounded-2xl transition-all ${
      active ? 'bg-red-600 text-white shadow-lg shadow-red-900/20' : 'text-gray-500 hover:text-white hover:bg-gray-900'
    }`}
  >
    <span className="mr-3 text-lg">{icon}</span>
    {label}
  </button>
);

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { User, UserRole, Course, ScheduledClass, Payment, Material } from './types';
import { MOCK_ADMIN, MOCK_STUDENTS, MOCK_COURSES, MOCK_SCHEDULES, MOCK_PAYMENTS, MOCK_MATERIALS } from './constants';
import AdminDashboard from './components/AdminDashboard';
import StudentDashboard from './components/StudentDashboard';
import Login from './components/Login';
import { supabase } from './services/supabase';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [schedules, setSchedules] = useState<ScheduledClass[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const { data: profiles } = await supabase.from('profiles').select('*');
        if (profiles) setStudents(profiles as User[]);
        else setStudents(MOCK_STUDENTS);

        const { data: dbCourses } = await supabase.from('courses').select('*');
        if (dbCourses) setCourses(dbCourses as Course[]);
        else setCourses(MOCK_COURSES);

        const { data: dbSchedules } = await supabase.from('schedules').select('*');
        if (dbSchedules) setSchedules(dbSchedules as ScheduledClass[]);
        else setSchedules(MOCK_SCHEDULES);

        const { data: dbPayments } = await supabase.from('payments').select('*');
        if (dbPayments) setPayments(dbPayments as Payment[]);
        else setPayments(MOCK_PAYMENTS);

        const { data: dbMaterials } = await supabase.from('materials').select('*');
        if (dbMaterials) setMaterials(dbMaterials as Material[]);
        else setMaterials(MOCK_MATERIALS);
      } catch (err) {
        console.error("Erro Supabase:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem('hinos_current_user');
    if (savedUser) setUser(JSON.parse(savedUser));
  }, []);

  const handleLogin = (email: string, role: UserRole) => {
    let loggedUser: User | undefined;
    if (role === 'ADMIN') {
      if (MOCK_ADMIN.email === email) loggedUser = MOCK_ADMIN;
    } else {
      loggedUser = students.find(s => s.email.toLowerCase() === email.toLowerCase());
    }
    if (loggedUser) {
      setUser(loggedUser);
      localStorage.setItem('hinos_current_user', JSON.stringify(loggedUser));
    } else {
      alert("E-mail não cadastrado!");
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('hinos_current_user');
  };

  const addStudent = async (newStudent: User) => {
    const { error } = await supabase.from('profiles').insert([newStudent]);
    if (!error) setStudents(prev => [...prev, newStudent]);
  };

  const updateStudent = async (updatedUser: User) => {
    const { error } = await supabase.from('profiles').update(updatedUser).eq('id', updatedUser.id);
    if (!error) setStudents(prev => prev.map(s => s.id === updatedUser.id ? updatedUser : s));
  };

  const addSchedule = async (newClass: ScheduledClass) => {
    const { error } = await supabase.from('schedules').insert([newClass]);
    if (!error) setSchedules(prev => [...prev, newClass]);
  };

  const addCourse = async (newCourse: Course) => {
    const { error } = await supabase.from('courses').insert([newCourse]);
    if (!error) setCourses(prev => [...prev, newCourse]);
  };

  const updateCourse = async (course: Course) => {
    const { error } = await supabase.from('courses').update(course).eq('id', course.id);
    if (!error) setCourses(prev => prev.map(c => c.id === course.id ? course : c));
  };

  const updateCourseAccess = async (courseId: string, studentIds: string[]) => {
    const { error } = await supabase.from('courses').update({ studentIds }).eq('id', courseId);
    if (!error) setCourses(prev => prev.map(c => c.id === courseId ? { ...c, studentIds } : c));
  };

  const addPayment = async (newPayment: Payment) => {
    const { error } = await supabase.from('payments').insert([newPayment]);
    if (!error) setPayments(prev => [...prev, newPayment]);
  };

  if (loading) return (
    <div className="flex h-screen items-center justify-center bg-white">
      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-red-600"></div>
    </div>
  );

  if (!user) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard 
          user={user} 
          onLogout={handleLogout}
          students={students}
          courses={courses}
          schedules={schedules}
          payments={payments}
          materials={materials}
          onAddStudent={addStudent}
          onUpdateStudent={updateStudent}
          onAddSchedule={addSchedule}
          onAddCourse={addCourse}
          onUpdateCourseContent={updateCourse}
          onUpdateCourseAccess={updateCourseAccess}
          onAddPayment={addPayment}
        />
      ) : (
        <StudentDashboard 
          user={user} 
          onLogout={handleLogout}
          courses={courses}
          schedules={schedules}
          materials={materials}
          payments={payments}
          onUpdateProfile={updateStudent}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level, Module, Lesson } from '../types';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => Promise<void>;
  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onAddCourse: (c: Course) => Promise<void>;
  onUpdateCourseContent: (c: Course) => Promise<void>;
  onUpdateCourseAccess: (id: string, ids: string[]) => Promise<void>;
  onAddPayment: (p: Payment) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);

  // States para Formulários
  const [showCourseForm, setShowCourseForm] = useState(false);
  const [showScheduleForm, setShowScheduleForm] = useState(false);
  const [showPaymentForm, setShowPaymentForm] = useState(false);

  // Stats Financeiras
  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  const annualTotal = payments.filter(p => p.status === 'PAID' && new Date(p.dueDate).getFullYear() === currentYear).reduce((acc, curr) => acc + curr.amount, 0);
  const monthlyTotal = payments.filter(p => p.status === 'PAID' && new Date(p.dueDate).getMonth() === currentMonth).reduce((acc, curr) => acc + curr.amount, 0);

  const paidStudents = students.filter(s => payments.some(p => p.studentId === s.id && p.status === 'PAID' && new Date(p.dueDate).getMonth() === currentMonth));
  const pendingStudents = students.filter(s => !paidStudents.find(ps => ps.id === s.id));

  // Handlers para Cursos
  const handleAddCourse = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newCourse: Course = {
      id: `course-${Date.now()}`,
      title: fd.get('title') as string,
      instrument: fd.get('instrument') as Instrument,
      level: fd.get('level') as Level,
      description: fd.get('description') as string,
      modules: [],
      studentIds: []
    };
    setIsSyncing(true);
    await onAddCourse(newCourse);
    setIsSyncing(false);
    setShowCourseForm(false);
  };

  const handleAddModule = async (courseId: string) => {
    const title = prompt("Título do novo módulo:");
    if (!title) return;
    const course = courses.find(c => c.id === courseId);
    if (!course) return;
    const updatedCourse = {
      ...course,
      modules: [...course.modules, { id: `mod-${Date.now()}`, title, lessons: [] }]
    };
    setIsSyncing(true);
    await onUpdateCourseContent(updatedCourse);
    setIsSyncing(false);
  };

  const handleAddLesson = async (courseId: string, moduleId: string) => {
    const title = prompt("Título da aula:");
    if (!title) return;
    const course = courses.find(c => c.id === courseId);
    if (!course) return;

    const newLesson: Lesson = {
      id: `lesson-${Date.now()}`,
      title,
      videoArranjoUrl: prompt("URL do Vídeo Arranjo (Youtube Embed):", "https://www.youtube.com/embed/...") || "",
      videoAoVivoUrl: prompt("URL do Vídeo Ao Vivo (Youtube Embed):", "https://www.youtube.com/embed/...") || "",
      description: prompt("Descrição da aula:") || ""
    };

    const updatedCourse = {
      ...course,
      modules: course.modules.map(m => m.id === moduleId ? { ...m, lessons: [...m.lessons, newLesson] } : m)
    };
    setIsSyncing(true);
    await onUpdateCourseContent(updatedCourse);
    setIsSyncing(false);
  };

  // Handler para Agenda
  const handleAddSchedule = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newSchedule: ScheduledClass = {
      id: `sc-${Date.now()}`,
      studentId: fd.get('studentId') as string,
      teacherId: user.id,
      date: fd.get('date') as string,
      time: fd.get('time') as string,
      status: 'CONFIRMED',
      instrument: fd.get('instrument') as Instrument
    };
    setIsSyncing(true);
    await onAddSchedule(newSchedule);
    setIsSyncing(false);
    setShowScheduleForm(false);
  };

  // Handler para Pagamentos
  const handleAddPayment = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newPayment: Payment = {
      id: `pay-${Date.now()}`,
      studentId: fd.get('studentId') as string,
      amount: Number(fd.get('amount')),
      status: fd.get('status') as any,
      dueDate: fd.get('dueDate') as string
    };
    setIsSyncing(true);
    await onAddPayment(newPayment);
    setIsSyncing(false);
    setShowPaymentForm(false);
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      {/* Sidebar */}
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800">
        <div className="p-8">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase">ADMIN</h2>
        </div>
        <nav className="flex-1 px-4 space-y-1">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos & Aulas" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-6 border-t border-gray-800">
          <button onClick={onLogout} className="text-xs font-black uppercase text-gray-500 hover:text-white transition-colors">Sair</button>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        {/* Header de Status */}
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-black uppercase tracking-tighter">
            {activeView === 'students' && "Gestão de Alunos"}
            {activeView === 'courses' && "Editor de Cursos"}
            {activeView === 'schedules' && "Agenda de Mentorias"}
            {activeView === 'payments' && "Controle Financeiro"}
          </h1>
          <div className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest ${isSyncing ? 'bg-yellow-500 text-black animate-pulse' : 'bg-green-600 text-white'}`}>
            {isSyncing ? "Sincronizando..." : "Conectado ao Supabase"}
          </div>
        </div>

        {/* VIEW: FINANCEIRO */}
        {activeView === 'payments' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-black text-white p-10 rounded-[2.5rem] shadow-xl">
                 <p className="text-[10px] font-black uppercase text-red-600 tracking-widest mb-2">Faturamento Anual ({currentYear})</p>
                 <p className="text-4xl font-black">R$ {annualTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
              <div className="bg-white border-2 border-gray-100 p-10 rounded-[2.5rem] shadow-sm">
                 <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-2">Mês Atual</p>
                 <p className="text-4xl font-black text-black">R$ {monthlyTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
            </div>

            <div className="flex justify-end">
              <button onClick={() => setShowPaymentForm(true)} className="bg-red-600 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all">+ Registrar Pagamento</button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white border border-gray-100 rounded-[2rem] p-8 shadow-sm">
                 <h3 className="text-sm font-black uppercase text-green-600 mb-6 tracking-widest border-b pb-4">Pagamentos em Dia ({paidStudents.length})</h3>
                 <div className="space-y-4">
                   {paidStudents.map(s => (
                     <div key={s.id} className="flex items-center justify-between bg-gray-50 p-4 rounded-2xl">
                       <span className="text-xs font-bold uppercase">{s.name}</span>
                       <span className="text-[9px] font-black uppercase bg-green-100 text-green-700 px-3 py-1 rounded-full">Liquidado</span>
                     </div>
                   ))}
                 </div>
              </div>
              <div className="bg-white border border-gray-100 rounded-[2rem] p-8 shadow-sm">
                 <h3 className="text-sm font-black uppercase text-red-600 mb-6 tracking-widest border-b pb-4">Aguardando Pagamento ({pendingStudents.length})</h3>
                 <div className="space-y-4">
                   {pendingStudents.map(s => (
                     <div key={s.id} className="flex items-center justify-between bg-gray-50 p-4 rounded-2xl">
                       <span className="text-xs font-bold uppercase">{s.name}</span>
                       <span className="text-[9px] font-black uppercase bg-red-100 text-red-700 px-3 py-1 rounded-full">Pendente</span>
                     </div>
                   ))}
                 </div>
              </div>
            </div>
          </div>
        )}

        {/* VIEW: AGENDA */}
        {activeView === 'schedules' && (
          <div className="space-y-8">
            <div className="flex justify-end">
              <button onClick={() => setShowScheduleForm(true)} className="bg-black text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-600 transition-all">+ Nova Mentoria</button>
            </div>

            <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden shadow-sm">
              <table className="w-full text-left">
                <thead className="bg-gray-50 text-[10px] font-black uppercase text-gray-400 tracking-widest border-b">
                  <tr>
                    <th className="px-8 py-4">Data/Hora</th>
                    <th className="px-8 py-4">Aluno</th>
                    <th className="px-8 py-4">Instrumento</th>
                    <th className="px-8 py-4">Ação</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {schedules.sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime()).map(sc => {
                    const student = students.find(s => s.id === sc.studentId);
                    return (
                      <tr key={sc.id} className="hover:bg-gray-50 transition-colors">
                        <td className="px-8 py-6">
                           <p className="text-xs font-black uppercase">{new Date(sc.date).toLocaleDateString()}</p>
                           <p className="text-[10px] font-bold text-red-600">{sc.time}</p>
                        </td>
                        <td className="px-8 py-6 text-xs font-bold uppercase">{student?.name || '---'}</td>
                        <td className="px-8 py-6 text-[10px] font-black uppercase text-gray-500">{sc.instrument}</td>
                        <td className="px-8 py-6">
                           <button className="text-xs font-black text-red-600 uppercase hover:underline">Cancelar</button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* VIEW: CURSOS */}
        {activeView === 'courses' && (
          <div className="space-y-10">
            <div className="flex justify-end">
              <button onClick={() => setShowCourseForm(true)} className="bg-red-600 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all">+ Criar Novo Curso</button>
            </div>

            <div className="grid grid-cols-1 gap-12">
              {courses.map(course => (
                <div key={course.id} className="bg-white border-2 border-gray-100 rounded-[3rem] p-10 shadow-sm">
                  <div className="flex justify-between items-start mb-10">
                    <div>
                      <h2 className="text-2xl font-black uppercase tracking-tighter">{course.title}</h2>
                      <p className="text-xs font-bold text-red-600 uppercase tracking-widest mt-1">{course.instrument} • {course.level}</p>
                    </div>
                    <button onClick={() => handleAddModule(course.id)} className="bg-black text-white px-6 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-red-600 transition-colors">+ Novo Módulo</button>
                  </div>

                  <div className="space-y-6">
                    {course.modules.length > 0 ? (
                      course.modules.map(mod => (
                        <div key={mod.id} className="bg-gray-50 p-6 rounded-[2rem] border border-gray-100">
                           <div className="flex justify-between items-center mb-6">
                              <h3 className="text-xs font-black uppercase text-gray-400 tracking-widest">{mod.title}</h3>
                              <button onClick={() => handleAddLesson(course.id, mod.id)} className="text-[9px] font-black uppercase text-red-600 hover:underline">+ Adicionar Aula</button>
                           </div>
                           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                             {mod.lessons.map(lesson => (
                               <div key={lesson.id} className="bg-white p-4 rounded-2xl border border-gray-100 flex items-center justify-between">
                                 <div>
                                    <p className="text-[10px] font-black uppercase">{lesson.title}</p>
                                    <p className="text-[8px] text-gray-400 font-bold uppercase truncate max-w-[150px]">{lesson.description}</p>
                                 </div>
                                 <div className="flex space-x-2">
                                    <button className="p-2 hover:bg-gray-100 rounded-lg text-xs" title="Editar">✏️</button>
                                    <button className="p-2 hover:bg-red-50 rounded-lg text-xs" title="Excluir">🗑️</button>
                                 </div>
                               </div>
                             ))}
                           </div>
                        </div>
                      ))
                    ) : (
                      <p className="text-center py-10 text-[10px] font-black uppercase text-gray-300">Este curso ainda não possui módulos.</p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* VIEW: ALUNOS (Mantida simplificada) */}
        {activeView === 'students' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {students.map(s => (
              <div key={s.id} className="p-8 bg-white border border-gray-100 rounded-[2.5rem] shadow-sm hover:border-red-600 transition-all">
                <div className="flex items-center space-x-4 mb-6">
                  <img src={s.avatar} className="w-16 h-16 rounded-full border-4 border-gray-50" />
                  <div>
                    <h3 className="font-black uppercase text-sm tracking-tight">{s.name}</h3>
                    <p className="text-[10px] font-bold text-red-600 uppercase">{s.instrument} • {s.level}</p>
                  </div>
                </div>
                <div className="flex space-x-1">
                   {s.currentCycle?.map(l => (
                     <div key={l.id} className={`h-1 flex-1 rounded-full ${l.completed ? 'bg-green-500' : 'bg-gray-100'}`}></div>
                   ))}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* MODAL: NOVO CURSO */}
        {showCourseForm && (
          <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] overflow-hidden">
               <div className="p-8 bg-black text-white flex justify-between items-center">
                  <h3 className="text-xl font-black uppercase">Novo Curso</h3>
                  <button onClick={() => setShowCourseForm(false)} className="text-2xl">&times;</button>
               </div>
               <form onSubmit={handleAddCourse} className="p-10 space-y-6">
                  <div>
                    <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Título</label>
                    <input name="title" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Instrumento</label>
                      <select name="instrument" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                        <option value="Violão">Violão</option>
                        <option value="Piano">Piano</option>
                      </select>
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Nível</label>
                      <select name="level" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                        <option value="NZ">NZ</option>
                        <option value="N1">N1</option>
                        <option value="N2">N2</option>
                        <option value="N3">N3</option>
                      </select>
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Descrição</label>
                    <textarea name="description" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" rows={3}></textarea>
                  </div>
                  <button type="submit" className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-black transition-all">Salvar Curso</button>
               </form>
            </div>
          </div>
        )}

        {/* MODAL: NOVA MENTORIA */}
        {showScheduleForm && (
          <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] overflow-hidden">
               <div className="p-8 bg-black text-white flex justify-between items-center">
                  <h3 className="text-xl font-black uppercase">Agendar Mentoria</h3>
                  <button onClick={() => setShowScheduleForm(false)} className="text-2xl">&times;</button>
               </div>
               <form onSubmit={handleAddSchedule} className="p-10 space-y-6">
                  <div>
                    <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Aluno</label>
                    <select name="studentId" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                      {students.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Data</label>
                      <input name="date" type="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Hora</label>
                      <input name="time" type="time" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Instrumento</label>
                    <select name="instrument" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                      <option value="Violão">Violão</option>
                      <option value="Piano">Piano</option>
                    </select>
                  </div>
                  <button type="submit" className="w-full bg-black text-white py-5 rounded-3xl text-xs font-black uppercase tracking-widest hover:bg-red-600 transition-all">Confirmar Agendamento</button>
               </form>
            </div>
          </div>
        )}

        {/* MODAL: PAGAMENTO */}
        {showPaymentForm && (
          <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] overflow-hidden">
               <div className="p-8 bg-red-600 text-white flex justify-between items-center">
                  <h3 className="text-xl font-black uppercase">Registrar Recebimento</h3>
                  <button onClick={() => setShowPaymentForm(false)} className="text-2xl">&times;</button>
               </div>
               <form onSubmit={handleAddPayment} className="p-10 space-y-6">
                  <div>
                    <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Aluno</label>
                    <select name="studentId" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                      {students.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Valor (R$)</label>
                      <input name="amount" type="number" step="0.01" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" placeholder="150.00" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Data</label>
                      <input name="dueDate" type="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Status</label>
                    <select name="status" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                      <option value="PAID">Pago / Liquidado</option>
                      <option value="PENDING">Pendente</option>
                    </select>
                  </div>
                  <button type="submit" className="w-full bg-black text-white py-5 rounded-3xl text-xs font-black uppercase tracking-widest hover:bg-green-600 transition-all">Salvar Registro</button>
               </form>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center px-4 py-4 text-[10px] font-black uppercase tracking-widest rounded-2xl transition-all ${
      active ? 'bg-red-600 text-white shadow-lg' : 'text-gray-500 hover:text-white hover:bg-gray-900'
    }`}
  >
    <span className="mr-3 text-lg">{icon}</span>
    {label}
  </button>
);

export default AdminDashboard;

import React, { useState } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level, Module, Lesson } from '../types';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => Promise<void>;
  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onAddCourse: (c: Course) => Promise<void>;
  onUpdateCourseContent: (c: Course) => Promise<void>;
  onUpdateCourseAccess: (id: string, ids: string[]) => Promise<void>;
  onAddPayment: (p: Payment) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);

  const [showCourseForm, setShowCourseForm] = useState(false);
  const [showScheduleForm, setShowScheduleForm] = useState(false);
  const [showPaymentForm, setShowPaymentForm] = useState(false);

  // --- CÁLCULOS FINANCEIROS ---
  const now = new Date();
  const currentMonth = now.getMonth();
  const currentYear = now.getFullYear();

  // Total Anual (Apenas Pagos no ano atual)
  const annualTotal = payments
    .filter(p => p.status === 'PAID' && new Date(p.due_date || p.dueDate).getFullYear() === currentYear)
    .reduce((acc, curr) => acc + curr.amount, 0);

  // Total Mensal (Apenas Pagos no mês atual)
  const monthlyTotal = payments
    .filter(p => p.status === 'PAID' && new Date(p.due_date || p.dueDate).getMonth() === currentMonth)
    .reduce((acc, curr) => acc + curr.amount, 0);

  // Alunos em Dia (Pagaram alguma parcela no mês atual ou não têm parcelas vencidas)
  const paidThisMonthIds = new Set(
    payments
      .filter(p => p.status === 'PAID' && new Date(p.due_date || p.dueDate).getMonth() === currentMonth)
      .map(p => p.studentId)
  );

  const studentsInDay = students.filter(s => paidThisMonthIds.has(s.id));
  const studentsOverdue = students.filter(s => s.role === 'STUDENT' && !paidThisMonthIds.has(s.id));

  // --- HANDLERS ---
  const handleAddCourse = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newCourse: Course = {
      id: `course-${Date.now()}`,
      title: fd.get('title') as string,
      instrument: fd.get('instrument') as Instrument,
      level: fd.get('level') as Level,
      description: fd.get('description') as string,
      modules: [],
      studentIds: []
    };
    setIsSyncing(true);
    await onAddCourse(newCourse);
    setIsSyncing(false);
    setShowCourseForm(false);
  };

  const handleAddModule = async (courseId: string) => {
    const title = prompt("Título do novo módulo:");
    if (!title) return;
    const course = courses.find(c => c.id === courseId);
    if (!course) return;
    const updatedCourse = {
      ...course,
      modules: [...(course.modules || []), { id: `mod-${Date.now()}`, title, lessons: [] }]
    };
    setIsSyncing(true);
    await onUpdateCourseContent(updatedCourse);
    setIsSyncing(false);
  };

  const handleAddLesson = async (courseId: string, moduleId: string) => {
    const title = prompt("Título da aula:");
    if (!title) return;
    const course = courses.find(c => c.id === courseId);
    if (!course) return;

    const newLesson: Lesson = {
      id: `lesson-${Date.now()}`,
      title,
      videoArranjoUrl: prompt("URL do Vídeo Arranjo (Youtube Embed):", "https://www.youtube.com/embed/...") || "",
      videoAoVivoUrl: prompt("URL do Vídeo Ao Vivo (Youtube Embed):", "https://www.youtube.com/embed/...") || "",
      description: prompt("Descrição da aula:") || ""
    };

    const updatedCourse = {
      ...course,
      modules: course.modules.map(m => m.id === moduleId ? { ...m, lessons: [...m.lessons, newLesson] } : m)
    };
    setIsSyncing(true);
    await onUpdateCourseContent(updatedCourse);
    setIsSyncing(false);
  };

  const handleAddSchedule = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newSchedule: ScheduledClass = {
      id: `sc-${Date.now()}`,
      studentId: fd.get('studentId') as string,
      teacherId: user.id,
      date: fd.get('date') as string,
      time: fd.get('time') as string,
      status: 'CONFIRMED',
      instrument: fd.get('instrument') as Instrument
    };
    setIsSyncing(true);
    await onAddSchedule(newSchedule);
    setIsSyncing(false);
    setShowScheduleForm(false);
  };

  const handleAddPayment = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newPayment: Payment = {
      id: `pay-${Date.now()}`,
      studentId: fd.get('studentId') as string,
      amount: Number(fd.get('amount')),
      status: fd.get('status') as any,
      dueDate: fd.get('dueDate') as string
    };
    setIsSyncing(true);
    await onAddPayment(newPayment);
    setIsSyncing(false);
    setShowPaymentForm(false);
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800">
        <div className="p-8">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase">ADMIN</h2>
        </div>
        <nav className="flex-1 px-4 space-y-1">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos & Aulas" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-6 border-t border-gray-800">
          <button onClick={onLogout} className="text-xs font-black uppercase text-gray-500 hover:text-white transition-colors">Sair</button>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-black uppercase tracking-tighter">
            {activeView === 'students' && "Gestão de Alunos"}
            {activeView === 'courses' && "Editor de Cursos"}
            {activeView === 'schedules' && "Agenda de Mentorias"}
            {activeView === 'payments' && "Controle Financeiro"}
          </h1>
          <div className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest ${isSyncing ? 'bg-yellow-500 text-black animate-pulse' : 'bg-green-600 text-white'}`}>
            {isSyncing ? "Sincronizando..." : "Supabase Online"}
          </div>
        </div>

        {/* VIEW: FINANCEIRO */}
        {activeView === 'payments' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-black text-white p-10 rounded-[2.5rem] shadow-xl relative overflow-hidden group">
                 <div className="absolute -right-10 -bottom-10 text-9xl text-white/5 font-black group-hover:scale-110 transition-transform">{currentYear}</div>
                 <p className="text-[10px] font-black uppercase text-red-600 tracking-widest mb-2">Acumulado Anual</p>
                 <p className="text-5xl font-black">R$ {annualTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
              <div className="bg-white border-2 border-gray-100 p-10 rounded-[2.5rem] shadow-sm relative overflow-hidden group">
                 <div className="absolute -right-10 -bottom-10 text-9xl text-gray-50 font-black group-hover:scale-110 transition-transform">{currentMonth + 1}</div>
                 <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-2">Mensal (Mês Atual)</p>
                 <p className="text-5xl font-black text-black">R$ {monthlyTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
              </div>
            </div>

            <div className="flex justify-end">
              <button onClick={() => setShowPaymentForm(true)} className="bg-red-600 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all shadow-lg">+ Registrar Novo Pagamento</button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white border border-gray-100 rounded-[2rem] p-8 shadow-sm">
                 <div className="flex items-center justify-between mb-6 border-b pb-4">
                    <h3 className="text-sm font-black uppercase text-green-600 tracking-widest">Pagamentos em Dia</h3>
                    <span className="bg-green-100 text-green-700 text-[10px] px-3 py-1 rounded-full font-black">{studentsInDay.length} Alunos</span>
                 </div>
                 <div className="space-y-3">
                   {studentsInDay.length > 0 ? studentsInDay.map(s => (
                     <div key={s.id} className="flex items-center justify-between bg-gray-50 p-4 rounded-2xl border border-gray-100 group hover:border-green-300 transition-all">
                       <div className="flex items-center space-x-3">
                          <img src={s.avatar} className="w-8 h-8 rounded-full border border-gray-200" alt="" />
                          <span className="text-xs font-bold uppercase">{s.name}</span>
                       </div>
                       <span className="text-[9px] font-black uppercase bg-green-200 text-green-800 px-3 py-1 rounded-full">Liquidado</span>
                     </div>
                   )) : (
                     <p className="text-center py-6 text-[10px] font-bold text-gray-400 uppercase">Nenhum registro este mês.</p>
                   )}
                 </div>
              </div>
              <div className="bg-white border border-gray-100 rounded-[2rem] p-8 shadow-sm">
                 <div className="flex items-center justify-between mb-6 border-b pb-4">
                    <h3 className="text-sm font-black uppercase text-red-600 tracking-widest">Aguardando Pagamento</h3>
                    <span className="bg-red-100 text-red-700 text-[10px] px-3 py-1 rounded-full font-black">{studentsOverdue.length} Alunos</span>
                 </div>
                 <div className="space-y-3">
                   {studentsOverdue.length > 0 ? studentsOverdue.map(s => (
                     <div key={s.id} className="flex items-center justify-between bg-gray-50 p-4 rounded-2xl border border-gray-100 group hover:border-red-300 transition-all">
                       <div className="flex items-center space-x-3">
                          <img src={s.avatar} className="w-8 h-8 rounded-full border border-gray-200" alt="" />
                          <span className="text-xs font-bold uppercase">{s.name}</span>
                       </div>
                       <span className="text-[9px] font-black uppercase bg-red-200 text-red-800 px-3 py-1 rounded-full animate-pulse">Pendente</span>
                     </div>
                   )) : (
                     <p className="text-center py-6 text-[10px] font-bold text-gray-400 uppercase">Todos os alunos estão em dia!</p>
                   )}
                 </div>
              </div>
            </div>
          </div>
        )}

        {/* VIEW: CURSOS */}
        {activeView === 'courses' && (
          <div className="space-y-10 animate-in slide-in-from-bottom-4 duration-500">
            <div className="flex justify-end">
              <button onClick={() => setShowCourseForm(true)} className="bg-red-600 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all shadow-lg">+ Criar Novo Curso Master</button>
            </div>

            <div className="grid grid-cols-1 gap-12">
              {courses.length > 0 ? courses.map(course => (
                <div key={course.id} className="bg-white border-2 border-gray-100 rounded-[3rem] p-10 shadow-sm hover:shadow-xl transition-all">
                  <div className="flex justify-between items-start mb-10 border-b border-gray-50 pb-8">
                    <div>
                      <h2 className="text-3xl font-black uppercase tracking-tighter text-black">{course.title}</h2>
                      <div className="flex space-x-2 mt-2">
                        <span className="text-[9px] font-black bg-red-600 text-white px-3 py-1 rounded-full uppercase">{course.instrument}</span>
                        <span className="text-[9px] font-black bg-black text-white px-3 py-1 rounded-full uppercase">Nível {course.level}</span>
                      </div>
                    </div>
                    <div className="flex space-x-2">
                      <button onClick={() => handleAddModule(course.id)} className="bg-black text-white px-6 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-red-600 transition-colors">+ Novo Módulo</button>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {course.modules && course.modules.length > 0 ? course.modules.map(mod => (
                      <div key={mod.id} className="bg-gray-50 p-8 rounded-[2.5rem] border border-gray-100 group hover:bg-white hover:border-red-100 transition-all">
                         <div className="flex justify-between items-center mb-6 border-b pb-4">
                            <h3 className="text-[11px] font-black uppercase text-gray-500 tracking-widest">{mod.title}</h3>
                            <button onClick={() => handleAddLesson(course.id, mod.id)} className="text-[9px] font-black uppercase text-red-600 hover:scale-105 transition-transform">+ Adicionar Aula</button>
                         </div>
                         <div className="space-y-3">
                           {mod.lessons && mod.lessons.map(lesson => (
