                                  <button className="p-2 hover:bg-red-50 rounded-lg text-xs">🗑️</button>
                               </div>
                             </div>
                           ))}
                         </div>
                      </div>
                    )) : (
                      <div className="col-span-2 text-center py-20 bg-gray-50 rounded-[2.5rem] border-2 border-dashed border-gray-200">
