                </div>
              )) : (
                <div className="text-center py-32 bg-white rounded-[3rem] border-2 border-dashed border-gray-100">
                   <p className="text-sm font-black uppercase text-gray-300">Nenhum curso cadastrado ainda.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* VIEW: AGENDA */}
        {activeView === 'schedules' && (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
            <div className="flex justify-end">
              <button onClick={() => setShowScheduleForm(true)} className="bg-black text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-lg">+ Nova Aula Individual</button>
            </div>

            <div className="bg-white border-2 border-gray-50 rounded-[3rem] overflow-hidden shadow-sm">
              <table className="w-full text-left">
                <thead className="bg-black text-[10px] font-black uppercase text-gray-400 tracking-widest">
