                    <th className="px-10 py-6">Data & Hora</th>
                    <th className="px-10 py-6">Estudante</th>
                    <th className="px-10 py-6">Instrumento</th>
                    <th className="px-10 py-6 text-right">Ações</th>
                  </tr>
                </thead>
