                        <option value="Violão">Violão</option>
                        <option value="Piano">Piano</option>
                      </select>
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Nível de Entrada</label>
                      <select name="level" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold outline-none">
                        <option value="NZ">NZ (Nível Zero)</option>
                        <option value="N1">N1 (Iniciante)</option>
                        <option value="N2">N2 (Intermediário)</option>
                        <option value="N3">N3 (Avançado)</option>
                      </select>
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Descrição Curta</label>
                    <textarea name="description" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold outline-none" rows={3} placeholder="Objetivos do curso..."></textarea>
                  </div>
                  <button type="submit" className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-black transition-all">Salvar e Publicar</button>
               </form>
            </div>
          </div>
        )}

        {showPaymentForm && (
          <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-lg rounded-[2.5rem] overflow-hidden animate-in zoom-in">
               <div className="p-8 bg-red-600 text-white flex justify-between items-center">
                  <h3 className="text-xl font-black uppercase tracking-tighter">Lançamento Financeiro</h3>
                  <button onClick={() => setShowPaymentForm(false)} className="text-2xl">&times;</button>
               </div>
