                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Valor do Repasse (R$)</label>
                      <input name="amount" type="number" step="0.01" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold outline-none" placeholder="150.00" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Data de Vencimento</label>
                      <input name="dueDate" type="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold outline-none" />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-gray-400 block mb-1">Estado do Pagamento</label>
                    <select name="status" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold outline-none">
                      <option value="PAID">Pago / Recebido</option>
                      <option value="PENDING">Pendente / Aguardando</option>
                      <option value="OVERDUE">Atrasado / Cobrança</option>
                    </select>
                  </div>
                  <button type="submit" className="w-full bg-black text-white py-5 rounded-3xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-red-600 transition-all">Efetuar Registro</button>
               </form>
            </div>
          </div>
        )}

        {/* Modal de Gestão de Aluno (Ciclo e Perfil) */}
        {editingStudent && (
          <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-2xl rounded-[3rem] overflow-hidden animate-in slide-in-from-top-10 duration-300">
               <div className="p-8 bg-black text-white flex justify-between items-center">
                  <h3 className="text-xl font-black uppercase tracking-tighter">Gerenciar Aluno: {editingStudent.name}</h3>
                  <button onClick={() => setEditingStudent(null)} className="text-2xl">&times;</button>
               </div>
               <div className="p-10 max-h-[70vh] overflow-y-auto custom-scrollbar">
                  <h4 className="text-[10px] font-black uppercase text-red-600 mb-6 tracking-widest border-b pb-2">Controle do Ciclo de Mentoria</h4>
                  <div className="space-y-4 mb-10">
                    {editingStudent.currentCycle?.map(l => (
                      <div key={l.id} className="flex items-center justify-between p-5 bg-gray-50 rounded-[2rem] border border-gray-100">
                         <span className="text-xs font-bold uppercase">{l.title}</span>
                         <button 
                          onClick={() => {
                            const newCycle = editingStudent.currentCycle?.map(item => item.id === l.id ? {...item, completed: !item.completed} : item);
                            setEditingStudent({...editingStudent, currentCycle: newCycle});
                          }}
                          className={`px-6 py-2 rounded-xl text-[9px] font-black uppercase transition-all ${l.completed ? 'bg-green-600 text-white' : 'bg-white border-2 border-gray-200 text-gray-400'}`}
                         >
                           {l.completed ? 'Concluída ✓' : 'Marcar Concluída'}
                         </button>
                      </div>
                    ))}
                  </div>
                  <button 
                    onClick={async () => {
                      setIsSyncing(true);
                      await onUpdateStudent(editingStudent);
                      setIsSyncing(false);
                      setEditingStudent(null);
                    }}
                    className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-black transition-all"
                  >
                    Salvar Alterações no Supabase
                  </button>
               </div>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center px-4 py-4 text-[10px] font-black uppercase tracking-widest rounded-2xl transition-all mb-1 ${
      active ? 'bg-red-600 text-white shadow-lg shadow-red-900/20' : 'text-gray-500 hover:text-white hover:bg-gray-900'
    }`}
  >
    <span className="mr-3 text-lg">{icon}</span>
    {label}
  </button>
);

