import React, { useState } from 'react';
import { User, Course, ScheduledClass, Material, Payment } from '../types';
import CoursePlayer from './CoursePlayer';
import { DEFAULT_AVATARS } from '../constants';

interface StudentDashboardProps {
  user: User;
  onLogout: () => void;
  courses: Course[];
  schedules: ScheduledClass[];
  materials: Material[];
  payments: Payment[];
  onUpdateProfile: (user: User) => void;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ 
  user, onLogout, courses, schedules, materials, payments, onUpdateProfile 
}) => {
  const [viewingCourse, setViewingCourse] = useState<Course | null>(null);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileForm, setProfileForm] = useState<User>(user);

  // Fix: Safe access to studentIds to prevent 'includes' error
  const myCourses = courses.filter(c => c.studentIds?.includes(user.id));
  const mySchedules = schedules.filter(s => s.studentId === user.id);
  const myPayments = payments.filter(p => p.studentId === user.id);

  const handleProfileSubmit = (e: React.FormEvent) => {
