import React, { useState } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level, Module, Lesson } from '../types';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => Promise<void>;
  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onAddCourse: (c: Course) => Promise<void>;
  onUpdateCourseContent: (c: Course) => Promise<void>;
  onUpdateCourseAccess: (id: string, ids: string[]) => Promise<void>;
  onAddPayment: (p: Payment) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);

  const [showCourseForm, setShowCourseForm] = useState(false);
  const [showScheduleForm, setShowScheduleForm] = useState(false);
  const [showPaymentForm, setShowPaymentForm] = useState(false);

  // FINANCEIRO LOGIC
  const now = new Date();
  const currentMonth = now.getMonth();
  const currentYear = now.getFullYear();

  const annualTotal = payments
    .filter(p => p.status === 'PAID' && new Date(p.dueDate || (p as any).due_date).getFullYear() === currentYear)
    .reduce((acc, curr) => acc + curr.amount, 0);

  const monthlyTotal = payments
    .filter(p => p.status === 'PAID' && new Date(p.dueDate || (p as any).due_date).getMonth() === currentMonth)
    .reduce((acc, curr) => acc + curr.amount, 0);

  const studentsWhoPaidIds = new Set(
    payments
      .filter(p => p.status === 'PAID' && new Date(p.dueDate || (p as any).due_date).getMonth() === currentMonth)
      .map(p => p.studentId)
  );

  const studentsInDay = students.filter(s => s.role === 'STUDENT' && studentsWhoPaidIds.has(s.id));
  const studentsOverdue = students.filter(s => s.role === 'STUDENT' && !studentsWhoPaidIds.has(s.id));

  // HANDLERS
  const handleAddCourse = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newCourse: Course = {
      id: crypto.randomUUID(),
      title: fd.get('title') as string,
      instrument: fd.get('instrument') as Instrument,
      level: fd.get('level') as Level,
      description: fd.get('description') as string,
      modules: [],
      studentIds: []
    };
    setIsSyncing(true);
    await onAddCourse(newCourse);
    setIsSyncing(false);
    setShowCourseForm(false);
  };

  const handleAddModule = async (courseId: string) => {
    const title = prompt("Título do novo módulo:");
    if (!title) return;
    const course = courses.find(c => c.id === courseId);
    if (!course) return;
    const updatedCourse = { ...course, modules: [...(course.modules || []), { id: crypto.randomUUID(), title, lessons: [] }] };
    setIsSyncing(true);
    await onUpdateCourseContent(updatedCourse);
    setIsSyncing(false);
  };

  const handleAddLesson = async (courseId: string, moduleId: string) => {
    const title = prompt("Título da aula:");
    if (!title) return;
    const course = courses.find(c => c.id === courseId);
    if (!course) return;

    const newLesson: Lesson = {
      id: crypto.randomUUID(),
      title,
      videoArranjoUrl: prompt("Embed URL Youtube Arranjo:", "https://www.youtube.com/embed/...") || "",
      videoAoVivoUrl: prompt("Embed URL Youtube Ao Vivo:", "https://www.youtube.com/embed/...") || "",
      description: prompt("Descrição:") || ""
    };

    const updatedCourse = {
      ...course,
      modules: (course.modules || []).map(m => m.id === moduleId ? { ...m, lessons: [...(m.lessons || []), newLesson] } : m)
    };
    setIsSyncing(true);
    await onUpdateCourseContent(updatedCourse);
    setIsSyncing(false);
  };

  return (
    <div className="flex min-h-screen bg-white">
      {/* Sidebar */}
      <aside className="w-64 bg-black text-white hidden md:flex flex-col">
        <div className="p-8">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase leading-none">Admin<br/>Painel</h2>
        </div>
        <nav className="flex-1 px-4 space-y-2">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-8 border-t border-white/10">
          <button onClick={onLogout} className="text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all">Encerrar Sessão</button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <div className="flex justify-between items-center mb-12">
           <h1 className="text-4xl font-black uppercase tracking-tighter">
             {activeView === 'students' && "Gestão de Alunos"}
             {activeView === 'courses' && "Gestão de Conteúdo"}
             {activeView === 'schedules' && "Agenda de Aulas"}
             {activeView === 'payments' && "Controle de Caixa"}
           </h1>
           <div className={`px-4 py-2 rounded-full text-[9px] font-black uppercase ${isSyncing ? 'bg-yellow-500 animate-pulse' : 'bg-green-600 text-white'}`}>
             {isSyncing ? "Sincronizando..." : "Conectado ao Banco"}
           </div>
        </div>

        {/* VIEW: FINANCEIRO */}
        {activeView === 'payments' && (
          <div className="space-y-12 animate-in fade-in duration-300">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div className="bg-black text-white p-12 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-10 text-white/5 text-8xl font-black">{currentYear}</div>
                  <p className="text-[10px] font-black uppercase text-red-600 tracking-widest mb-4">Faturamento Anual Acumulado</p>
                  <p className="text-6xl font-black">R$ {annualTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
               </div>
               <div className="bg-white border-4 border-gray-100 p-12 rounded-[2.5rem] shadow-sm relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-10 text-gray-50 text-8xl font-black">{currentMonth + 1}</div>
                  <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-4">Total Liquidado (Mês Atual)</p>
                  <p className="text-6xl font-black text-black">R$ {monthlyTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
               </div>
            </div>

            <div className="flex justify-between items-end">
               <h3 className="text-xl font-black uppercase tracking-tight">Status de Alunos</h3>
               <button onClick={() => setShowPaymentForm(true)} className="bg-red-600 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:scale-105 transition-transform">Lançar Pagamento</button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
               <div className="bg-white border-2 border-gray-100 rounded-[2rem] p-8">
                  <h4 className="text-[10px] font-black uppercase text-green-600 mb-6 tracking-widest border-b pb-4">Pagamentos Confirmados ({studentsInDay.length})</h4>
                  <div className="space-y-3">
                    {studentsInDay.map(s => (
                      <div key={s.id} className="flex items-center justify-between bg-gray-50 p-4 rounded-xl">
                        <span className="text-xs font-bold uppercase">{s.name}</span>
                        <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-[9px] font-black">EM DIA</span>
                      </div>
                    ))}
                  </div>
               </div>
               <div className="bg-white border-2 border-gray-100 rounded-[2rem] p-8">
                  <h4 className="text-[10px] font-black uppercase text-red-600 mb-6 tracking-widest border-b pb-4">Aguardando Pagamento ({studentsOverdue.length})</h4>
                  <div className="space-y-3">
                    {studentsOverdue.map(s => (
                      <div key={s.id} className="flex items-center justify-between bg-gray-50 p-4 rounded-xl">
                        <span className="text-xs font-bold uppercase">{s.name}</span>
                        <span className="bg-red-100 text-red-700 px-3 py-1 rounded-full text-[9px] font-black animate-pulse">PENDENTE</span>
                      </div>
                    ))}
                  </div>
               </div>
            </div>
          </div>
        )}

        {/* VIEW: CURSOS */}
        {activeView === 'courses' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-300">
