  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onAddCourse: (c: Course) => Promise<void>;
  onUpdateCourseContent: (c: Course) => Promise<void>;
  onUpdateCourseAccess: (id: string, ids: string[]) => Promise<void>;
  onAddPayment: (p: Payment) => Promise<void>;
  onUpdatePayment: (id: string, updates: Partial<Payment>) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment, onUpdatePayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);

  const [showCourseForm, setShowCourseForm] = useState(false);
  const [showScheduleForm, setShowScheduleForm] = useState(false);
  const [showPaymentForm, setShowPaymentForm] = useState(false);

  // FINANCEIRO LOGIC
  const now = new Date();
  const currentMonth = now.getMonth();
  const currentYear = now.getFullYear();

  // Saldos calculados dinamicamente baseados no estado `payments`
  const annualTotal = payments
    .filter(p => p.status === 'PAID' && new Date(p.dueDate || (p as any).due_date).getFullYear() === currentYear)
    .reduce((acc, curr) => acc + curr.amount, 0);

  const monthlyTotal = payments
    .filter(p => p.status === 'PAID' && new Date(p.dueDate || (p as any).due_date).getMonth() === currentMonth)
    .reduce((acc, curr) => acc + curr.amount, 0);

  const studentsWhoPaidIds = new Set(
    payments
      .filter(p => p.status === 'PAID' && new Date(p.dueDate || (p as any).due_date).getMonth() === currentMonth)
      .map(p => p.studentId)
  );

  const studentsInDay = students.filter(s => s.role === 'STUDENT' && studentsWhoPaidIds.has(s.id));
  const studentsOverdue = students.filter(s => s.role === 'STUDENT' && !studentsWhoPaidIds.has(s.id));

  // HANDLERS
  const handleConfirmPayment = async (paymentId: string) => {
    setIsSyncing(true);
    await onUpdatePayment(paymentId, { status: 'PAID' });
    setIsSyncing(false);
  };

  const handleAddCourse = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newCourse: Course = {
      id: crypto.randomUUID(),
      title: fd.get('title') as string,
      instrument: fd.get('instrument') as Instrument,
      level: fd.get('level') as Level,
      description: fd.get('description') as string,
      modules: [],
      studentIds: []
    };
    setIsSyncing(true);
    await onAddCourse(newCourse);
    setIsSyncing(false);
    setShowCourseForm(false);
  };

  const handleAddModule = async (courseId: string) => {
    const title = prompt("Título do novo módulo:");
    if (!title) return;
    const course = courses.find(c => c.id === courseId);
    if (!course) return;
    const updatedCourse = { ...course, modules: [...(course.modules || []), { id: crypto.randomUUID(), title, lessons: [] }] };
    setIsSyncing(true);
    await onUpdateCourseContent(updatedCourse);
    setIsSyncing(false);
  };

  const handleAddLesson = async (courseId: string, moduleId: string) => {
    const title = prompt("Título da aula:");
    if (!title) return;
    const course = courses.find(c => c.id === courseId);
    if (!course) return;

    const newLesson: Lesson = {
      id: crypto.randomUUID(),
      title,
      videoArranjoUrl: prompt("Embed URL Youtube Arranjo:", "https://www.youtube.com/embed/...") || "",
      videoAoVivoUrl: prompt("Embed URL Youtube Ao Vivo:", "https://www.youtube.com/embed/...") || "",
      description: prompt("Descrição:") || ""
    };

    const updatedCourse = {
      ...course,
      modules: (course.modules || []).map(m => m.id === moduleId ? { ...m, lessons: [...(m.lessons || []), newLesson] } : m)
    };
    setIsSyncing(true);
    await onUpdateCourseContent(updatedCourse);
    setIsSyncing(false);
  };

  return (
    <div className="flex min-h-screen bg-white">
      {/* Sidebar */}
      <aside className="w-64 bg-black text-white hidden md:flex flex-col">
        <div className="p-8">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase leading-none">Admin<br/>Painel</h2>
        </div>
        <nav className="flex-1 px-4 space-y-2">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-8 border-t border-white/10">
          <button onClick={onLogout} className="text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all">Encerrar Sessão</button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <div className="flex justify-between items-center mb-12">
           <h1 className="text-4xl font-black uppercase tracking-tighter">
             {activeView === 'students' && "Gestão de Alunos"}
             {activeView === 'courses' && "Gestão de Conteúdo"}
             {activeView === 'schedules' && "Agenda de Aulas"}
             {activeView === 'payments' && "Controle de Caixa"}
           </h1>
           <div className={`px-4 py-2 rounded-full text-[9px] font-black uppercase ${isSyncing ? 'bg-yellow-500 animate-pulse' : 'bg-green-600 text-white'}`}>
             {isSyncing ? "Sincronizando..." : "Conectado ao Banco"}
           </div>
        </div>

        {/* VIEW: FINANCEIRO */}
        {activeView === 'payments' && (
          <div className="space-y-12 animate-in fade-in duration-300">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div className="bg-black text-white p-12 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-10 text-white/5 text-8xl font-black">{currentYear}</div>
                  <p className="text-[10px] font-black uppercase text-red-600 tracking-widest mb-4">Faturamento Anual Acumulado</p>
                  <p className="text-6xl font-black">R$ {annualTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
               </div>
               <div className="bg-white border-4 border-gray-100 p-12 rounded-[2.5rem] shadow-sm relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-10 text-gray-50 text-8xl font-black">{currentMonth + 1}</div>
                  <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-4">Total Liquidado (Mês Atual)</p>
                  <p className="text-6xl font-black text-black">R$ {monthlyTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
               </div>
            </div>

            <div className="flex justify-between items-end">
               <h3 className="text-xl font-black uppercase tracking-tight">Lançamentos Recentes</h3>
               <button onClick={() => setShowPaymentForm(true)} className="bg-red-600 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:scale-105 transition-transform">Novo Lançamento</button>
            </div>

            <div className="bg-white border-4 border-gray-100 rounded-[3rem] overflow-hidden">
                <table className="w-full text-left">
                   <thead className="bg-black text-white text-[10px] font-black uppercase">
                      <tr>
                        <th className="px-10 py-6">Data Venc.</th>
                        <th className="px-10 py-6">Aluno</th>
                        <th className="px-10 py-6">Valor</th>
                        <th className="px-10 py-6">Status</th>
                        <th className="px-10 py-6 text-right">Ação</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-gray-100">
                      {payments.length > 0 ? [...payments].sort((a,b) => new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime()).map(p => {
                        const student = students.find(s => s.id === p.studentId);
                        return (
                          <tr key={p.id} className="hover:bg-gray-50 transition-colors">
                            <td className="px-10 py-6 text-xs font-bold">{new Date(p.dueDate).toLocaleDateString()}</td>
                            <td className="px-10 py-6 text-xs font-black uppercase">{student?.name || "---"}</td>
                            <td className="px-10 py-6 text-xs font-black">R$ {p.amount.toFixed(2)}</td>
                            <td className="px-10 py-6">
                               <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase ${p.status === 'PAID' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                                 {p.status === 'PAID' ? 'Confirmado' : 'Pendente'}
                               </span>
                            </td>
                            <td className="px-10 py-6 text-right">
                               {p.status === 'PENDING' && (
                                 <button 
                                  onClick={() => handleConfirmPayment(p.id)}
                                  className="bg-black text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase hover:bg-green-600 transition-colors"
                                 >
                                   Confirmar
                                 </button>
                               )}
                            </td>
                          </tr>
                        );
                      }) : (
                        <tr><td colSpan={5} className="text-center py-10 text-gray-300 font-black uppercase text-xs">Nenhum pagamento registrado.</td></tr>
                      )}
                   </tbody>
                </table>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
               <div className="bg-white border-2 border-gray-100 rounded-[2rem] p-8">
                  <h4 className="text-[10px] font-black uppercase text-green-600 mb-6 tracking-widest border-b pb-4">Alunos com Mês Pago ({studentsInDay.length})</h4>
                  <div className="space-y-3">
                    {studentsInDay.map(s => (
                      <div key={s.id} className="flex items-center justify-between bg-gray-50 p-4 rounded-xl">
                        <span className="text-xs font-bold uppercase">{s.name}</span>
                        <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-[9px] font-black">EM DIA</span>
                      </div>
                    ))}
                  </div>
               </div>
               <div className="bg-white border-2 border-gray-100 rounded-[2rem] p-8">
                  <h4 className="text-[10px] font-black uppercase text-red-600 mb-6 tracking-widest border-b pb-4">Alunos Inadimplentes ({studentsOverdue.length})</h4>
                  <div className="space-y-3">
                    {studentsOverdue.map(s => (
                      <div key={s.id} className="flex items-center justify-between bg-gray-50 p-4 rounded-xl">
                        <span className="text-xs font-bold uppercase">{s.name}</span>
                        <span className="bg-red-100 text-red-700 px-3 py-1 rounded-full text-[9px] font-black animate-pulse">PENDENTE</span>
                      </div>
                    ))}
                  </div>
               </div>
            </div>
          </div>
        )}

        {/* VIEW: CURSOS */}
        {activeView === 'courses' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-300">
            <div className="flex justify-end">
               <button onClick={() => setShowCourseForm(true)} className="bg-black text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-600 transition-colors">+ Criar Novo Curso</button>
            </div>

            <div className="grid grid-cols-1 gap-10">
              {courses.map(course => (
                <div key={course.id} className="bg-white border-4 border-gray-100 rounded-[3rem] p-10 hover:border-red-600 transition-colors">
                  <div className="flex justify-between items-start mb-8">
                     <div>
                        <h2 className="text-3xl font-black uppercase tracking-tighter">{course.title}</h2>
                        <div className="flex space-x-2 mt-2">
                           <span className="bg-red-600 text-white px-3 py-1 rounded-full text-[9px] font-black uppercase">{course.instrument}</span>
                           <span className="bg-black text-white px-3 py-1 rounded-full text-[9px] font-black uppercase">Nível {course.level}</span>
                        </div>
                     </div>
                     <button onClick={() => handleAddModule(course.id)} className="text-[10px] font-black uppercase text-red-600 border-b-2 border-red-600">+ Novo Módulo</button>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {course.modules?.map(mod => (
                      <div key={mod.id} className="bg-gray-50 p-6 rounded-[2rem]">
                        <div className="flex justify-between items-center mb-4">
                           <h4 className="text-xs font-black uppercase text-gray-400">{mod.title}</h4>
                           <button onClick={() => handleAddLesson(course.id, mod.id)} className="text-[9px] font-black uppercase bg-white px-3 py-1 rounded-lg">+ Aula</button>
                        </div>
                        <div className="space-y-2">
                           {mod.lessons?.map(lesson => (
                             <div key={lesson.id} className="bg-white p-3 rounded-xl border border-gray-100 flex justify-between items-center">
                                <span className="text-[10px] font-bold uppercase">{lesson.title}</span>
                                <div className="flex space-x-2">
                                   <button className="text-[10px]">✏️</button>
                                   <button className="text-[10px]">🗑️</button>
                                </div>
                             </div>
                           ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* VIEW: AGENDA */}
        {activeView === 'schedules' && (
           <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
             <div className="flex justify-end">
                <button onClick={() => setShowScheduleForm(true)} className="bg-red-600 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-black transition-colors">+ Agendar Nova Aula</button>
             </div>
             <div className="bg-white border-4 border-gray-100 rounded-[3rem] overflow-hidden">
                <table className="w-full text-left">
                   <thead className="bg-black text-white">
                      <tr>
                        <th className="px-10 py-6 text-[10px] font-black uppercase">Data / Hora</th>
                        <th className="px-10 py-6 text-[10px] font-black uppercase">Aluno</th>
                        <th className="px-10 py-6 text-[10px] font-black uppercase">Instrumento</th>
                        <th className="px-10 py-6 text-[10px] font-black uppercase text-right">Status</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-gray-100">
                      {schedules.map(sc => {
                        const student = students.find(s => s.id === sc.studentId);
                        return (
                          <tr key={sc.id} className="hover:bg-gray-50 transition-colors">
                            <td className="px-10 py-6">
                               <p className="text-xs font-black uppercase">{new Date(sc.date).toLocaleDateString()}</p>
                               <p className="text-lg font-black text-red-600">{sc.time}</p>
                            </td>
                            <td className="px-10 py-6 font-bold uppercase text-xs">{student?.name || "Aluno Removido"}</td>
                            <td className="px-10 py-6 text-[10px] font-black uppercase text-gray-400">{sc.instrument}</td>
                            <td className="px-10 py-6 text-right">
                               <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-[9px] font-black uppercase">Confirmada</span>
                            </td>
                          </tr>
                        );
                      })}
                   </tbody>
                </table>
             </div>
           </div>
        )}

        {/* VIEW: ALUNOS (MANTIDA) */}
        {activeView === 'students' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 animate-in zoom-in duration-300">
            {students.length > 0 ? students.map(s => (
              <div key={s.id} className="p-10 bg-white border border-gray-100 rounded-[3rem] shadow-sm hover:border-red-600 transition-all group relative overflow-hidden">
                <div className="flex flex-col items-center mb-8">
                  <div className="relative mb-4">
                    <img src={s.avatar} className="w-24 h-24 rounded-full border-4 border-gray-50 group-hover:border-red-600 transition-colors shadow-lg" alt="" />
                  </div>
                  <h3 className="font-black uppercase text-lg tracking-tight text-center">{s.name}</h3>
                  <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">{s.instrument} • NÍVEL {s.level}</p>
                </div>
                <div className="space-y-4">
                   <div className="flex justify-between items-center text-[9px] font-black uppercase text-gray-400">
                      <span>Progresso do Ciclo</span>
                      <span className="text-red-600">{s.currentCycle?.filter(l => l.completed).length || 0}/4</span>
                   </div>
                   <div className="flex space-x-2">
                      {s.currentCycle?.map(l => (
                        <div key={l.id} className={`h-2 flex-1 rounded-full ${l.completed ? 'bg-red-600' : 'bg-gray-100'}`}></div>
                      ))}
                   </div>
                   <button onClick={() => setEditingStudent(s)} className="w-full mt-6 bg-black text-white py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-red-600 transition-all">Gerenciar Perfil</button>
                </div>
              </div>
            )) : <p className="col-span-3 text-center py-20 text-gray-300 font-black uppercase">Carregando alunos...</p>}
          </div>
        )}

        {/* MODAL: NOVO CURSO */}
        {showCourseForm && (
          <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
            <form onSubmit={handleAddCourse} className="bg-white w-full max-w-lg rounded-[2.5rem] p-12 space-y-6">
               <h3 className="text-2xl font-black uppercase mb-8 border-b-4 border-red-600 pb-2">Novo Curso</h3>
               <input name="title" required placeholder="Título do Curso" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
               <div className="grid grid-cols-2 gap-4">
                  <select name="instrument" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                     <option value="Violão">Violão</option>
                     <option value="Piano">Piano</option>
                  </select>
                  <select name="level" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                     <option value="NZ">Nível Zero</option>
                     <option value="N1">Nível 1</option>
                     <option value="N2">Nível 2</option>
                     <option value="N3">Nível 3</option>
                  </select>
               </div>
               <textarea name="description" placeholder="Resumo do curso" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" rows={3}></textarea>
               <div className="flex space-x-4 pt-4">
                  <button type="button" onClick={() => setShowCourseForm(false)} className="flex-1 py-4 text-[10px] font-black uppercase text-gray-400">Cancelar</button>
                  <button type="submit" className="flex-1 bg-red-600 text-white py-4 rounded-2xl text-[10px] font-black uppercase">Publicar Curso</button>
               </div>
            </form>
          </div>
        )}

        {/* MODAL: AGENDAR AULA */}
        {showScheduleForm && (
           <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
             <form onSubmit={async (e) => {
               e.preventDefault();
               const fd = new FormData(e.currentTarget);
               setIsSyncing(true);
               await onAddSchedule({
                 id: crypto.randomUUID(),
                 studentId: fd.get('studentId') as string,
                 teacherId: user.id,
                 date: fd.get('date') as string,
                 time: fd.get('time') as string,
                 instrument: fd.get('instrument') as Instrument,
                 status: 'CONFIRMED'
               });
               setIsSyncing(false);
               setShowScheduleForm(false);
             }} className="bg-white w-full max-w-lg rounded-[2.5rem] p-12 space-y-6">
                <h3 className="text-2xl font-black uppercase mb-8 border-b-4 border-black pb-2">Agendar Mentoria</h3>
                <select name="studentId" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                   {students.filter(s => s.role === 'STUDENT').map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
                <div className="grid grid-cols-2 gap-4">
                   <input name="date" type="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                   <input name="time" type="time" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                </div>
                <select name="instrument" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                   <option value="Violão">Violão</option>
                   <option value="Piano">Piano</option>
                </select>
                <button type="submit" className="w-full bg-black text-white py-5 rounded-2xl text-[10px] font-black uppercase tracking-widest">Confirmar na Agenda</button>
                <button type="button" onClick={() => setShowScheduleForm(false)} className="w-full py-4 text-[10px] font-black uppercase text-gray-400">Sair sem salvar</button>
             </form>
           </div>
        )}

        {/* MODAL: PAGAMENTO */}
        {showPaymentForm && (
           <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
             <form onSubmit={async (e) => {
                e.preventDefault();
                const fd = new FormData(e.currentTarget);
                setIsSyncing(true);
                await onAddPayment({
                  id: crypto.randomUUID(),
                  studentId: fd.get('studentId') as string,
                  amount: Number(fd.get('amount')),
                  dueDate: fd.get('dueDate') as string,
                  status: fd.get('status') as any
                });
                setIsSyncing(false);
                setShowPaymentForm(false);
             }} className="bg-white w-full max-w-lg rounded-[2.5rem] p-12 space-y-6">
                <h3 className="text-2xl font-black uppercase mb-8 border-b-4 border-green-600 pb-2">Lançar Pagamento</h3>
                <select name="studentId" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                   {students.filter(s => s.role === 'STUDENT').map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
                <div className="grid grid-cols-2 gap-4">
                   <input name="amount" type="number" required placeholder="Valor (Ex: 150)" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                   <input name="dueDate" type="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                </div>
                <select name="status" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                   <option value="PENDING">Aguardando Pagamento</option>
                   <option value="PAID">Já Recebido (Confirmado)</option>
                </select>
                <button type="submit" className="w-full bg-green-600 text-white py-5 rounded-2xl text-[10px] font-black uppercase tracking-widest">Registrar Pagamento</button>
                <button type="button" onClick={() => setShowPaymentForm(false)} className="w-full py-4 text-[10px] font-black uppercase text-gray-400">Fechar</button>
             </form>
           </div>
        )}

        {/* Modal de Gestão de Aluno (MANTIDA) */}
        {editingStudent && (
          <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-2xl rounded-[3rem] overflow-hidden">
               <div className="p-8 bg-black text-white flex justify-between items-center">
                  <h3 className="text-xl font-black uppercase tracking-tighter">Gerenciar: {editingStudent.name}</h3>
                  <button onClick={() => setEditingStudent(null)} className="text-2xl">&times;</button>
               </div>
               <div className="p-10 max-h-[70vh] overflow-y-auto custom-scrollbar">
                  <h4 className="text-[10px] font-black uppercase text-red-600 mb-6 tracking-widest border-b pb-2">Controle do Ciclo</h4>
                  <div className="space-y-4 mb-10">
                    {editingStudent.currentCycle?.map(l => (
                      <div key={l.id} className="flex items-center justify-between p-5 bg-gray-50 rounded-[2rem] border border-gray-100">
                         <span className="text-xs font-bold uppercase">{l.title}</span>
                         <button 
                          onClick={() => {
                            const newCycle = editingStudent.currentCycle?.map(item => item.id === l.id ? {...item, completed: !item.completed} : item);
                            setEditingStudent({...editingStudent, currentCycle: newCycle});
                          }}
                          className={`px-6 py-2 rounded-xl text-[9px] font-black uppercase transition-all ${l.completed ? 'bg-green-600 text-white' : 'bg-white border-2 border-gray-200 text-gray-400'}`}
                         >
                           {l.completed ? 'Concluída ✓' : 'Marcar'}
                         </button>
                      </div>
                    ))}
                  </div>
                  <button 
                    onClick={async () => {
                      setIsSyncing(true);
                      await onUpdateStudent(editingStudent);
                      setIsSyncing(false);
                      setEditingStudent(null);
                    }}
                    className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase shadow-xl hover:bg-black transition-all"
                  >
                    Salvar Alterações
                  </button>
               </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

