  const [showCourseForm, setShowCourseForm] = useState(false);
  const [showScheduleForm, setShowScheduleForm] = useState(false);
  const [showPaymentForm, setShowPaymentForm] = useState(false);

  // --- CALCULOS REATIVOS (Aparecem na hora que você clica em confirmar) ---
  const { annualTotal, monthlyTotal, studentsWhoPaidIds } = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const annual = payments
      .filter(p => p.status === 'PAID' && new Date(p.dueDate).getFullYear() === currentYear)
      .reduce((acc, curr) => acc + curr.amount, 0);

    const monthly = payments
      .filter(p => {
        const d = new Date(p.dueDate);
        return p.status === 'PAID' && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + curr.amount, 0);

    const paidIds = new Set(
      payments
        .filter(p => {
          const d = new Date(p.dueDate);
          return p.status === 'PAID' && d.getMonth() === currentMonth;
        })
        .map(p => p.studentId)
    );

    return { annualTotal: annual, monthlyTotal: monthly, studentsWhoPaidIds: paidIds };
  }, [payments]);

  const studentsInDay = students.filter(s => s.role === 'STUDENT' && studentsWhoPaidIds.has(s.id));
  const studentsOverdue = students.filter(s => s.role === 'STUDENT' && !studentsWhoPaidIds.has(s.id));

  const handleConfirmPayment = async (paymentId: string) => {
    setIsSyncing(true);
    await onUpdatePayment(paymentId, { status: 'PAID' });
    setIsSyncing(false);
  };

  const handleAddPayment = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newPayment: Payment = {
      id: crypto.randomUUID(),
      studentId: fd.get('studentId') as string,
      amount: Number(fd.get('amount')),
      dueDate: fd.get('dueDate') as string,
      status: fd.get('status') as any
    };
    setIsSyncing(true);
    await onAddPayment(newPayment);
    setIsSyncing(false);
    setShowPaymentForm(false);
  };

  const handleAddCourse = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget);
    const newCourse: Course = {
      id: crypto.randomUUID(),
      title: fd.get('title') as string,
      instrument: fd.get('instrument') as Instrument,
      level: fd.get('level') as Level,
      description: fd.get('description') as string,
      modules: [],
      studentIds: []
    };
    setIsSyncing(true);
    await onAddCourse(newCourse);
    setIsSyncing(false);
    setShowCourseForm(false);
  };

  return (
    <div className="flex min-h-screen bg-white">
      {/* Sidebar */}
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800">
        <div className="p-8">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase leading-none">Admin<br/>Painel</h2>
        </div>
        <nav className="flex-1 px-4 space-y-2">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-8 border-t border-white/10">
          <button onClick={onLogout} className="text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all">Sair do Painel</button>
        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <div className="flex justify-between items-center mb-12">
           <h1 className="text-4xl font-black uppercase tracking-tighter">
             {activeView === 'students' && "Gestão de Alunos"}
             {activeView === 'courses' && "Gestão de Conteúdo"}
             {activeView === 'schedules' && "Agenda de Aulas"}
             {activeView === 'payments' && "Controle Financeiro"}
           </h1>
           <div className={`px-4 py-2 rounded-full text-[9px] font-black uppercase flex items-center gap-2 ${isSyncing ? 'bg-yellow-500' : 'bg-green-600 text-white'}`}>
             <div className={`w-2 h-2 rounded-full ${isSyncing ? 'animate-ping bg-black' : 'bg-white'}`}></div>
             {isSyncing ? "Processando..." : "Supabase Online"}
           </div>
        </div>

        {activeView === 'payments' && (
          <div className="space-y-12 animate-in fade-in duration-500">
            {/* KPIs de Saldo - ATUALIZAM AUTOMATICAMENTE QUANDO O STATUS MUDA */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div className="bg-black text-white p-12 rounded-[3rem] shadow-2xl relative overflow-hidden group">
                  <p className="text-[10px] font-black uppercase text-red-600 tracking-widest mb-4">Faturamento Total Anual</p>
                  <p className="text-7xl font-black tabular-nums transition-all duration-500">R$ {annualTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
               </div>
               <div className="bg-white border-4 border-gray-100 p-12 rounded-[3rem] shadow-sm relative overflow-hidden group">
                  <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-4">Liquidado este Mês</p>
                  <p className="text-7xl font-black text-black tabular-nums transition-all duration-500">R$ {monthlyTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
               </div>
            </div>

            <div className="flex justify-between items-end">
               <div>
                 <h3 className="text-xl font-black uppercase tracking-tight">Transações</h3>
