                      <tr>
                        <th className="px-10 py-6">Data</th>
                        <th className="px-10 py-6">Aluno</th>
                        <th className="px-10 py-6">Valor</th>
                        <th className="px-10 py-6">Status</th>
                        <th className="px-10 py-6 text-right">Ação</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-gray-50">
                      {payments.length > 0 ? [...payments].sort((a,b) => new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime()).map(p => {
                        const student = students.find(s => s.id === p.studentId);
                        return (
                          <tr key={p.id} className={`transition-all duration-300 ${p.status === 'PAID' ? 'bg-green-50/20' : ''}`}>
                            <td className="px-10 py-6 text-xs font-bold text-gray-500">{new Date(p.dueDate).toLocaleDateString()}</td>
                            <td className="px-10 py-6 text-xs font-black uppercase">{student?.name || "---"}</td>
                            <td className="px-10 py-6 text-sm font-black">R$ {p.amount.toFixed(2)}</td>
                            <td className="px-10 py-6">
                               <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase ${p.status === 'PAID' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700 animate-pulse'}`}>
                                 {p.status === 'PAID' ? 'Confirmado ✓' : 'Pendente'}
                               </span>
                            </td>
                            <td className="px-10 py-6 text-right">
                               {p.status === 'PENDING' && (
                                 <button onClick={() => handleConfirmPayment(p.id)} className="bg-black text-white px-6 py-2 rounded-xl text-[9px] font-black uppercase hover:bg-green-600 transition-all">Confirmar</button>
                               )}
                            </td>
                          </tr>
                        );
                      }) : (
                        <tr><td colSpan={5} className="text-center py-20 text-gray-300 font-black uppercase text-xs">Nenhum registro.</td></tr>
                      )}
                   </tbody>
                </table>
            </div>
          </div>
        )}

        {/* ... (Outras views mantidas) ... */}
        {activeView === 'students' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {students.filter(s => s.role === 'STUDENT').map(s => (
              <div key={s.id} className="p-10 bg-white border border-gray-100 rounded-[3rem] shadow-sm hover:border-red-600 hover:shadow-2xl transition-all group relative overflow-hidden">
                <div className="flex flex-col items-center mb-8">
                  <img src={s.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${s.name}`} className="w-24 h-24 rounded-full border-4 border-gray-50 group-hover:border-red-600 transition-colors shadow-lg mb-4" />
                  <h3 className="font-black uppercase text-lg tracking-tight text-center">{s.name}</h3>
                  <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">{s.instrument} • {s.level}</p>
                </div>
                <button onClick={() => setEditingStudent(s)} className="w-full bg-black text-white py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-red-600 transition-all">Editar Perfil</button>
              </div>
            ))}
          </div>
        )}

        {/* MODAL PAGAMENTO */}
        {showPaymentForm && (
           <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
             <form onSubmit={handleAddPayment} className="bg-white w-full max-w-lg rounded-[3rem] p-12 space-y-6 animate-in zoom-in">
