                </select>
                <div className="grid grid-cols-2 gap-4">
                   <input name="amount" type="number" step="0.01" required placeholder="Valor R$" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold outline-none focus:border-red-600" />
                   <input name="dueDate" type="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold outline-none focus:border-red-600" />
