        </div>
      </aside>

      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <div className="flex justify-between items-center mb-12">
           <h1 className="text-4xl font-black uppercase tracking-tighter">
             {activeView === 'students' && "Gestão de Alunos"}
             {activeView === 'courses' && "Gestão de Conteúdo"}
             {activeView === 'schedules' && "Agenda de Aulas"}
             {activeView === 'payments' && "Controle Financeiro"}
           </h1>
           <div className={`px-4 py-2 rounded-full text-[9px] font-black uppercase flex items-center gap-2 ${isSyncing ? 'bg-yellow-500' : 'bg-green-600 text-white'}`}>
             <div className={`w-2 h-2 rounded-full ${isSyncing ? 'animate-ping bg-black' : 'bg-white'}`}></div>
             {isSyncing ? "Processando..." : "Supabase Online"}
           </div>
        </div>

        {/* VIEW: CURSOS */}
        {activeView === 'courses' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-300">
            <div className="flex justify-end">
               <button onClick={() => setShowCourseForm(true)} className="bg-black text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-600 transition-colors shadow-lg shadow-black/10">
