                          className="bg-gray-100 text-gray-600 px-6 py-3 rounded-2xl text-[9px] font-black uppercase hover:bg-black hover:text-white transition-all"
                        >
                          Gerenciar Acessos
                        </button>
                        <button className="bg-red-600 text-white px-6 py-3 rounded-2xl text-[9px] font-black uppercase">
                          Editar Conteúdo
                        </button>
                     </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {(course.modules || []).map(mod => (
                      <div key={mod.id} className="bg-gray-50 p-6 rounded-[2rem] border border-transparent hover:border-red-200 transition-all">
                        <h4 className="text-[10px] font-black uppercase text-gray-400 mb-4">{mod.title}</h4>
                        <div className="space-y-2">
