              )) : (
                <div className="text-center py-20 bg-gray-50 rounded-[3rem] border-4 border-dashed border-gray-200">
                  <p className="text-gray-400 font-black uppercase tracking-widest">Nenhum curso encontrado no banco de dados.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* MODAL: GERENCIAR ACESSOS */}
        {managingAccessCourse && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-xl rounded-[3rem] overflow-hidden animate-in zoom-in duration-200">
                <div className="p-8 bg-black text-white">
                   <h3 className="text-xl font-black uppercase tracking-tighter">Quem pode ver este curso?</h3>
                   <p className="text-[10px] text-red-600 font-bold uppercase tracking-widest mt-1">{managingAccessCourse.title}</p>
                </div>
                <div className="p-10 max-h-[60vh] overflow-y-auto custom-scrollbar">
                   <div className="space-y-2">
                      {students.filter(s => s.role === 'STUDENT').map(student => (
