    const supabaseUpdates: any = {};
    if (updates.status) supabaseUpdates.status = updates.status;

    const { error } = await supabase.from('payments').update(supabaseUpdates).eq('id', paymentId);
    if (!error) {
      await fetchData(); // Recarregar tudo para garantir saldo correto
    } else {
      console.error("Erro ao atualizar pagamento:", error);
    }
  };

  if (loading) return (
    <div className="flex h-screen items-center justify-center bg-white">
      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-red-600"></div>
    </div>
  );

  if (!user) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard 
          user={user} onLogout={handleLogout}
          students={students} courses={courses} schedules={schedules}
          payments={payments} materials={materials}
          onAddStudent={addStudent} onUpdateStudent={updateStudent}
          onAddSchedule={async (sc) => { await supabase.from('schedules').insert(sc); fetchData(); }}
          onAddCourse={async (c) => { await supabase.from('courses').insert(c); fetchData(); }}
          onUpdateCourseContent={async (c) => { await updateCourseAccess(c.id, c.studentIds); }}
          onUpdateCourseAccess={updateCourseAccess}
          onAddPayment={addPayment}
          onUpdatePayment={updatePayment}
        />
      ) : (
        <StudentDashboard 
          user={user} onLogout={handleLogout}
          courses={courses} schedules={schedules}
          materials={materials} payments={payments}
          onUpdateProfile={updateStudent}
        />
      )}
    </div>
  );
};

