              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="bg-black text-white p-12 rounded-[3rem] shadow-2xl">
                    <p className="text-[10px] font-black uppercase text-red-600 tracking-widest mb-4">Saldo Anual</p>
                    <p className="text-7xl font-black tabular-nums transition-all">R$ {annualTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
                <div className="bg-white border-4 border-gray-100 p-12 rounded-[3rem] shadow-sm">
                    <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-4">Este Mês</p>
                    <p className="text-7xl font-black text-black tabular-nums transition-all">R$ {monthlyTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
              </div>

              <div className="bg-white border-2 border-gray-100 rounded-[3rem] overflow-hidden">
                <table className="w-full text-left">
                  <thead className="bg-black text-white text-[10px] font-black uppercase tracking-widest">
                    <tr>
                      <th className="px-10 py-6">Data</th>
                      <th className="px-10 py-6">Aluno</th>
                      <th className="px-10 py-6">Valor</th>
                      <th className="px-10 py-6">Status</th>
                      <th className="px-10 py-6 text-right">Ação</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {payments.length > 0 ? [...payments].sort((a,b) => new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime()).map(p => {
                      const student = students.find(s => s.id === p.studentId);
                      const isPaid = p.status === 'PAID';
                      const isPending = p.status === 'PENDING';

                      return (
                        <tr key={p.id} className={`transition-all ${isPaid ? 'bg-green-50/20' : ''}`}>
                          <td className="px-10 py-6 text-xs font-bold text-gray-500">{new Date(p.dueDate).toLocaleDateString()}</td>
                          <td className="px-10 py-6 text-xs font-black uppercase">{student?.name || '---'}</td>
                          <td className="px-10 py-6 text-sm font-black text-black">R$ {Number(p.amount).toFixed(2)}</td>
                          <td className="px-10 py-6">
                            <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-tighter ${
                              isPaid ? 'bg-green-100 text-green-700' : 
                              isPending ? 'bg-yellow-100 text-yellow-700 animate-pulse' : 
                              'bg-red-100 text-red-700'
                            }`}>
                              {isPaid ? 'Recebido ✓' : isPending ? 'Aguardando' : 'Vencido'}
                            </span>
                          </td>
                          <td className="px-10 py-6 text-right">
                            {isPending && (
                              <button onClick={() => handleConfirmPayment(p.id)} className="bg-black text-white px-6 py-2 rounded-xl text-[9px] font-black uppercase hover:bg-green-600 transition-all">Confirmar</button>
                            )}
                          </td>
                        </tr>
                      );
                    }) : (
                      <tr><td colSpan={5} className="text-center py-20 text-gray-300 font-black uppercase text-xs">Sem dados.</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
           </div>
        )}

        {activeView === 'courses' && (
           <div className="p-20 bg-gray-50 rounded-[3rem] text-center border-4 border-dashed border-gray-100">
              <p className="text-gray-300 font-black uppercase tracking-widest text-xs">Módulo de Cursos em breve...</p>
           </div>
        )}
      </main>
    </div>
  );
};

