        {/* MODAL: ACESSOS */}
        {managingAccessCourse && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-xl rounded-[3rem] overflow-hidden">
                <div className="p-8 bg-black text-white flex justify-between items-center">
                   <h3 className="text-xl font-black uppercase">Gerenciar Acessos: {managingAccessCourse.title}</h3>
                   <button onClick={() => setManagingAccessCourse(null)} className="text-2xl">&times;</button>
                </div>
                <div className="p-10 max-h-[60vh] overflow-y-auto">
                   {students.filter(s => s.role === 'STUDENT').map(s => (
                     <div key={s.id} className="flex items-center justify-between p-4 border-b">
                        <span className="text-xs font-black uppercase">{s.name}</span>
                        <input type="checkbox" checked={managingAccessCourse.studentIds.includes(s.id)} onChange={() => handleToggleAccess(s.id)} className="w-6 h-6 accent-red-600" />
                     </div>
                   ))}
                </div>
                <div className="p-8 bg-gray-50 flex gap-4">
                   <button onClick={saveAccess} className="flex-1 bg-red-600 text-white py-4 rounded-2xl text-[10px] font-black uppercase">Salvar Alterações</button>
                </div>
             </div>
          </div>
        )}

        {/* MODAL: AGENDA */}
        {showScheduleForm && (
          <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
             <form onSubmit={handleAddScheduleSubmit} className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-4">
                <h3 className="text-xl font-black uppercase text-center mb-6">Nova Aula</h3>
                <select name="studentId" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                   <option value="">Selecione o Aluno</option>
                   {students.filter(s => s.role === 'STUDENT').map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
                <input type="date" name="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                <input type="time" name="time" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                <select name="instrument" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                   <option value="Violão">Violão</option>
                   <option value="Piano">Piano</option>
                </select>
                <button type="submit" className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase">Salvar na Agenda</button>
                <button type="button" onClick={() => setShowScheduleForm(false)} className="w-full py-2 text-[10px] font-black uppercase text-gray-400">Cancelar</button>
             </form>
          </div>
        )}
      </main>
    </div>
  );
};

