              <h3 className="text-[10px] font-black uppercase mb-4 text-red-600 tracking-widest">Descrição da Aula</h3>
              <p className="text-sm text-gray-600 leading-relaxed italic">
                {selectedLesson.description || "Nenhuma descrição fornecida para esta aula."}
