import React, { useState, useMemo } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level, Module, Lesson } from '../types';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => Promise<void>;
  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onAddCourse: (c: Course) => Promise<void>;
  onUpdateCourseContent: (c: Course) => Promise<void>;
  onUpdateCourseAccess: (id: string, ids: string[]) => Promise<void>;
  onAddPayment: (p: Payment) => Promise<void>;
  onUpdatePayment: (id: string, updates: Partial<Payment>) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment, onUpdatePayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [showStudentForm, setShowStudentForm] = useState(false);
  const [showScheduleForm, setShowScheduleForm] = useState(false);
  const [managingAccessCourse, setManagingAccessCourse] = useState<Course | null>(null);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);

  // --- CALCULOS REATIVOS ---
  const { annualTotal, monthlyTotal } = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const annual = payments
      .filter(p => p.status === 'PAID' && new Date(p.dueDate).getFullYear() === currentYear)
      .reduce((acc, curr) => acc + Number(curr.amount), 0);

    const monthly = payments
      .filter(p => {
        const d = new Date(p.dueDate);
        return p.status === 'PAID' && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + Number(curr.amount), 0);

    return { annualTotal: annual, monthlyTotal: monthly };
  }, [payments]);

  const handleToggleAccess = (studentId: string) => {
    if (!managingAccessCourse) return;
    const currentIds = managingAccessCourse.studentIds || [];
    const newIds = currentIds.includes(studentId) 
      ? currentIds.filter(id => id !== studentId)
      : [...currentIds, studentId];

    setManagingAccessCourse({ ...managingAccessCourse, studentIds: newIds });
  };

  const saveAccess = async () => {
    if (!managingAccessCourse) return;
    setIsSyncing(true);
    await onUpdateCourseAccess(managingAccessCourse.id, managingAccessCourse.studentIds);
    setIsSyncing(false);
    setManagingAccessCourse(null);
  };

  const handleAddScheduleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSyncing(true);
    const fd = new FormData(e.currentTarget);
    const sc: ScheduledClass = {
      id: crypto.randomUUID(),
      studentId: fd.get('studentId') as string,
      teacherId: user.id,
      date: fd.get('date') as string,
      time: fd.get('time') as string,
      instrument: fd.get('instrument') as Instrument,
      status: 'CONFIRMED'
    };
    await onAddSchedule(sc);
    setIsSyncing(false);
    setShowScheduleForm(false);
  };

  const handleEditStudentSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingStudent) return;
    setIsSyncing(true);
    await onUpdateStudent(editingStudent);
    setIsSyncing(false);
    setEditingStudent(null);
  };

  return (
    <div className="flex min-h-screen bg-white">
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800">
        <div className="p-8">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase leading-none">Admin<br/>Painel</h2>
        </div>
        <nav className="flex-1 px-4 space-y-2">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-8 border-t border-white/10">
          <button onClick={onLogout} className="text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all">Sair do Painel</button>
