      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <div className="flex justify-between items-center mb-12">
           <h1 className="text-4xl font-black uppercase tracking-tighter">
             {activeView === 'students' && "Gestão de Alunos"}
             {activeView === 'courses' && "Gestão de Conteúdo"}
             {activeView === 'schedules' && "Agenda de Aulas"}
             {activeView === 'payments' && "Controle Financeiro"}
           </h1>
           <div className={`px-4 py-2 rounded-full text-[9px] font-black uppercase flex items-center gap-2 ${isSyncing ? 'bg-yellow-500 text-black' : 'bg-green-600 text-white'}`}>
             <div className={`w-2 h-2 rounded-full ${isSyncing ? 'animate-ping bg-black' : 'bg-white'}`}></div>
             {isSyncing ? "Processando..." : "Sincronizado"}
           </div>
        </div>

        {/* VIEW: CURSOS */}
        {activeView === 'courses' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 gap-8">
              {courses.map(course => (
                <div key={course.id} className="bg-white border-4 border-gray-100 rounded-[3rem] p-10 hover:border-red-600 transition-all group shadow-sm">
