                     <button onClick={() => setManagingAccessCourse(course)} className="bg-gray-100 px-6 py-3 rounded-2xl text-[9px] font-black uppercase hover:bg-black hover:text-white transition-all">Gerenciar Acessos</button>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    {course.modules.map(mod => (
                      <div key={mod.id} className="bg-gray-50 p-6 rounded-3xl">
                        <p className="text-[10px] font-black uppercase text-gray-400 mb-3">{mod.title}</p>
                        <div className="space-y-2">
