                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* VIEW: AGENDA */}
        {activeView === 'schedules' && (
          <div className="space-y-8">
            <div className="flex justify-end">
               <button onClick={() => setShowScheduleForm(true)} className="bg-black text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase shadow-lg">+ Agendar Aula</button>
            </div>
            <div className="bg-white border-2 border-gray-100 rounded-[3rem] overflow-hidden">
               <table className="w-full text-left">
                  <thead className="bg-black text-white text-[10px] font-black uppercase">
