                  </thead>
                  <tbody className="divide-y">
                     {schedules.map(sc => (
                        <tr key={sc.id}>
                           <td className="px-10 py-6 text-xs font-bold">{new Date(sc.date).toLocaleDateString()}</td>
                           <td className="px-10 py-6 text-xs font-black">{sc.time}</td>
                           <td className="px-10 py-6 text-xs font-black uppercase">{students.find(s => s.id === sc.studentId)?.name || '---'}</td>
                           <td className="px-10 py-6 text-xs font-bold text-red-600">{sc.instrument}</td>
                           <td className="px-10 py-6"><span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-[9px] font-black uppercase">{sc.status}</span></td>
                        </tr>
                     ))}
                  </tbody>
               </table>
            </div>
