        )}

        {/* VIEW: ALUNOS */}
        {activeView === 'students' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {students.filter(s => s.role === 'STUDENT').map(s => (
              <div key={s.id} className="p-10 bg-white border border-gray-100 rounded-[3rem] shadow-sm hover:border-red-600 transition-all group">
                <div className="flex flex-col items-center mb-8">
                  <img src={s.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${s.name}`} className="w-24 h-24 rounded-full border-4 border-gray-50 mb-4" />
                  <h3 className="font-black uppercase text-lg tracking-tight text-center">{s.name}</h3>
                  <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">{s.instrument} • {s.level}</p>
                </div>
                <button 
                  onClick={() => setEditingStudent(s)}
                  className="w-full bg-black text-white py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-red-600 transition-all"
                >
                  Editar Perfil
                </button>
              </div>
            ))}
          </div>
        )}

        {/* VIEW: FINANCEIRO */}
        {activeView === 'payments' && (
           <div className="space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="bg-black text-white p-12 rounded-[3rem] shadow-2xl">
                    <p className="text-[10px] font-black uppercase text-red-600 tracking-widest mb-4">Saldo Anual</p>
                    <p className="text-7xl font-black">R$ {annualTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
                <div className="bg-white border-4 border-gray-100 p-12 rounded-[3rem]">
                    <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-4">Este Mês</p>
                    <p className="text-7xl font-black text-black">R$ {monthlyTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
              </div>
           </div>
        )}

        {/* MODAL: EDITAR ALUNO */}
        {editingStudent && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
            <form onSubmit={handleEditStudentSubmit} className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xl font-black uppercase tracking-tighter">Editar Aluno</h3>
                <button type="button" onClick={() => setEditingStudent(null)} className="text-2xl font-black">&times;</button>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Nome do Aluno</label>
                <input 
                  type="text" 
                  value={editingStudent.name} 
                  onChange={(e) => setEditingStudent({...editingStudent, name: e.target.value})}
                  required 
                  className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" 
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Instrumento</label>
                  <select 
                    value={editingStudent.instrument} 
                    onChange={(e) => setEditingStudent({...editingStudent, instrument: e.target.value as Instrument})}
                    className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold"
                  >
                    <option value="Violão">Violão</option>
                    <option value="Piano">Piano</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Nível</label>
                  <select 
                    value={editingStudent.level} 
                    onChange={(e) => setEditingStudent({...editingStudent, level: e.target.value as Level})}
                    className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold"
                  >
                    <option value="NZ">NZ (Iniciante)</option>
                    <option value="N1">N1</option>
                    <option value="N2">N2</option>
                    <option value="N3">N3</option>
                  </select>
                </div>
              </div>

              <div className="pt-4">
                <button type="submit" className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase shadow-lg hover:bg-black transition-all">
                  Salvar Alterações
                </button>
                <button type="button" onClick={() => setEditingStudent(null)} className="w-full py-3 mt-2 text-[10px] font-black uppercase text-gray-400">
                  Cancelar
                </button>
              </div>
            </form>
          </div>
        )}

        {/* MODAL: ACESSOS */}
        {managingAccessCourse && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-xl rounded-[3rem] overflow-hidden">
                <div className="p-8 bg-black text-white flex justify-between items-center">
                   <h3 className="text-xl font-black uppercase">Gerenciar Acessos: {managingAccessCourse.title}</h3>
                   <button onClick={() => setManagingAccessCourse(null)} className="text-2xl">&times;</button>
                </div>
                <div className="p-10 max-h-[60vh] overflow-y-auto">
                   {students.filter(s => s.role === 'STUDENT').map(s => (
                     <div key={s.id} className="flex items-center justify-between p-4 border-b">
                        <span className="text-xs font-black uppercase">{s.name}</span>
                        <input type="checkbox" checked={managingAccessCourse.studentIds.includes(s.id)} onChange={() => handleToggleAccess(s.id)} className="w-6 h-6 accent-red-600" />
                     </div>
                   ))}
                </div>
                <div className="p-8 bg-gray-50 flex gap-4">
                   <button onClick={saveAccess} className="flex-1 bg-red-600 text-white py-4 rounded-2xl text-[10px] font-black uppercase">Salvar Alterações</button>
                </div>
             </div>
          </div>
        )}

        {/* MODAL: AGENDA */}
        {showScheduleForm && (
          <div className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center p-4">
             <form onSubmit={handleAddScheduleSubmit} className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-4">
                <h3 className="text-xl font-black uppercase text-center mb-6">Nova Aula</h3>
                <select name="studentId" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                   <option value="">Selecione o Aluno</option>
                   {students.filter(s => s.role === 'STUDENT').map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
                <input type="date" name="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                <input type="time" name="time" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
                <select name="instrument" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                   <option value="Violão">Violão</option>
                   <option value="Piano">Piano</option>
                </select>
                <button type="submit" className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase">Salvar na Agenda</button>
                <button type="button" onClick={() => setShowScheduleForm(false)} className="w-full py-2 text-[10px] font-black uppercase text-gray-400">Cancelar</button>
             </form>
          </div>
        )}
      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center px-4 py-4 text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all mb-1 ${
      active ? 'bg-red-600 text-white shadow-lg' : 'text-gray-500 hover:text-white hover:bg-white/5'
    }`}
  >
    <span className="mr-3 text-lg">{icon}</span>
    {label}
  </button>
);

export default AdminDashboard;

import React, { useState, useRef } from 'react';
import { User, Course, ScheduledClass, Material, Payment } from '../types';
import CoursePlayer from './CoursePlayer';
import { DEFAULT_AVATARS } from '../constants';

interface StudentDashboardProps {
  user: User;
  onLogout: () => void;
  courses: Course[];
  schedules: ScheduledClass[];
  materials: Material[];
  payments: Payment[];
  onUpdateProfile: (user: User) => void;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ 
  user, onLogout, courses, schedules, materials, payments, onUpdateProfile 
}) => {
  const [viewingCourse, setViewingCourse] = useState<Course | null>(null);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileForm, setProfileForm] = useState<User>(user);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const myCourses = courses.filter(c => c.studentIds?.includes(user.id));
  const mySchedules = schedules.filter(s => s.studentId === user.id);
  const myPayments = payments.filter(p => p.studentId === user.id);

  const handleProfileSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateProfile(profileForm);
    setIsEditingProfile(false);
    alert("Perfil atualizado com sucesso!");
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { // Limite de 2MB para não sobrecarregar o banco com base64
        alert("A imagem é muito grande. Escolha uma foto de até 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfileForm({ ...profileForm, avatar: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleChangeAvatar = (type: 'male' | 'female' | 'upload') => {
    if (type === 'male') {
      setProfileForm({ ...profileForm, avatar: DEFAULT_AVATARS.male });
    } else if (type === 'female') {
      setProfileForm({ ...profileForm, avatar: DEFAULT_AVATARS.female });
    } else {
      fileInputRef.current?.click();
    }
  };

  if (viewingCourse) {
    return (
      <>
        <header className="bg-black text-white h-16 shadow-lg flex items-center px-4 sm:px-8">
           <div className="flex items-center space-x-2 flex-1">
             <span className="text-2xl font-bold border-2 border-red-600 px-2">H</span>
             <span className="text-xl font-bold tracking-tighter uppercase">Estudando Agora</span>
           </div>
           <button onClick={() => setViewingCourse(null)} className="bg-red-600 text-white px-4 py-1 rounded text-[10px] font-black uppercase">Fechar Aula</button>
        </header>
        <CoursePlayer course={viewingCourse} onBack={() => setViewingCourse(null)} materials={materials} />
      </>
    );
  }

  return (
    <div className="min-h-screen bg-white pb-12">
      <header className="bg-black text-white sticky top-0 z-50 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
          <div className="flex items-center space-x-2">
            <span className="text-2xl font-bold border-2 border-red-600 px-2">H</span>
            <div className="leading-none">
              <span className="text-xl font-black tracking-tight block uppercase">Como Tocar Hinos</span>
              <span className="text-[10px] text-red-600 font-bold uppercase tracking-widest">Escola de Música</span>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-bold leading-none">{user.name}</p>
              <p className="text-[10px] text-red-500 uppercase font-black tracking-tighter mt-1">{user.instrument} | {user.level}</p>
            </div>
            <div className="flex space-x-2">
              <button 
                onClick={() => {
                  setProfileForm(user); // Reseta o form para os dados atuais do user
                  setIsEditingProfile(true);
                }}
                className="bg-white/10 hover:bg-white/20 text-white px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-colors"
              >
                PERFIL
              </button>
              <button onClick={onLogout} className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-colors">SAIR</button>
            </div>
          </div>
        </div>
      </header>

      {/* Modal Perfil */}
      {isEditingProfile && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
            <div className="p-8 bg-black text-white flex justify-between items-center">
              <h3 className="text-2xl font-black uppercase tracking-tighter">Meu Perfil</h3>
              <button onClick={() => setIsEditingProfile(false)} className="text-2xl font-black hover:text-red-600 transition-colors">&times;</button>
            </div>
            <form onSubmit={handleProfileSubmit} className="p-10">
              <div className="flex flex-col items-center mb-10">
                <div className="relative group">
                  <img src={profileForm.avatar} className="w-32 h-32 rounded-full border-4 border-red-600 shadow-2xl mb-4 object-cover bg-gray-50" />
                  <button 
                    type="button"
                    onClick={() => handleChangeAvatar('upload')}
                    className="absolute bottom-4 right-0 bg-red-600 text-white p-2 rounded-full shadow-lg hover:scale-110 transition-transform"
                    title="Carregar Foto"
                  >
                    📷
                  </button>
                </div>

                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleFileChange} 
                  accept="image/*" 
                  className="hidden" 
                />

                <div className="flex gap-2 mt-2">
                  <button type="button" onClick={() => handleChangeAvatar('male')} className="text-[9px] font-black uppercase bg-gray-100 px-4 py-2 rounded-xl hover:bg-gray-200 transition-colors">Avatar M</button>
                  <button type="button" onClick={() => handleChangeAvatar('female')} className="text-[9px] font-black uppercase bg-gray-100 px-4 py-2 rounded-xl hover:bg-gray-200 transition-colors">Avatar F</button>
                  <button type="button" onClick={() => handleChangeAvatar('upload')} className="text-[9px] font-black uppercase bg-black text-white px-4 py-2 rounded-xl hover:bg-red-600 transition-colors">Galeria</button>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                <div className="space-y-1">
                  <label className="text-[9px] font-black uppercase text-gray-400 ml-2">Nome Completo</label>
                  <input type="text" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold focus:border-red-600 outline-none transition-colors" value={profileForm.name} onChange={e => setProfileForm({...profileForm, name: e.target.value})} placeholder="Nome" />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black uppercase text-gray-400 ml-2">WhatsApp</label>
                  <input type="text" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold focus:border-red-600 outline-none transition-colors" value={profileForm.whatsapp || ''} onChange={e => setProfileForm({...profileForm, whatsapp: e.target.value})} placeholder="(00) 00000-0000" />
                </div>
              </div>

              <div className="flex gap-4">
                <button type="button" onClick={() => setIsEditingProfile(false)} className="flex-1 py-4 text-[10px] font-black uppercase text-gray-400">Cancelar</button>
                <button type="submit" className="flex-[2] bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase shadow-xl hover:bg-black transition-all">Salvar Alterações</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          <div className="lg:col-span-2 space-y-12">
            <section>
              <h2 className="text-2xl font-black uppercase tracking-tighter mb-6">Meu Progresso</h2>
              <div className="bg-white border-2 border-gray-100 rounded-[2.5rem] overflow-hidden shadow-sm">
                <table className="w-full text-left">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-8 py-4 text-[10px] font-black uppercase text-gray-400">Aula</th>
                      <th className="px-8 py-4 text-[10px] font-black uppercase text-gray-400">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {user.currentCycle?.map((lesson, idx) => (
                      <tr key={lesson.id}>
                        <td className="px-8 py-6 text-xs font-bold uppercase">{lesson.title}</td>
                        <td className="px-8 py-6">
                           <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase ${lesson.completed ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}>
                              {lesson.completed ? 'Concluída ✓' : 'Pendente'}
                           </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>

            <section>
              <h2 className="text-2xl font-black uppercase tracking-tighter mb-6">Cursos Liberados</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {myCourses.map(course => (
                  <div key={course.id} className="bg-black rounded-[2.5rem] overflow-hidden group">
                    <div className="p-8">
                       <span className="text-red-600 text-[10px] font-black uppercase tracking-widest mb-2 block">{course.level}</span>
                       <h3 className="text-white font-black text-xl uppercase tracking-tighter mb-6">{course.title}</h3>
                       <button onClick={() => setViewingCourse(course)} className="w-full bg-red-600 text-white py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-white hover:text-black transition-all">Assistir Aulas</button>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>

          <div className="space-y-8">
            <section className="bg-red-600 p-8 rounded-[2.5rem] text-white shadow-xl shadow-red-600/20">
              <h3 className="text-lg font-black uppercase mb-6 tracking-tighter">Financeiro</h3>
              <div className="space-y-4">
                 {myPayments.length > 0 ? myPayments.map(p => (
                   <div key={p.id} className="bg-white/10 p-4 rounded-2xl flex justify-between items-center border border-white/5">
                      <div>
                         <p className="text-sm font-black">R$ {p.amount.toFixed(2)}</p>
                         <p className="text-[9px] font-bold text-white/60">Venc: {new Date(p.dueDate || (p as any).due_date).toLocaleDateString()}</p>
                      </div>
                      <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${p.status === 'PAID' ? 'bg-green-500' : 'bg-black text-white'}`}>
                        {p.status === 'PAID' ? 'PAGO' : 'PENDENTE'}
                      </span>
                   </div>
                 )) : <p className="text-xs text-white/50 text-center py-4 italic">Nenhum registro financeiro.</p>}
              </div>
            </section>

            <section className="bg-black p-8 rounded-[2.5rem] text-white">
               <h3 className="text-lg font-black uppercase mb-6 tracking-tighter">Agenda</h3>
               <div className="space-y-4">
                 {mySchedules.length > 0 ? mySchedules.map(sc => (
                   <div key={sc.id} className="border-l-4 border-red-600 pl-4 py-2 bg-white/5 rounded-r-xl">
                      <p className="text-xs font-black">{new Date(sc.date).toLocaleDateString()}</p>
                      <p className="text-lg font-black tracking-tighter">{sc.time}</p>
                      <p className="text-[10px] font-bold text-gray-500 uppercase">{sc.instrument}</p>
                   </div>
                 )) : <p className="text-xs text-white/30 text-center py-4">Sem aulas agendadas.</p>}
               </div>
            </section>
          </div>

        </div>
      </main>
    </div>
  );
};

