import React, { useState, useEffect, useCallback } from 'react';
import { User, UserRole, Course, ScheduledClass, Payment, Material } from './types';
import { MOCK_ADMIN, MOCK_STUDENTS, MOCK_COURSES, MOCK_SCHEDULES, MOCK_PAYMENTS, MOCK_MATERIALS, DEFAULT_AVATARS } from './constants';
import AdminDashboard from './components/AdminDashboard';
import StudentDashboard from './components/StudentDashboard';
import Login from './components/Login';
import { supabase } from './services/supabase';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [schedules, setSchedules] = useState<ScheduledClass[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);

  const fetchData = useCallback(async () => {
    try {
      // PROFILES
      const { data: profiles } = await supabase.from('profiles').select('*');
      if (profiles && profiles.length > 0) {
        const mappedStudents = profiles.map((p: any) => ({ 
          ...p, 
          role: (p.role || 'STUDENT').toUpperCase(),
          currentCycle: p.current_cycle || []
        })) as User[];
        setStudents(mappedStudents);

        // Se o usuário atual estiver na lista, atualiza o estado dele também
        const savedUser = localStorage.getItem('hinos_current_user');
        if (savedUser) {
          const parsed = JSON.parse(savedUser);
          const updatedCurrentUser = mappedStudents.find(s => s.id === parsed.id);
          if (updatedCurrentUser) {
            setUser(updatedCurrentUser);
            localStorage.setItem('hinos_current_user', JSON.stringify(updatedCurrentUser));
          }
        }
      } else {
        setStudents(MOCK_STUDENTS);
      }

      // COURSES
      const { data: dbCourses } = await supabase.from('courses').select('*');
      if (dbCourses && dbCourses.length > 0) {
        setCourses(dbCourses.map((c: any) => ({ 
          ...c, 
          studentIds: c.student_ids || [] 
        })) as Course[]);
      } else {
        setCourses(MOCK_COURSES);
      }

      // SCHEDULES
      const { data: dbSchedules } = await supabase.from('schedules').select('*');
      if (dbSchedules && dbSchedules.length > 0) {
        setSchedules(dbSchedules.map((s: any) => ({ 
          ...s, 
          studentId: s.student_id,
          teacherId: s.teacher_id
        })) as ScheduledClass[]);
      } else {
        setSchedules(MOCK_SCHEDULES);
      }

      // PAYMENTS
      const { data: dbPayments } = await supabase.from('payments').select('*');
      if (dbPayments && dbPayments.length > 0) {
        setPayments(dbPayments.map((p: any) => ({ 
          ...p, 
          studentId: p.student_id, 
          dueDate: p.due_date,
          status: (p.status || 'PENDING').toUpperCase()
        })) as Payment[]);
      } else {
        setPayments(MOCK_PAYMENTS);
      }

      // MATERIALS
      const { data: dbMaterials } = await supabase.from('materials').select('*');
      if (dbMaterials && dbMaterials.length > 0) {
        setMaterials(dbMaterials as Material[]);
      } else {
        setMaterials(MOCK_MATERIALS);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
    }
  }, []);

  useEffect(() => {
    setLoading(true);
    fetchData().finally(() => setLoading(false));
  }, [fetchData]);

  useEffect(() => {
    const savedUser = localStorage.getItem('hinos_current_user');
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      setUser(parsed);
    }
  }, []);

  const handleLogin = (email: string, role: UserRole) => {
    let loggedUser: User | undefined;
    if (role === 'ADMIN') {
      if (MOCK_ADMIN.email === email) loggedUser = MOCK_ADMIN;
    } else {
      loggedUser = students.find(s => s.email.toLowerCase() === email.toLowerCase());
    }
    if (loggedUser) {
      setUser(loggedUser);
      localStorage.setItem('hinos_current_user', JSON.stringify(loggedUser));
    } else {
      alert("E-mail não cadastrado!");
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('hinos_current_user');
  };

  const addStudent = async (newStudent: User) => {
    const { error } = await supabase.from('profiles').insert([{ 
      id: newStudent.id,
      name: newStudent.name,
      email: newStudent.email,
      role: 'STUDENT',
      instrument: newStudent.instrument,
      level: newStudent.level,
      avatar: newStudent.avatar || DEFAULT_AVATARS.male,
      current_cycle: newStudent.currentCycle || []
    }]);
    if (error) {
      console.error(error);
      alert("Erro ao cadastrar aluno: " + error.message);
    } else {
      await fetchData();
    }
  };

  const addSchedule = async (sc: ScheduledClass) => {
    const { error } = await supabase.from('schedules').insert([{
      id: sc.id,
      student_id: sc.studentId,
      teacher_id: sc.teacherId,
      date: sc.date,
      time: sc.time,
      instrument: sc.instrument,
      status: sc.status
    }]);
    if (error) {
      console.error(error);
      alert("Erro ao salvar agenda: " + error.message);
    } else {
      await fetchData();
    }
  };

  const addCourse = async (newCourse: Course) => {
    const { error } = await supabase.from('courses').insert([{
      id: newCourse.id,
      title: newCourse.title,
      instrument: newCourse.instrument,
      level: newCourse.level,
      description: newCourse.description,
      modules: newCourse.modules,
      student_ids: newCourse.studentIds
    }]);
    if (error) {
      alert("Erro ao criar curso: " + error.message);
    } else {
      await fetchData();
    }
  };

  const updatePayment = async (paymentId: string, updates: Partial<Payment>) => {
    const { error } = await supabase.from('payments').update({ status: updates.status }).eq('id', paymentId);
    if (!error) await fetchData();
  };

  if (loading) return (
    <div className="flex h-screen items-center justify-center bg-white">
      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-red-600"></div>
    </div>
  );

  if (!user) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard 
          user={user} onLogout={handleLogout}
          students={students} courses={courses} schedules={schedules}
          payments={payments} materials={materials}
          onAddStudent={addStudent} 
          onUpdateStudent={async (s) => {
            const { error } = await supabase.from('profiles')
              .update({ 
                name: s.name, 
                instrument: s.instrument, 
                level: s.level,
                avatar: s.avatar,
                whatsapp: s.whatsapp
              })
              .eq('id', s.id);
            if (!error) {
              await fetchData();
            } else {
              alert("Erro ao atualizar: " + error.message);
            }
          }}
          onAddSchedule={addSchedule} 
          onAddCourse={addCourse}
          onUpdateCourseContent={async (c) => { 
             const { error } = await supabase.from('courses').update({ modules: c.modules }).eq('id', c.id);
             if (!error) await fetchData();
          }}
          onUpdateCourseAccess={async (id, ids) => {
            const { error } = await supabase.from('courses').update({ student_ids: ids }).eq('id', id);
            if (!error) await fetchData();
          }}
          onAddPayment={async (p) => { 
             const { error } = await supabase.from('payments').insert([{ id: p.id, student_id: p.studentId, amount: p.amount, due_date: p.dueDate, status: p.status }]);
             if (!error) await fetchData();
          }}
          onUpdatePayment={updatePayment}
        />
      ) : (
        <StudentDashboard 
          user={user} onLogout={handleLogout}
          courses={courses} schedules={schedules}
          materials={materials} payments={payments}
          onUpdateProfile={async (u) => {
            const { error } = await supabase.from('profiles')
              .update({ 
                name: u.name, 
                whatsapp: u.whatsapp, 
                avatar: u.avatar 
              })
              .eq('id', u.id);

            if (!error) {
              // Atualiza o estado global e o cache local imediatamente
              setUser({ ...u });
              localStorage.setItem('hinos_current_user', JSON.stringify(u));
              await fetchData();
            } else {
              alert("Erro ao salvar perfil: " + error.message);
            }
          }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { User, Course, ScheduledClass, Material, Payment } from '../types';
import CoursePlayer from './CoursePlayer';
import { DEFAULT_AVATARS } from '../constants';

interface StudentDashboardProps {
  user: User;
  onLogout: () => void;
  courses: Course[];
  schedules: ScheduledClass[];
  materials: Material[];
  payments: Payment[];
  onUpdateProfile: (user: User) => Promise<void>;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ 
  user, onLogout, courses, schedules, materials, payments, onUpdateProfile 
}) => {
  const [viewingCourse, setViewingCourse] = useState<Course | null>(null);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileForm, setProfileForm] = useState<User>(user);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sincroniza o formulário com o usuário atual quando o modal abre ou o usuário muda
  useEffect(() => {
    if (isEditingProfile) {
      setProfileForm(user);
    }
  }, [user, isEditingProfile]);

  const myCourses = courses.filter(c => c.studentIds?.includes(user.id));
  const mySchedules = schedules.filter(s => s.studentId === user.id);
  const myPayments = payments.filter(p => p.studentId === user.id);

  const handleProfileSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await onUpdateProfile(profileForm);
      setIsEditingProfile(false);
      alert("Perfil atualizado com sucesso!");
    } catch (err) {
      alert("Erro ao atualizar perfil.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1.5 * 1024 * 1024) { 
        alert("A imagem é muito pesada! Escolha uma de até 1.5MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfileForm(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleChangeAvatar = (type: 'male' | 'female' | 'upload') => {
    if (type === 'male') {
      setProfileForm(prev => ({ ...prev, avatar: DEFAULT_AVATARS.male }));
    } else if (type === 'female') {
      setProfileForm(prev => ({ ...prev, avatar: DEFAULT_AVATARS.female }));
    } else {
      fileInputRef.current?.click();
    }
  };

  if (viewingCourse) {
    return (
      <>
        <header className="bg-black text-white h-16 shadow-lg flex items-center px-4 sm:px-8">
           <div className="flex items-center space-x-2 flex-1">
             <span className="text-2xl font-bold border-2 border-red-600 px-2">H</span>
             <span className="text-xl font-bold tracking-tighter uppercase">Estudando Agora</span>
           </div>
           <button onClick={() => setViewingCourse(null)} className="bg-red-600 text-white px-4 py-1 rounded text-[10px] font-black uppercase">Fechar Aula</button>
        </header>
        <CoursePlayer course={viewingCourse} onBack={() => setViewingCourse(null)} materials={materials} />
      </>
    );
  }

  return (
    <div className="min-h-screen bg-white pb-12">
      <header className="bg-black text-white sticky top-0 z-50 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
          <div className="flex items-center space-x-2">
            <span className="text-2xl font-bold border-2 border-red-600 px-2">H</span>
            <div className="leading-none">
              <span className="text-xl font-black tracking-tight block uppercase">Como Tocar Hinos</span>
              <span className="text-[10px] text-red-600 font-bold uppercase tracking-widest">Escola de Música</span>
            </div>
          </div>
          <div className="flex items-center space-x-4">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-bold leading-none">{user.name}</p>
              <p className="text-[10px] text-red-500 uppercase font-black tracking-tighter mt-1">{user.instrument} | {user.level}</p>
            </div>
            <div className="flex space-x-2">
              <button 
                onClick={() => setIsEditingProfile(true)}
                className="bg-white/10 hover:bg-white/20 text-white px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-colors"
              >
                PERFIL
              </button>
              <button onClick={onLogout} className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-colors">SAIR</button>
            </div>
          </div>
        </div>
      </header>

      {/* Modal Perfil */}
      {isEditingProfile && (
        <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
            <div className="p-8 bg-black text-white flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black uppercase tracking-tighter leading-none">Meu Perfil</h3>
                <p className="text-[9px] text-red-500 font-black uppercase mt-1 tracking-widest">Personalize seu acesso</p>
              </div>
              <button onClick={() => setIsEditingProfile(false)} className="text-2xl font-black hover:text-red-600 transition-colors">&times;</button>
            </div>
            <form onSubmit={handleProfileSubmit} className="p-10">
              <div className="flex flex-col items-center mb-10">
                <div className="relative group cursor-pointer" onClick={() => handleChangeAvatar('upload')}>
                  <img src={profileForm.avatar} className="w-32 h-32 rounded-full border-4 border-red-600 shadow-2xl mb-4 object-cover bg-gray-50 transition-transform group-hover:scale-105" />
                  <div className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                    <span className="text-white text-xs font-black uppercase">Trocar Foto</span>
                  </div>
