                  <button type="button" onClick={() => handleChangeAvatar('male')} className="text-[9px] font-black uppercase bg-gray-100 px-4 py-2 rounded-xl hover:bg-gray-200 transition-colors border-2 border-transparent focus:border-red-600">Avatar M</button>
