                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                <div className="space-y-1">
                  <label className="text-[9px] font-black uppercase text-gray-400 ml-2">Nome Completo</label>
                  <input type="text" className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold focus:border-red-600 outline-none transition-colors" value={profileForm.name} onChange={e => setProfileForm({...profileForm, name: e.target.value})} />
                </div>
