                </div>
              </div>

              <div className="flex gap-4">
                <button type="button" onClick={() => setIsEditingProfile(false)} className="flex-1 py-4 text-[10px] font-black uppercase text-gray-400" disabled={isSaving}>Cancelar</button>
                <button type="submit" className="flex-[2] bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase shadow-xl hover:bg-black transition-all disabled:bg-gray-400" disabled={isSaving}>
                  {isSaving ? "Salvando..." : "Salvar Alterações"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

