                   <button type="button" onClick={() => fileInputRef.current?.click()} className="text-[8px] font-black uppercase bg-black text-white px-3 py-1 rounded-lg">Galeria</button>
                   <input type="file" ref={fileInputRef} onChange={handleAvatarFileChange} className="hidden" accept="image/*" />
                 </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Nome do Aluno</label>
                <input type="text" value={editingStudent.name} onChange={(e) => setEditingStudent({...editingStudent, name: e.target.value})} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Instrumento</label>
                  <select value={editingStudent.instrument} onChange={(e) => setEditingStudent({...editingStudent, instrument: e.target.value as Instrument})} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                    <option value="Violão">Violão</option>
                    <option value="Piano">Piano</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Nível</label>
                  <select value={editingStudent.level} onChange={(e) => setEditingStudent({...editingStudent, level: e.target.value as Level})} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                    <option value="NZ">NZ (Iniciante)</option>
                    <option value="N1">N1</option>
                    <option value="N2">N2</option>
                    <option value="N3">N3</option>
                  </select>
                </div>
              </div>

              <button type="submit" className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase shadow-lg hover:bg-black transition-all">
                Salvar Alterações
              </button>
            </form>
          </div>
        )}

        {/* MODAL: GERENCIAR ACESSO */}
        {managingAccessCourse && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 space-y-8 animate-in zoom-in duration-300">
               <div className="flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase tracking-tighter">Acesso ao Curso: {managingAccessCourse.title}</h3>
                 <button onClick={() => setManagingAccessCourse(null)} className="text-2xl font-black">&times;</button>
               </div>
               <div className="max-h-96 overflow-y-auto pr-4 space-y-2 custom-scrollbar">
                 {students.filter(s => s.role === 'STUDENT').map(s => (
                   <button 
                    key={s.id}
                    onClick={() => handleToggleAccess(s.id)}
                    className={`w-full flex justify-between items-center p-4 rounded-2xl border-2 transition-all ${
                      managingAccessCourse.studentIds?.includes(s.id) ? 'border-red-600 bg-red-50' : 'border-gray-100 hover:border-gray-200'
                    }`}
                   >
                     <div className="flex items-center gap-3">
                       <img src={s.avatar} className="w-8 h-8 rounded-full" />
                       <span className="text-xs font-black uppercase">{s.name}</span>
                     </div>
                     <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                       managingAccessCourse.studentIds?.includes(s.id) ? 'bg-red-600 border-red-600' : 'border-gray-300'
                     }`}>
                       {managingAccessCourse.studentIds?.includes(s.id) && <span className="text-white text-[10px]">✓</span>}
                     </div>
                   </button>
                 ))}
               </div>
               <button onClick={saveAccess} className="w-full bg-black text-white py-5 rounded-3xl text-xs font-black uppercase shadow-xl hover:bg-red-600 transition-all">
                 Salvar Configurações de Acesso
               </button>
            </div>
          </div>
        )}

        {/* MODAL: NOVA AULA AGENDADA */}
        {showScheduleForm && (
           <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
             <form onSubmit={handleAddSchedule} className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-6">
                <h3 className="text-xl font-black uppercase tracking-tighter mb-4">Nova Aula na Agenda</h3>
                <div className="space-y-4">
                  <select 
                    className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold"
                    onChange={(e) => setNewSchedule({...newSchedule, studentId: e.target.value})}
                    required
                  >
                    <option value="">Selecione o Aluno</option>
                    {students.filter(s => s.role === 'STUDENT').map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                  <input type="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" onChange={(e) => setNewSchedule({...newSchedule, date: e.target.value})} />
                  <input type="time" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" onChange={(e) => setNewSchedule({...newSchedule, time: e.target.value})} />
                </div>
                <div className="flex gap-4 pt-4">
                  <button type="button" onClick={() => setShowScheduleForm(false)} className="flex-1 py-4 text-[10px] font-black uppercase text-gray-400">Cancelar</button>
                  <button type="submit" className="flex-[2] bg-red-600 text-white py-4 rounded-3xl text-xs font-black uppercase shadow-lg">Agendar Aula</button>
                </div>
             </form>
           </div>
        )}
      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center px-4 py-4 text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all mb-1 ${
      active ? 'bg-red-600 text-white shadow-lg' : 'text-gray-500 hover:text-white hover:bg-white/5'
    }`}
  >
    <span className="mr-3 text-lg">{icon}</span>
    {label}
  </button>
);

export default AdminDashboard;

import React, { useState, useMemo, useRef } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level, Module, Lesson } from '../types';
import { DEFAULT_AVATARS } from '../constants';
import { generateLessonDescription } from '../services/geminiService';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => Promise<void>;
  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onAddCourse: (c: Course) => Promise<void>;
  onUpdateCourseContent: (c: Course) => Promise<void>;
  onUpdateCourseAccess: (id: string, ids: string[]) => Promise<void>;
  onAddPayment: (p: Payment) => Promise<void>;
  onUpdatePayment: (id: string, updates: Partial<Payment>) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment, onUpdatePayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [showScheduleForm, setShowScheduleForm] = useState(false);
  const [managingAccessCourse, setManagingAccessCourse] = useState<Course | null>(null);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);
  const [editingCourseContent, setEditingCourseContent] = useState<Course | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Estados para formulários de criação
  const [newSchedule, setNewSchedule] = useState<Partial<ScheduledClass>>({ instrument: 'Violão', status: 'PENDING' });

  // --- CALCULOS REATIVOS ---
  const { annualTotal, monthlyTotal } = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const annual = payments
      .filter(p => p.status === 'PAID' && new Date(p.dueDate).getFullYear() === currentYear)
      .reduce((acc, curr) => acc + Number(curr.amount), 0);

    const monthly = payments
      .filter(p => {
        const d = new Date(p.dueDate);
        return p.status === 'PAID' && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + Number(curr.amount), 0);

    return { annualTotal: annual, monthlyTotal: monthly };
  }, [payments]);

  const handleToggleAccess = (studentId: string) => {
    if (!managingAccessCourse) return;
    const currentIds = managingAccessCourse.studentIds || [];
    const newIds = currentIds.includes(studentId) 
      ? currentIds.filter(id => id !== studentId)
      : [...currentIds, studentId];

    setManagingAccessCourse({ ...managingAccessCourse, studentIds: newIds });
  };

  const saveAccess = async () => {
    if (!managingAccessCourse) return;
    setIsSyncing(true);
    await onUpdateCourseAccess(managingAccessCourse.id, managingAccessCourse.studentIds);
    setIsSyncing(false);
    setManagingAccessCourse(null);
  };

  const handleEditStudentSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingStudent) return;
    setIsSyncing(true);
    await onUpdateStudent(editingStudent);
    setIsSyncing(false);
    setEditingStudent(null);
  };

  const handleAvatarFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && editingStudent) {
      if (file.size > 1.5 * 1024 * 1024) {
        alert("Imagem muito grande! Máximo 1.5MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditingStudent({ ...editingStudent, avatar: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddSchedule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSchedule.studentId || !newSchedule.date || !newSchedule.time) return;
    setIsSyncing(true);
    await onAddSchedule({
      id: `sc-${Date.now()}`,
      studentId: newSchedule.studentId,
      teacherId: user.id,
      date: newSchedule.date,
      time: newSchedule.time,
      status: 'PENDING',
      instrument: newSchedule.instrument as Instrument
    });
    setIsSyncing(false);
    setShowScheduleForm(false);
  };

  // --- FUNÇÕES DO EDITOR DE CURSOS ---
  const addModule = () => {
    if (!editingCourseContent) return;
    const newModule: Module = {
      id: `mod-${Date.now()}`,
      title: `Novo Módulo`,
      lessons: []
    };
    setEditingCourseContent({
      ...editingCourseContent,
      modules: [...(editingCourseContent.modules || []), newModule]
    });
  };

  const addLesson = (moduleId: string) => {
    if (!editingCourseContent) return;
    const newLesson: Lesson = {
      id: `lesson-${Date.now()}`,
      title: 'Nova Aula',
      videoArranjoUrl: '',
      videoAoVivoUrl: '',
      description: ''
    };
    const updatedModules = editingCourseContent.modules.map(m => 
      m.id === moduleId ? { ...m, lessons: [...m.lessons, newLesson] } : m
    );
    setEditingCourseContent({ ...editingCourseContent, modules: updatedModules });
  };

  const updateLesson = (moduleId: string, lessonId: string, updates: Partial<Lesson>) => {
    if (!editingCourseContent) return;
    const updatedModules = editingCourseContent.modules.map(m => {
      if (m.id === moduleId) {
        return {
          ...m,
          lessons: m.lessons.map(l => l.id === lessonId ? { ...l, ...updates } : l)
        };
      }
      return m;
    });
    setEditingCourseContent({ ...editingCourseContent, modules: updatedModules });
  };

  const deleteLesson = (moduleId: string, lessonId: string) => {
    if (!editingCourseContent) return;
    const updatedModules = editingCourseContent.modules.map(m => {
      if (m.id === moduleId) {
        return { ...m, lessons: m.lessons.filter(l => l.id !== lessonId) };
      }
      return m;
    });
    setEditingCourseContent({ ...editingCourseContent, modules: updatedModules });
  };

  const deleteModule = (moduleId: string) => {
    if (!editingCourseContent) return;
    setEditingCourseContent({
      ...editingCourseContent,
      modules: editingCourseContent.modules.filter(m => m.id !== moduleId)
    });
  };

  const saveCourseContent = async () => {
    if (!editingCourseContent) return;
    setIsSyncing(true);
    await onUpdateCourseContent(editingCourseContent);
    setIsSyncing(false);
    setEditingCourseContent(null);
    alert("Curso atualizado com sucesso!");
  };

  const handleAIAutoFill = async (moduleId: string, lessonId: string, title: string) => {
    if (!editingCourseContent) return;
    setIsSyncing(true);
    const desc = await generateLessonDescription(title, editingCourseContent.instrument, editingCourseContent.level);
    updateLesson(moduleId, lessonId, { description: desc });
    setIsSyncing(false);
  };

  return (
    <div className="flex min-h-screen bg-white">
      {/* Sidebar Lateral */}
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800 shrink-0">
        <div className="p-8">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase leading-none">Admin<br/>Painel</h2>
        </div>
        <nav className="flex-1 px-4 space-y-2">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-8 border-t border-white/10">
          <button onClick={onLogout} className="text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all">Sair do Painel</button>
        </div>
      </aside>

      {/* Área Principal */}
      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <div className="flex justify-between items-center mb-12">
           <h1 className="text-4xl font-black uppercase tracking-tighter">
             {activeView === 'students' && "Gestão de Alunos"}
             {activeView === 'courses' && "Gestão de Conteúdo"}
             {activeView === 'schedules' && "Agenda de Aulas"}
             {activeView === 'payments' && "Controle Financeiro"}
           </h1>
           <div className={`px-4 py-2 rounded-full text-[9px] font-black uppercase flex items-center gap-2 ${isSyncing ? 'bg-yellow-500 text-black' : 'bg-green-600 text-white'}`}>
             <div className={`w-2 h-2 rounded-full ${isSyncing ? 'animate-ping bg-black' : 'bg-white'}`}></div>
             {isSyncing ? "Processando..." : "Sincronizado"}
           </div>
        </div>

        {/* VIEW: ALUNOS */}
        {activeView === 'students' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {students.filter(s => s.role === 'STUDENT').map(s => (
              <div key={s.id} className="p-10 bg-white border border-gray-100 rounded-[3rem] shadow-sm hover:border-red-600 transition-all group">
                <div className="flex flex-col items-center mb-8">
                  <img src={s.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${s.name}`} className="w-24 h-24 rounded-full border-4 border-gray-50 mb-4 object-cover" />
                  <h3 className="font-black uppercase text-lg tracking-tight text-center">{s.name}</h3>
                  <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">{s.instrument} • {s.level}</p>
                </div>
                <button 
                  onClick={() => setEditingStudent(s)}
                  className="w-full bg-black text-white py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-red-600 transition-all"
                >
                  Editar Perfil
                </button>
              </div>
            ))}
          </div>
        )}

        {/* VIEW: CURSOS */}
        {activeView === 'courses' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {courses.map(course => (
              <div key={course.id} className="bg-black text-white p-10 rounded-[3rem] shadow-xl">
                <span className="text-red-600 text-[10px] font-black uppercase tracking-widest block mb-2">{course.instrument} | {course.level}</span>
                <h3 className="text-2xl font-black uppercase tracking-tighter mb-6">{course.title}</h3>
                <div className="grid grid-cols-2 gap-4">
                  <button 
                    onClick={() => setManagingAccessCourse(course)}
                    className="bg-white/10 hover:bg-white/20 text-white py-4 rounded-2xl text-[10px] font-black uppercase transition-all"
                  >
                    Acessos
                  </button>
                  <button 
                    className="bg-red-600 hover:bg-red-700 text-white py-4 rounded-2xl text-[10px] font-black uppercase transition-all"
                    onClick={() => setEditingCourseContent(course)}
                  >
                    Editar Aulas
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* VIEW: AGENDA */}
        {activeView === 'schedules' && (
          <div className="space-y-8">
            <div className="flex justify-end">
              <button onClick={() => setShowScheduleForm(true)} className="bg-black text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-red-600 transition-all">+ Nova Aula</button>
            </div>
            <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden">
               <table className="w-full">
                 <thead className="bg-gray-50 border-b border-gray-100">
                   <tr>
                     <th className="px-8 py-4 text-left text-[10px] font-black uppercase text-gray-400">Aluno</th>
                     <th className="px-8 py-4 text-left text-[10px] font-black uppercase text-gray-400">Data/Hora</th>
                     <th className="px-8 py-4 text-left text-[10px] font-black uppercase text-gray-400">Instrumento</th>
                     <th className="px-8 py-4 text-left text-[10px] font-black uppercase text-gray-400">Status</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-gray-100">
                   {schedules.map(sc => {
                     const student = students.find(s => s.id === sc.studentId);
                     return (
                       <tr key={sc.id}>
                         <td className="px-8 py-6 font-black uppercase text-xs">{student?.name || '---'}</td>
                         <td className="px-8 py-6 text-xs font-bold text-gray-500">{new Date(sc.date).toLocaleDateString()} às {sc.time}</td>
                         <td className="px-8 py-6 text-xs font-bold">{sc.instrument}</td>
                         <td className="px-8 py-6">
                           <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-[9px] font-black uppercase">{sc.status}</span>
                         </td>
                       </tr>
                     );
                   })}
                 </tbody>
               </table>
            </div>
          </div>
        )}

        {/* VIEW: FINANCEIRO */}
        {activeView === 'payments' && (
          <div className="space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-black text-white p-10 rounded-[3rem] shadow-xl">
                 <p className="text-red-600 text-[10px] font-black uppercase mb-2">Faturamento Mensal</p>
                 <h2 className="text-5xl font-black tracking-tighter">R$ {monthlyTotal.toFixed(2)}</h2>
              </div>
              <div className="bg-gray-50 p-10 rounded-[3rem] border-2 border-dashed border-gray-200">
                 <p className="text-gray-400 text-[10px] font-black uppercase mb-2">Faturamento Anual</p>
                 <h2 className="text-5xl font-black tracking-tighter">R$ {annualTotal.toFixed(2)}</h2>
              </div>
            </div>

            <div className="bg-white border border-gray-100 rounded-[2.5rem] overflow-hidden">
               <table className="w-full">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-8 py-4 text-left text-[10px] font-black uppercase text-gray-400">Aluno</th>
                      <th className="px-8 py-4 text-left text-[10px] font-black uppercase text-gray-400">Vencimento</th>
                      <th className="px-8 py-4 text-left text-[10px] font-black uppercase text-gray-400">Valor</th>
                      <th className="px-8 py-4 text-left text-[10px] font-black uppercase text-gray-400">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {payments.map(p => {
                       const student = students.find(s => s.id === p.studentId);
                       return (
                         <tr key={p.id}>
                           <td className="px-8 py-6 font-black uppercase text-xs">{student?.name}</td>
                           <td className="px-8 py-6 text-xs font-bold text-gray-500">{new Date(p.dueDate).toLocaleDateString()}</td>
                           <td className="px-8 py-6 text-xs font-black">R$ {p.amount.toFixed(2)}</td>
                           <td className="px-8 py-6">
                              <button 
                                onClick={() => onUpdatePayment(p.id, { status: p.status === 'PAID' ? 'PENDING' : 'PAID' })}
                                className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase transition-all ${p.status === 'PAID' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-600'}`}
                              >
                                {p.status === 'PAID' ? 'PAGO ✓' : 'PENDENTE'}
                              </button>
                           </td>
                         </tr>
                       );
                    })}
                  </tbody>
               </table>
            </div>
          </div>
        )}

        {/* MODAL: EDITOR DE CONTEÚDO (MÓDULOS E AULAS) */}
        {editingCourseContent && (
          <div className="fixed inset-0 bg-white z-[120] overflow-y-auto custom-scrollbar flex flex-col">
            <header className="bg-black text-white p-6 sticky top-0 flex justify-between items-center z-10">
              <div>
                <h2 className="text-2xl font-black uppercase tracking-tighter">{editingCourseContent.title}</h2>
                <p className="text-[10px] text-red-600 font-black uppercase tracking-widest">Editor de Aulas</p>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setEditingCourseContent(null)} className="px-6 py-2 text-[10px] font-black uppercase text-gray-400">Cancelar</button>
                <button onClick={saveCourseContent} className="bg-red-600 text-white px-8 py-2 rounded-xl text-[10px] font-black uppercase hover:bg-white hover:text-black transition-all">Salvar Tudo</button>
              </div>
            </header>

            <div className="max-w-4xl mx-auto w-full p-12 space-y-12">
              <div className="flex justify-between items-center border-b-4 border-black pb-4">
                <h3 className="text-3xl font-black uppercase tracking-tighter italic">Estrutura do Curso</h3>
                <button onClick={addModule} className="bg-black text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase">+ Adicionar Módulo</button>
              </div>

              {editingCourseContent.modules?.length === 0 && (
                <div className="text-center py-20 bg-gray-50 rounded-[3rem] border-2 border-dashed border-gray-200">
                  <p className="text-gray-400 font-black uppercase text-sm">Nenhum módulo cadastrado ainda.</p>
                </div>
              )}

              <div className="space-y-10">
                {editingCourseContent.modules?.map((mod, mIdx) => (
                  <div key={mod.id} className="bg-gray-50 rounded-[3rem] p-8 border border-gray-100 shadow-sm relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-2 h-full bg-red-600"></div>
                    <div className="flex justify-between items-start mb-8 pl-4">
                      <div className="flex-1">
                        <label className="text-[9px] font-black uppercase text-gray-400">Título do Módulo</label>
                        <input 
                          type="text" 
                          value={mod.title} 
                          onChange={(e) => {
                            const newMods = editingCourseContent.modules.map(m => m.id === mod.id ? { ...m, title: e.target.value } : m);
                            setEditingCourseContent({ ...editingCourseContent, modules: newMods });
                          }}
                          className="w-full bg-transparent text-2xl font-black uppercase tracking-tighter border-b-2 border-gray-200 focus:border-red-600 outline-none transition-all py-2"
                        />
                      </div>
                      <button onClick={() => deleteModule(mod.id)} className="text-gray-300 hover:text-red-600 text-xs font-black uppercase ml-4">Excluir Módulo</button>
                    </div>

                    <div className="space-y-4 pl-4">
                       {mod.lessons.map((lesson, lIdx) => (
                         <div key={lesson.id} className="bg-white border border-gray-100 rounded-3xl p-6 shadow-sm">
                           <div className="flex justify-between items-center mb-6">
                              <div className="flex items-center gap-3">
                                <span className="w-8 h-8 rounded-full bg-black text-white flex items-center justify-center text-[10px] font-black">{lIdx + 1}</span>
                                <input 
                                  type="text" 
                                  value={lesson.title} 
                                  onChange={(e) => updateLesson(mod.id, lesson.id, { title: e.target.value })}
                                  placeholder="Título da Aula"
                                  className="text-sm font-black uppercase outline-none focus:text-red-600"
                                />
                              </div>
                              <button onClick={() => deleteLesson(mod.id, lesson.id)} className="text-gray-300 hover:text-red-600 text-[10px] font-black uppercase">Remover</button>
                           </div>

                           <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                             <div className="space-y-1">
                               <label className="text-[9px] font-black uppercase text-gray-400">URL Vídeo Arranjo (Youtube)</label>
                               <input 
                                type="text" 
                                value={lesson.videoArranjoUrl} 
                                onChange={(e) => updateLesson(mod.id, lesson.id, { videoArranjoUrl: e.target.value })}
                                className="w-full border border-gray-200 p-3 rounded-xl text-xs font-bold bg-gray-50"
                                placeholder="ID ou Link do Youtube"
                               />
                             </div>
                             <div className="space-y-1">
                               <label className="text-[9px] font-black uppercase text-gray-400">URL Vídeo Aula Ao Vivo</label>
                               <input 
                                type="text" 
                                value={lesson.videoAoVivoUrl} 
                                onChange={(e) => updateLesson(mod.id, lesson.id, { videoAoVivoUrl: e.target.value })}
                                className="w-full border border-gray-200 p-3 rounded-xl text-xs font-bold bg-gray-50"
                                placeholder="ID ou Link do Youtube"
                               />
                             </div>
                           </div>

                           <div className="space-y-1">
                             <div className="flex justify-between items-center">
                               <label className="text-[9px] font-black uppercase text-gray-400">Descrição da Aula</label>
                               <button 
                                 type="button"
                                 onClick={() => handleAIAutoFill(mod.id, lesson.id, lesson.title)}
                                 className="text-[8px] font-black uppercase text-red-600 hover:text-black transition-colors"
                               >
                                 ✨ Gerar com IA
                               </button>
                             </div>
                             <textarea 
                               rows={3} 
                               value={lesson.description} 
                               onChange={(e) => updateLesson(mod.id, lesson.id, { description: e.target.value })}
                               className="w-full border border-gray-200 p-3 rounded-xl text-xs font-medium bg-gray-50 resize-none"
                               placeholder="Descreva o que será ensinado nesta aula..."
                             />
                           </div>
                         </div>
                       ))}
                       <button onClick={() => addLesson(mod.id)} className="w-full border-2 border-dashed border-gray-200 py-4 rounded-3xl text-[10px] font-black uppercase text-gray-400 hover:border-red-600 hover:text-red-600 transition-all">
                         + Adicionar Aula ao Módulo
                       </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* MODAL: EDITAR ALUNO */}
        {editingStudent && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
            <form onSubmit={handleEditStudentSubmit} className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-6 animate-in slide-in-from-bottom-10 duration-300">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xl font-black uppercase tracking-tighter">Editar Aluno</h3>
                <button type="button" onClick={() => setEditingStudent(null)} className="text-2xl font-black">&times;</button>
              </div>

              <div className="flex flex-col items-center gap-4">
                 <img src={editingStudent.avatar} className="w-24 h-24 rounded-full border-4 border-red-600 object-cover shadow-xl" />
                 <div className="flex gap-2">
                   <button type="button" onClick={() => setEditingStudent({...editingStudent, avatar: DEFAULT_AVATARS.male})} className="text-[8px] font-black uppercase bg-gray-100 px-3 py-1 rounded-lg">Masc</button>
                   <button type="button" onClick={() => setEditingStudent({...editingStudent, avatar: DEFAULT_AVATARS.female})} className="text-[8px] font-black uppercase bg-gray-100 px-3 py-1 rounded-lg">Fem</button>
                   <button type="button" onClick={() => fileInputRef.current?.click()} className="text-[8px] font-black uppercase bg-black text-white px-3 py-1 rounded-lg">Galeria</button>
                   <input type="file" ref={fileInputRef} onChange={handleAvatarFileChange} className="hidden" accept="image/*" />
                 </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Nome do Aluno</label>
                <input type="text" value={editingStudent.name} onChange={(e) => setEditingStudent({...editingStudent, name: e.target.value})} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Instrumento</label>
                  <select value={editingStudent.instrument} onChange={(e) => setEditingStudent({...editingStudent, instrument: e.target.value as Instrument})} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                    <option value="Violão">Violão</option>
                    <option value="Piano">Piano</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Nível</label>
                  <select value={editingStudent.level} onChange={(e) => setEditingStudent({...editingStudent, level: e.target.value as Level})} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold">
                    <option value="NZ">NZ (Iniciante)</option>
                    <option value="N1">N1</option>
                    <option value="N2">N2</option>
                    <option value="N3">N3</option>
                  </select>
                </div>
              </div>

              <button type="submit" className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase shadow-lg hover:bg-black transition-all">
                Salvar Alterações
              </button>
            </form>
          </div>
        )}

        {/* MODAL: GERENCIAR ACESSO */}
        {managingAccessCourse && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 space-y-8 animate-in zoom-in duration-300">
               <div className="flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase tracking-tighter">Acesso ao Curso: {managingAccessCourse.title}</h3>
                 <button onClick={() => setManagingAccessCourse(null)} className="text-2xl font-black">&times;</button>
               </div>
               <div className="max-h-96 overflow-y-auto pr-4 space-y-2 custom-scrollbar">
                 {students.filter(s => s.role === 'STUDENT').map(s => (
                   <button 
                    key={s.id}
                    onClick={() => handleToggleAccess(s.id)}
                    className={`w-full flex justify-between items-center p-4 rounded-2xl border-2 transition-all ${
                      managingAccessCourse.studentIds?.includes(s.id) ? 'border-red-600 bg-red-50' : 'border-gray-100 hover:border-gray-200'
                    }`}
                   >
                     <div className="flex items-center gap-3">
                       <img src={s.avatar} className="w-8 h-8 rounded-full" />
                       <span className="text-xs font-black uppercase">{s.name}</span>
                     </div>
                     <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                       managingAccessCourse.studentIds?.includes(s.id) ? 'bg-red-600 border-red-600' : 'border-gray-300'
                     }`}>
                       {managingAccessCourse.studentIds?.includes(s.id) && <span className="text-white text-[10px]">✓</span>}
                     </div>
                   </button>
                 ))}
               </div>
               <button onClick={saveAccess} className="w-full bg-black text-white py-5 rounded-3xl text-xs font-black uppercase shadow-xl hover:bg-red-600 transition-all">
                 Salvar Configurações de Acesso
               </button>
            </div>
          </div>
        )}

        {/* MODAL: NOVA AULA AGENDADA */}
        {showScheduleForm && (
           <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
             <form onSubmit={handleAddSchedule} className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-6">
                <h3 className="text-xl font-black uppercase tracking-tighter mb-4">Nova Aula na Agenda</h3>
                <div className="space-y-4">
                  <select 
                    className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold"
                    onChange={(e) => setNewSchedule({...newSchedule, studentId: e.target.value})}
                    required
                  >
                    <option value="">Selecione o Aluno</option>
                    {students.filter(s => s.role === 'STUDENT').map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                  <input type="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" onChange={(e) => setNewSchedule({...newSchedule, date: e.target.value})} />
                  <input type="time" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" onChange={(e) => setNewSchedule({...newSchedule, time: e.target.value})} />
                </div>
                <div className="flex gap-4 pt-4">
                  <button type="button" onClick={() => setShowScheduleForm(false)} className="flex-1 py-4 text-[10px] font-black uppercase text-gray-400">Cancelar</button>
                  <button type="submit" className="flex-[2] bg-red-600 text-white py-4 rounded-3xl text-xs font-black uppercase shadow-lg">Agendar Aula</button>
                </div>
             </form>
           </div>
        )}
      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center px-4 py-4 text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all mb-1 ${
      active ? 'bg-red-600 text-white shadow-lg' : 'text-gray-500 hover:text-white hover:bg-white/5'
    }`}
  >
    <span className="mr-3 text-lg">{icon}</span>
    {label}
  </button>
);

export default AdminDashboard;

import React, { useState, useMemo, useRef } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level, Module, Lesson } from '../types';
import { DEFAULT_AVATARS } from '../constants';
import { generateLessonDescription } from '../services/geminiService';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => Promise<void>;
  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onAddCourse: (c: Course) => Promise<void>;
  onUpdateCourseContent: (c: Course) => Promise<void>;
  onUpdateCourseAccess: (id: string, ids: string[]) => Promise<void>;
  onAddPayment: (p: Payment) => Promise<void>;
  onUpdatePayment: (id: string, updates: Partial<Payment>) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment, onUpdatePayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [showScheduleForm, setShowScheduleForm] = useState(false);
  const [showAddCourseForm, setShowAddCourseForm] = useState(false);
  const [managingAccessCourse, setManagingAccessCourse] = useState<Course | null>(null);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);
  const [editingCourseContent, setEditingCourseContent] = useState<Course | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Estados para novos cadastros
  const [newSchedule, setNewSchedule] = useState<Partial<ScheduledClass>>({ instrument: 'Violão', status: 'PENDING' });
  const [newCourse, setNewCourse] = useState<Partial<Course>>({ title: '', instrument: 'Violão', level: 'NZ', description: '', modules: [], studentIds: [] });

  // --- CALCULOS REATIVOS ---
  const { annualTotal, monthlyTotal } = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const annual = payments
      .filter(p => p.status === 'PAID' && new Date(p.dueDate).getFullYear() === currentYear)
      .reduce((acc, curr) => acc + Number(curr.amount), 0);

    const monthly = payments
      .filter(p => {
        const d = new Date(p.dueDate);
        return p.status === 'PAID' && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .reduce((acc, curr) => acc + Number(curr.amount), 0);

    return { annualTotal: annual, monthlyTotal: monthly };
  }, [payments]);

  const handleCreateCourse = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCourse.title) return;
    setIsSyncing(true);
    const courseToSave: Course = {
      id: `course-${Date.now()}`,
      title: newCourse.title!,
      instrument: newCourse.instrument as Instrument,
      level: newCourse.level as Level,
      description: newCourse.description || '',
      modules: [],
      studentIds: []
    };
    await onAddCourse(courseToSave);
    setIsSyncing(false);
    setShowAddCourseForm(false);
    setNewCourse({ title: '', instrument: 'Violão', level: 'NZ', description: '', modules: [], studentIds: [] });
  };

  const handleToggleAccess = (studentId: string) => {
    if (!managingAccessCourse) return;
    const currentIds = managingAccessCourse.studentIds || [];
    const newIds = currentIds.includes(studentId) 
      ? currentIds.filter(id => id !== studentId)
      : [...currentIds, studentId];

    setManagingAccessCourse({ ...managingAccessCourse, studentIds: newIds });
  };

  const saveAccess = async () => {
    if (!managingAccessCourse) return;
    setIsSyncing(true);
    await onUpdateCourseAccess(managingAccessCourse.id, managingAccessCourse.studentIds);
    setIsSyncing(false);
    setManagingAccessCourse(null);
  };

  const handleEditStudentSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingStudent) return;
    setIsSyncing(true);
    await onUpdateStudent(editingStudent);
    setIsSyncing(false);
    setEditingStudent(null);
  };

  const handleAvatarFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && editingStudent) {
      if (file.size > 1.5 * 1024 * 1024) {
        alert("Imagem muito grande! Máximo 1.5MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditingStudent({ ...editingStudent, avatar: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddSchedule = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSchedule.studentId || !newSchedule.date || !newSchedule.time) return;
    setIsSyncing(true);
    await onAddSchedule({
      id: `sc-${Date.now()}`,
      studentId: newSchedule.studentId,
      teacherId: user.id,
      date: newSchedule.date,
      time: newSchedule.time,
      status: 'PENDING',
      instrument: newSchedule.instrument as Instrument
    });
    setIsSyncing(false);
    setShowScheduleForm(false);
  };

  // --- FUNÇÕES DO EDITOR DE CURSOS ---
  const addModule = () => {
    if (!editingCourseContent) return;
    const newModule: Module = {
      id: `mod-${Date.now()}`,
      title: `Novo Módulo`,
      lessons: []
    };
    setEditingCourseContent({
      ...editingCourseContent,
      modules: [...(editingCourseContent.modules || []), newModule]
    });
  };

  const addLesson = (moduleId: string) => {
    if (!editingCourseContent) return;
    const newLesson: Lesson = {
      id: `lesson-${Date.now()}`,
      title: 'Nova Aula',
      videoArranjoUrl: '',
      videoAoVivoUrl: '',
      description: ''
    };
    const updatedModules = editingCourseContent.modules.map(m => 
      m.id === moduleId ? { ...m, lessons: [...m.lessons, newLesson] } : m
    );
    setEditingCourseContent({ ...editingCourseContent, modules: updatedModules });
  };

  const updateLesson = (moduleId: string, lessonId: string, updates: Partial<Lesson>) => {
    if (!editingCourseContent) return;
    const updatedModules = editingCourseContent.modules.map(m => {
      if (m.id === moduleId) {
        return {
          ...m,
          lessons: m.lessons.map(l => l.id === lessonId ? { ...l, ...updates } : l)
        };
      }
      return m;
    });
    setEditingCourseContent({ ...editingCourseContent, modules: updatedModules });
  };

  const deleteLesson = (moduleId: string, lessonId: string) => {
    if (!editingCourseContent) return;
    const updatedModules = editingCourseContent.modules.map(m => {
      if (m.id === moduleId) {
        return { ...m, lessons: m.lessons.filter(l => l.id !== lessonId) };
      }
      return m;
    });
    setEditingCourseContent({ ...editingCourseContent, modules: updatedModules });
  };

  const deleteModule = (moduleId: string) => {
    if (!editingCourseContent) return;
    setEditingCourseContent({
      ...editingCourseContent,
      modules: editingCourseContent.modules.filter(m => m.id !== moduleId)
    });
  };

  const saveCourseContent = async () => {
    if (!editingCourseContent) return;
    setIsSyncing(true);
    await onUpdateCourseContent(editingCourseContent);
    setIsSyncing(false);
    setEditingCourseContent(null);
    alert("Curso atualizado com sucesso no banco de dados!");
  };

  const handleAIAutoFill = async (moduleId: string, lessonId: string, title: string) => {
    if (!editingCourseContent) return;
    setIsSyncing(true);
    const desc = await generateLessonDescription(title, editingCourseContent.instrument, editingCourseContent.level);
    updateLesson(moduleId, lessonId, { description: desc });
    setIsSyncing(false);
  };

  return (
    <div className="flex min-h-screen bg-white">
      {/* Sidebar Lateral */}
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800 shrink-0">
        <div className="p-8">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase leading-none">Admin<br/>Painel</h2>
        </div>
        <nav className="flex-1 px-4 space-y-2">
          <SidebarLink active={activeView === 'students'} onClick={() => setActiveView('students')} icon="👥" label="Alunos" />
          <SidebarLink active={activeView === 'courses'} onClick={() => setActiveView('courses')} icon="🎹" label="Cursos" />
          <SidebarLink active={activeView === 'schedules'} onClick={() => setActiveView('schedules')} icon="📅" label="Agenda" />
          <SidebarLink active={activeView === 'payments'} onClick={() => setActiveView('payments')} icon="💰" label="Financeiro" />
        </nav>
        <div className="p-8 border-t border-white/10">
          <button onClick={onLogout} className="text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all">Sair do Painel</button>
        </div>
      </aside>

      {/* Área Principal */}
      <main className="flex-1 p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <div className="flex justify-between items-center mb-12">
           <h1 className="text-4xl font-black uppercase tracking-tighter">
             {activeView === 'students' && "Gestão de Alunos"}
             {activeView === 'courses' && "Gestão de Conteúdo"}
             {activeView === 'schedules' && "Agenda de Aulas"}
             {activeView === 'payments' && "Controle Financeiro"}
           </h1>
           <div className={`px-4 py-2 rounded-full text-[9px] font-black uppercase flex items-center gap-2 ${isSyncing ? 'bg-yellow-500 text-black' : 'bg-green-600 text-white'}`}>
             <div className={`w-2 h-2 rounded-full ${isSyncing ? 'animate-ping bg-black' : 'bg-white'}`}></div>
             {isSyncing ? "Processando..." : "Sincronizado"}
           </div>
        </div>

        {/* VIEW: ALUNOS */}
        {activeView === 'students' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {students.filter(s => s.role === 'STUDENT').map(s => (
              <div key={s.id} className="p-10 bg-white border border-gray-100 rounded-[3rem] shadow-sm hover:border-red-600 transition-all group">
                <div className="flex flex-col items-center mb-8">
                  <img src={s.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${s.name}`} className="w-24 h-24 rounded-full border-4 border-gray-50 mb-4 object-cover" />
                  <h3 className="font-black uppercase text-lg tracking-tight text-center">{s.name}</h3>
                  <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">{s.instrument} • {s.level}</p>
                </div>
                <button 
                  onClick={() => setEditingStudent(s)}
                  className="w-full bg-black text-white py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-red-600 transition-all"
                >
                  Editar Perfil
                </button>
              </div>
            ))}
          </div>
        )}

        {/* VIEW: CURSOS */}
        {activeView === 'courses' && (
          <div className="space-y-8">
            <div className="flex justify-end">
              <button onClick={() => setShowAddCourseForm(true)} className="bg-black text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-red-600 transition-all">+ Novo Curso</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {courses.map(course => (
                <div key={course.id} className="bg-black text-white p-10 rounded-[3rem] shadow-xl">
                  <span className="text-red-600 text-[10px] font-black uppercase tracking-widest block mb-2">{course.instrument} | {course.level}</span>
                  <h3 className="text-2xl font-black uppercase tracking-tighter mb-6">{course.title}</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <button 
                      onClick={() => setManagingAccessCourse(course)}
                      className="bg-white/10 hover:bg-white/20 text-white py-4 rounded-2xl text-[10px] font-black uppercase transition-all"
                    >
                      Acessos
                    </button>
                    <button 
                      className="bg-red-600 hover:bg-red-700 text-white py-4 rounded-2xl text-[10px] font-black uppercase transition-all"
                      onClick={() => setEditingCourseContent(course)}
                    >
                      Editar Aulas
                    </button>
                  </div>
                </div>
              ))}
            </div>
