               </div>
               <button onClick={saveAccess} className="w-full bg-black text-white py-5 rounded-3xl text-xs font-black uppercase shadow-xl hover:bg-red-600 transition-all">Salvar Configurações de Acesso</button>
            </div>
          </div>
        )}

        {showScheduleForm && (
           <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-4">
             <form onSubmit={handleAddSchedule} className="bg-white w-full max-w-md rounded-[3rem] p-10 space-y-6">
                <h3 className="text-xl font-black uppercase tracking-tighter mb-4">Nova Aula na Agenda</h3>
                <div className="space-y-4">
                  <select className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" onChange={(e) => setNewSchedule({...newSchedule, studentId: e.target.value})} required>
                    <option value="">Selecione o Aluno</option>
                    {students.filter(s => s.role === 'STUDENT').map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                  <input type="date" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" onChange={(e) => setNewSchedule({...newSchedule, date: e.target.value})} />
                  <input type="time" required className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" onChange={(e) => setNewSchedule({...newSchedule, time: e.target.value})} />
