};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button
    onClick={onClick}
    className={`w-full flex items-center px-4 py-4 text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all mb-1 ${
      active ? 'bg-red-600 text-white shadow-lg' : 'text-gray-500 hover:text-white hover:bg-white/5'
    }`}
  >
    <span className="mr-3 text-lg">{icon}</span>
    {label}
  </button>
);

export default AdminDashboard;

export type Instrument = 'Violão' | 'Piano';
export type Level = 'NZ' | 'N1' | 'N2' | 'N3';
export type UserRole = 'ADMIN' | 'STUDENT';

export interface CycleLesson {
  id: string;
  title: string;
  completed: boolean;
  date?: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  role: UserRole;
  instrument?: Instrument;
  level?: Level;
  avatar?: string;
  birthDate?: string;
  city?: string;
  state?: string;
  country?: string;
  whatsapp?: string;
  // Controle de Ciclo de Aulas
  totalCompletedClasses?: number;
  currentCycle?: CycleLesson[]; // Mantido para compatibilidade, mas usaremos a lógica de schedules
}

export interface Lesson {
  id: string;
  title: string;
  videoArranjoUrl: string;
  videoAoVivoUrl: string;
  description: string;
}

export interface Module {
  id: string;
  title: string;
  lessons: Lesson[];
}

export interface Course {
  id: string;
  title: string;
  instrument: Instrument;
  level: Level;
  description: string;
  modules: Module[];
  studentIds: string[];
}

export interface ScheduledClass {
  id: string;
  studentId: string;
  teacherId: string;
  date: string;
  time: string;
  status: 'PENDING' | 'CONFIRMED' | 'CANCELLED' | 'COMPLETED';
  instrument: Instrument;
  title?: string; // Campo opcional para nomear a aula na agenda
}

export interface Material {
  id: string;
  title: string;
  fileUrl: string;
  instrument: Instrument;
  level: Level;
  studentIds?: string[];
}

export interface Payment {
  id: string;
  studentId: string;
  amount: number;
  status: 'PAID' | 'PENDING' | 'OVERDUE';
  dueDate: string;
}

