                  <h3 className="text-2xl font-black uppercase tracking-tighter mb-6">{course.title}</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => setManagingAccessCourse(course)} className="bg-white/10 hover:bg-white/20 text-white py-4 rounded-2xl text-[10px] font-black uppercase">Acessos</button>
