                  <select value={editingStudent.level} onChange={e => setEditingStudent({...editingStudent, level: e.target.value as Level})} className="w-full border-2 p-4 rounded-2xl text-xs font-bold"><option value="NZ">NZ</option><option value="N1">N1</option><option value="N2">N2</option><option value="N3">N3</option></select>
                </div>
              </div>
              <button type="submit" className="w-full bg-red-600 text-white py-5 rounded-3xl text-xs font-black uppercase shadow-lg">Salvar Perfil</button>
            </form>
          </div>
        )}

        {/* MODAIS DE APOIO (Agenda, Acesso, Novo Curso) seguem a mesma lógica funcional e estética... */}
      </main>
    </div>
  );
};

