import React, { useState } from 'react';
import { UserRole } from '../types';

interface LoginProps {
  onLogin: (email: string, role: UserRole) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>('STUDENT');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return alert("Por favor, digite seu e-mail");
    onLogin(email, role);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-white p-4">
      <div className="max-w-md w-full border border-gray-100 shadow-2xl rounded-2xl overflow-hidden bg-white">
        <div className="p-8 bg-black text-white text-center">
          <h1 className="text-3xl font-bold tracking-tight">
            Como <span className="text-red-600">Tocar</span> Hinos
          </h1>
          <p className="mt-2 text-gray-400 text-sm">Portal da Escola de Música</p>
        </div>
        <div className="p-8">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700">Acessar como</label>
              <div className="mt-2 grid grid-cols-2 gap-3">
                <button
                  type="button"
                  onClick={() => setRole('STUDENT')}
                  className={`py-2 px-4 text-sm font-medium rounded-lg border ${
                    role === 'STUDENT' ? 'bg-red-600 text-white border-red-600' : 'bg-white text-gray-700 border-gray-200'
                  } transition-all duration-200`}
                >
                  Aluno
                </button>
                <button
                  type="button"
                  onClick={() => setRole('ADMIN')}
                  className={`py-2 px-4 text-sm font-medium rounded-lg border ${
                    role === 'ADMIN' ? 'bg-red-600 text-white border-red-600' : 'bg-white text-gray-700 border-gray-200'
                  } transition-all duration-200`}
                >
                  Administrador
                </button>
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700">E-mail cadastrado</label>
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="mt-1 block w-full px-4 py-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-red-500 focus:border-red-500 transition-all"
                placeholder={role === 'ADMIN' ? 'admin@comotocarhinos.com' : 'seu@email.com'}
              />
            </div>

            <button
              type="submit"
              className="w-full flex justify-center py-3 px-4 border border-transparent rounded-lg shadow-sm text-sm font-bold text-white bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 transition-colors"
            >
              Acessar Painel
            </button>

            <div className="mt-4 p-4 bg-gray-50 rounded-xl text-center">
              <p className="text-xs text-gray-500">
                <strong>Modo de Desenvolvimento:</strong><br/>
                O acesso por senha foi desativado temporariamente.<br/>
                Use: <em>{role === 'ADMIN' ? 'admin@comotocarhinos.com' : 'joao@email.com'}</em>
              </p>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useRef } from 'react';
import { User, Course, ScheduledClass, Material, Payment } from '../types';
import CoursePlayer from './CoursePlayer';
import { DEFAULT_AVATARS } from '../constants';

interface StudentDashboardProps {
  user: User;
  onLogout: () => void;
  courses: Course[];
  schedules: ScheduledClass[];
  materials: Material[];
  payments: Payment[];
  onUpdateProfile: (user: User) => Promise<void>;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ 
  user, onLogout, courses, schedules, materials, payments, onUpdateProfile
}) => {
  const [viewingCourse, setViewingCourse] = useState<Course | null>(null);
