            </section>
          </div>

          <aside className="space-y-12">
            <section className="bg-black p-12 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
               <h3 className="text-xl font-black uppercase mb-8 tracking-tighter italic flex items-center gap-3">
                 <span className="bg-red-600 w-1.5 h-6"></span> Histórico de Aulas
