import React, { useState, useMemo } from 'react';
import { Course, Lesson, Material } from '../types';
import Metronome from './Metronome';

interface CoursePlayerProps {
  course: Course;
  onBack: () => void;
  materials: Material[];
}

const CoursePlayer: React.FC<CoursePlayerProps> = ({ course, onBack, materials }) => {
  // Encontra a primeira aula disponível com segurança
  const firstLesson = useMemo(() => {
    if (course.modules && course.modules.length > 0) {
      for (const module of course.modules) {
        if (module.lessons && module.lessons.length > 0) {
          return module.lessons[0];
        }
      }
    }
    return null;
  }, [course]);

  const [selectedLesson, setSelectedLesson] = useState<Lesson | null>(firstLesson);
  const [videoType, setVideoType] = useState<'arranjo' | 'aovivo'>('arranjo');
  const [activeTab, setActiveTab] = useState<'aulas' | 'materiais'>('aulas');

  const MusicNoteIcon = () => (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className="text-white">
      <path d="M9 18V5L21 3V16" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
      <circle cx="6" cy="18" r="3" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
      <circle cx="18" cy="16" r="3" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
    </svg>
  );

  // Se não houver aula selecionada (curso vazio), mostra um aviso em vez de tela branca
  if (!selectedLesson) {
    return (
      <div className="flex flex-col items-center justify-center h-[calc(100vh-64px)] bg-gray-50 p-8 text-center">
        <div className="bg-white p-12 rounded-[3rem] shadow-xl border-2 border-gray-100 max-w-md">
          <span className="text-6xl mb-6 block">🚧</span>
          <h2 className="text-2xl font-black uppercase tracking-tighter mb-4">Curso em Construção</h2>
          <p className="text-gray-500 text-sm font-medium mb-8">Este curso ainda não possui aulas ou módulos cadastrados. Volte em breve!</p>
          <button onClick={onBack} className="bg-black text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase">Voltar ao Início</button>
        </div>
      </div>
    );
  }

  const videoUrl = videoType === 'arranjo' ? selectedLesson.videoArranjoUrl : selectedLesson.videoAoVivoUrl;
  const courseMaterials = materials.filter(m => m.instrument === course.instrument && m.level === course.level);

  // Função segura para pegar o número da aula ou índice
  const getLessonNumber = (lesson: Lesson, moduleIdx: number, lessonIdx: number) => {
    if (lesson.id.includes('-h')) {
      const parts = lesson.id.split('-h');
      return parts[1] ? parts[1].charAt(0) : lessonIdx + 1;
    }
    return lessonIdx + 1;
  };

  return (
    <div className="flex flex-col lg:flex-row h-[calc(100vh-64px)] bg-white">
      {/* Sidebar de Conteúdo */}
      <aside className="w-full lg:w-80 bg-gray-50 border-r border-gray-200 overflow-y-auto custom-scrollbar flex flex-col shrink-0">
        <div className="p-6 border-b bg-white sticky top-0 z-10">
          <button onClick={onBack} className="text-[10px] font-black uppercase text-gray-400 hover:text-red-600 mb-2 flex items-center transition-colors">
            <span className="mr-2">←</span> Voltar para Início
          </button>
          <div className="flex items-center gap-3 mb-4">
            <div className="bg-black p-1.5 rounded-lg">
              <MusicNoteIcon />
            </div>
            <h2 className="font-black text-lg uppercase leading-tight">{course.title}</h2>
          </div>

          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button 
              onClick={() => setActiveTab('aulas')}
              className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${activeTab === 'aulas' ? 'bg-white shadow-sm text-red-600' : 'text-gray-400'}`}
            >
              Aulas
            </button>
            <button 
              onClick={() => setActiveTab('materiais')}
              className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${activeTab === 'materiais' ? 'bg-white shadow-sm text-red-600' : 'text-gray-400'}`}
            >
              Arquivos
            </button>
          </div>
        </div>

        <div className="flex-1">
          {activeTab === 'aulas' ? (
            course.modules?.map((module, mIdx) => (
              <div key={module.id || mIdx} className="border-b border-gray-100">
                <div className="bg-gray-100/50 px-6 py-2 text-[10px] font-black uppercase text-gray-500 tracking-widest">
                  {module.title}
                </div>
                {module.lessons?.map((lesson, lIdx) => (
                  <button
                    key={lesson.id || lIdx}
                    onClick={() => setSelectedLesson(lesson)}
                    className={`w-full text-left px-6 py-4 transition-all flex items-center space-x-3 ${
                      selectedLesson.id === lesson.id ? 'bg-red-600 text-white shadow-lg z-10' : 'hover:bg-red-50'
                    }`}
                  >
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold border shrink-0 ${
                      selectedLesson.id === lesson.id ? 'border-white/30 bg-white/10' : 'border-gray-200 bg-white text-gray-400'
                    }`}>
                      {getLessonNumber(lesson, mIdx, lIdx)}
                    </div>
                    <span className="text-xs font-bold uppercase flex-1 line-clamp-2">{lesson.title}</span>
                  </button>
                ))}
              </div>
            ))
          ) : (
            <div className="p-4 space-y-2">
              {courseMaterials.length > 0 ? (
                courseMaterials.map(m => (
                  <a 
                    key={m.id} 
                    href={m.fileUrl} 
                    target="_blank" 
                    rel="noreferrer"
                    className="flex items-center p-4 bg-white border border-gray-100 rounded-2xl hover:border-red-600 transition-all group"
                  >
                    <span className="text-xl mr-3 group-hover:scale-110 transition-transform">📄</span>
                    <div className="flex-1 overflow-hidden">
                      <p className="text-[10px] font-black uppercase tracking-tight leading-tight truncate">{m.title}</p>
                      <p className="text-[9px] text-gray-400 font-bold uppercase">Download PDF</p>
                    </div>
                  </a>
                ))
              ) : (
                <p className="text-center py-10 text-[10px] font-black uppercase text-gray-400">Nenhum material disponível.</p>
              )}
            </div>
          )}
        </div>
      </aside>

      {/* Área do Player */}
      <main className="flex-1 bg-white overflow-y-auto p-4 lg:p-8 custom-scrollbar">
        <div className="max-w-5xl mx-auto space-y-6">
          <div className="aspect-video bg-black rounded-3xl overflow-hidden shadow-2xl relative">
            {videoUrl ? (
               <iframe
                className="w-full h-full"
                src={videoUrl.includes('youtube.com/embed') ? videoUrl : `https://www.youtube.com/embed/${videoUrl.split('v=')[1]?.split('&')[0] || videoUrl}`}
                title={selectedLesson.title}
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              ></iframe>
            ) : (
              <div className="w-full h-full flex items-center justify-center text-gray-500 font-black uppercase text-xs">Vídeo não disponível</div>
            )}
          </div>

          <div className="flex flex-col sm:flex-row justify-between items-center gap-4 bg-gray-50 p-4 rounded-3xl border border-gray-100">
            <div className="flex p-1 bg-gray-200 rounded-2xl w-full sm:w-auto">
              <button
                onClick={() => setVideoType('arranjo')}
                className={`flex-1 sm:px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  videoType === 'arranjo' ? 'bg-red-600 text-white shadow-md' : 'text-gray-500 hover:text-black'
                }`}
              >
                Arranjo
              </button>
              <button
                onClick={() => setVideoType('aovivo')}
                className={`flex-1 sm:px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  videoType === 'aovivo' ? 'bg-red-600 text-white shadow-md' : 'text-gray-500 hover:text-black'
                }`}
              >
                Aula Ao Vivo
              </button>
            </div>
            <div className="text-right w-full sm:w-auto">
              <h1 className="text-xl font-black uppercase tracking-tighter">{selectedLesson.title}</h1>
              <p className="text-xs text-gray-500 font-bold uppercase">{course.instrument} • {course.level}</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="md:col-span-2 bg-white border border-gray-100 p-8 rounded-3xl shadow-sm">
              <h3 className="text-[10px] font-black uppercase mb-4 text-red-600 tracking-widest">Descrição da Aula</h3>
              <p className="text-sm text-gray-600 leading-relaxed italic">
                {selectedLesson.description || "Nenhuma descrição fornecida para esta aula."}
              </p>
            </div>
            <div className="space-y-4">
              <Metronome />
              <div className="bg-gray-900 text-white p-6 rounded-[2rem] border border-gray-800 shadow-xl">
                <div className="flex justify-between items-center mb-4">
                  <span className="text-[10px] font-black uppercase text-red-600">Afinador Digital</span>
                  <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse shadow-[0_0_8px_#ef4444]"></div>
                </div>
                <div className="flex items-center justify-center space-x-1 mb-4 h-12">
                   {[...Array(9)].map((_, i) => (
                     <div key={i} className={`w-1 rounded-full transition-all duration-300 ${i === 4 ? 'h-10 bg-red-600 shadow-[0_0_10px_#ef4444]' : 'h-6 bg-gray-700'}`}></div>
                   ))}
