import React, { useState, useEffect, useCallback } from 'react';
import { User, UserRole, Course, ScheduledClass, Payment, Material } from './types';
import { MOCK_ADMIN, MOCK_STUDENTS, MOCK_COURSES, MOCK_SCHEDULES, MOCK_PAYMENTS, MOCK_MATERIALS, DEFAULT_AVATARS } from './constants';
import AdminDashboard from './components/AdminDashboard';
import StudentDashboard from './components/StudentDashboard';
import Login from './components/Login';
import { supabase } from './services/supabase';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [schedules, setSchedules] = useState<ScheduledClass[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);

  const fetchData = useCallback(async () => {
    try {
      const { data: profiles } = await supabase.from('profiles').select('*');
      if (profiles && profiles.length > 0) {
        setStudents(profiles.map((p: any) => ({ 
          ...p, 
          role: (p.role || 'STUDENT').toUpperCase(),
          totalCompletedClasses: p.total_completed_classes || 0
        })));
      } else {
        setStudents(MOCK_STUDENTS);
      }

      const { data: dbCourses } = await supabase.from('courses').select('*');
      if (dbCourses && dbCourses.length > 0) {
        setCourses(dbCourses.map((c: any) => ({ ...c, studentIds: c.student_ids || [] })));
      } else {
        setCourses(MOCK_COURSES);
      }

      const { data: dbSchedules } = await supabase.from('schedules').select('*');
      if (dbSchedules && dbSchedules.length > 0) {
        setSchedules(dbSchedules.map((s: any) => ({ 
          ...s, 
          studentId: s.student_id,
          teacherId: s.teacher_id,
          status: s.status?.toUpperCase() || 'PENDING'
        })));
      } else {
        setSchedules(MOCK_SCHEDULES);
      }

      const { data: dbPayments } = await supabase.from('payments').select('*');
      if (dbPayments && dbPayments.length > 0) {
        setPayments(dbPayments.map((p: any) => ({ 
          ...p, 
          studentId: p.student_id, 
          dueDate: p.due_date,
          status: (p.status || 'PENDING').toUpperCase()
        })));
      } else {
        setPayments(MOCK_PAYMENTS);
      }
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
    }
  }, []);

  useEffect(() => {
    fetchData().finally(() => setLoading(false));
  }, [fetchData]);

  const updateScheduleStatus = async (id: string, newStatus: ScheduledClass['status']) => {
    const classToUpdate = schedules.find(s => s.id === id);
    if (!classToUpdate) return;

    const { error } = await supabase.from('schedules').update({ status: newStatus }).eq('id', id);
    if (!error) {
      if (newStatus === 'COMPLETED' && classToUpdate.status !== 'COMPLETED') {
        const student = students.find(s => s.id === classToUpdate.studentId);
        if (student) {
          const newCount = (student.totalCompletedClasses || 0) + 1;
          await supabase.from('profiles').update({ total_completed_classes: newCount }).eq('id', student.id);
        }
      } else if (newStatus !== 'COMPLETED' && classToUpdate.status === 'COMPLETED') {
        const student = students.find(s => s.id === classToUpdate.studentId);
        if (student) {
          const newCount = Math.max(0, (student.totalCompletedClasses || 0) - 1);
          await supabase.from('profiles').update({ total_completed_classes: newCount }).eq('id', student.id);
        }
      }
      await fetchData();
    }
  };

  const handleLogin = (email: string, password: string, role: UserRole) => {
    let loggedUser: User | undefined;

    if (role === 'ADMIN') {
      const ADMIN_EMAIL = 'admin@comotocarhinos.com';
      const ADMIN_PASSWORD = 'MusicaSacra2026*';

      if (email.toLowerCase() === ADMIN_EMAIL.toLowerCase() && password === ADMIN_PASSWORD) {
        loggedUser = MOCK_ADMIN;
      } else {
        return alert("E-mail ou senha de administrador incorretos.");
      }
    } else {
      // Para alunos, vamos buscar o perfil e validar a senha
      // Como é um mock, usaremos uma senha padrão '123456' para todos os alunos se não houver senha no BD
      const student = students.find(s => s.email.toLowerCase() === email.toLowerCase());

      if (student) {
        // No sistema real, a senha estaria criptografada no banco. 
        // Aqui usamos uma senha padrão para os mocks ou a senha do objeto se definida.
        const validPassword = student.password || '123456';
        if (password === validPassword) {
          loggedUser = student;
        } else {
          return alert("Senha incorreta.");
        }
      } else {
        return alert("Aluno não encontrado com este e-mail.");
      }
    }

    if (loggedUser) {
      setUser(loggedUser);
      localStorage.setItem('hinos_current_user', JSON.stringify(loggedUser));
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('hinos_current_user');
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><div className="animate-spin rounded-full h-12 w-12 border-b-4 border-red-600"></div></div>;
  if (!user) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard 
          user={user} onLogout={handleLogout}
          students={students} courses={courses} schedules={schedules}
          payments={payments} materials={materials}
          onAddStudent={async (s) => { await supabase.from('profiles').insert([s]); await fetchData(); }}
          onUpdateStudent={async (s) => { await supabase.from('profiles').update({ name: s.name, instrument: s.instrument, level: s.level, avatar: s.avatar, whatsapp: s.whatsapp }).eq('id', s.id); await fetchData(); }}
          onAddSchedule={async (sc) => { await supabase.from('schedules').insert([{ id: sc.id, student_id: sc.studentId, teacher_id: sc.teacherId, date: sc.date, time: sc.time, instrument: sc.instrument, status: sc.status, title: sc.title }]); await fetchData(); }}
          onUpdateSchedule={updateScheduleStatus}
          onAddCourse={async (c) => { await supabase.from('courses').insert([{ id: c.id, title: c.title, instrument: c.instrument, level: c.level, description: c.description, modules: c.modules, student_ids: c.studentIds }]); await fetchData(); }}
          onUpdateCourseContent={async (c) => { await supabase.from('courses').update({ modules: c.modules, description: c.description }).eq('id', c.id); await fetchData(); }}
          onUpdateCourseAccess={async (id, ids) => { await supabase.from('courses').update({ student_ids: ids }).eq('id', id); await fetchData(); }}
          onAddPayment={async (p) => { await supabase.from('payments').insert([p]); await fetchData(); }}
          onUpdatePayment={async (id, u) => { await supabase.from('payments').update({ status: u.status }).eq('id', id); await fetchData(); }}
        />
      ) : (
        <StudentDashboard 
          user={user} onLogout={handleLogout}
          courses={courses} schedules={schedules}
          materials={materials} payments={payments}
          onUpdateProfile={async (u) => { await supabase.from('profiles').update({ name: u.name, whatsapp: u.whatsapp, avatar: u.avatar }).eq('id', u.id); setUser(u); await fetchData(); }}
        />
      )}
    </div>
  );
};

export default App;

