  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onUpdateSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment, onUpdatePayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [showAddCourseForm, setShowAddCourseForm] = useState(false);
  const [managingAccessCourse, setManagingAccessCourse] = useState<Course | null>(null);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);
  const [editingCourseContent, setEditingCourseContent] = useState<Course | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [newCourse, setNewCourse] = useState<Partial<Course>>({ title: '', instrument: 'Violão', level: 'NZ', description: '', modules: [], studentIds: [] });

  const { annualTotal, monthlyTotal } = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const annual = payments.filter(p => p.status === 'PAID' && new Date(p.dueDate).getFullYear() === currentYear).reduce((acc, curr) => acc + Number(curr.amount), 0);
    const monthly = payments.filter(p => { const d = new Date(p.dueDate); return p.status === 'PAID' && d.getMonth() === currentMonth && d.getFullYear() === currentYear; }).reduce((acc, curr) => acc + Number(curr.amount), 0);
    return { annualTotal: annual, monthlyTotal: monthly };
  }, [payments]);

  const getStudentCycleInfo = (studentId: string) => {
    const student = students.find(s => s.id === studentId);
    if (!student) return null;
    const completed = student.totalCompletedClasses || 0;
    const cycles = Math.floor(completed / 4);
    const currentCycleClass = (completed % 4) + 1;
    return { completed, cycles, currentCycleClass };
  };

  const handleToggleAccess = async (courseId: string, studentId: string) => {
    const course = courses.find(c => c.id === courseId);
    if (!course) return;
    let newIds = [...(course.studentIds || [])];
    if (newIds.includes(studentId)) {
      newIds = newIds.filter(id => id !== studentId);
    } else {
      newIds.push(studentId);
    }
    await onUpdateCourseAccess(courseId, newIds);
  };

  const addModule = () => {
    if (!editingCourseContent) return;
    const newModule: Module = { id: `mod-${Date.now()}`, title: `Novo Módulo`, lessons: [] };
    setEditingCourseContent({ ...editingCourseContent, modules: [...(editingCourseContent.modules || []), newModule] });
  };

  const addLesson = (moduleId: string) => {
    if (!editingCourseContent) return;
    const newLesson: Lesson = { id: `lesson-${Date.now()}`, title: 'Nova Aula', videoArranjoUrl: '', videoAoVivoUrl: '', description: '' };
    const updatedModules = editingCourseContent.modules.map(m => m.id === moduleId ? { ...m, lessons: [...m.lessons, newLesson] } : m);
    setEditingCourseContent({ ...editingCourseContent, modules: updatedModules });
  };

  const updateLesson = (modId: string, lesId: string, updates: Partial<Lesson>) => {
    if (!editingCourseContent) return;
    const updated = editingCourseContent.modules.map(m => m.id === modId ? { ...m, lessons: m.lessons.map(l => l.id === lesId ? { ...l, ...updates } : l) } : m);
    setEditingCourseContent({ ...editingCourseContent, modules: updated });
  };

  const SidebarContent = () => (
    <>
      <div className="p-8 flex justify-between items-center md:block">
        <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase">Admin</h2>
        <button onClick={() => setIsSidebarOpen(false)} className="md:hidden text-white text-2xl font-black">&times;</button>
      </div>
      <nav className="flex-1 px-4 space-y-2">
        <SidebarLink 
          active={activeView === 'students'} 
          onClick={() => { setActiveView('students'); setIsSidebarOpen(false); }} 
          icon="👥" label="Alunos" 
        />
        <SidebarLink 
          active={activeView === 'courses'} 
          onClick={() => { setActiveView('courses'); setIsSidebarOpen(false); }} 
          icon="🎹" label="Cursos" 
        />
        <SidebarLink 
          active={activeView === 'schedules'} 
          onClick={() => { setActiveView('schedules'); setIsSidebarOpen(false); }} 
          icon="📅" label="Agenda" 
        />
        <SidebarLink 
          active={activeView === 'payments'} 
          onClick={() => { setActiveView('payments'); setIsSidebarOpen(false); }} 
          icon="💰" label="Financeiro" 
        />
      </nav>
      <div className="p-8 border-t border-white/10">
        <button onClick={onLogout} className="text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all w-full text-left">Sair</button>
      </div>
    </>
  );

  return (
    <div className="flex min-h-screen bg-white relative">
      {/* Sidebar Desktop */}
      <aside className="w-64 bg-black text-white hidden md:flex flex-col border-r border-gray-800 shrink-0">
        <SidebarContent />
      </aside>

      {/* Sidebar Mobile (Floating Drawer) */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/60 z-[250] md:hidden" onClick={() => setIsSidebarOpen(false)}>
          <aside 
            className="w-72 h-full bg-black text-white flex flex-col border-r border-gray-800 animate-in slide-in-from-left duration-300"
            onClick={(e) => e.stopPropagation()}
          >
            <SidebarContent />
          </aside>
        </div>
      )}

      <main className="flex-1 p-4 md:p-8 overflow-y-auto max-h-screen custom-scrollbar">
        <div className="flex justify-between items-center mb-12 gap-4">
           <div className="flex items-center gap-4">
             <button 
               onClick={() => setIsSidebarOpen(true)} 
               className="md:hidden bg-black text-white p-3 rounded-2xl shadow-lg hover:scale-105 transition-transform"
             >
               <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                 <path d="M4 6H20M4 12H20M4 18H20" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
               </svg>
             </button>
             <h1 className="text-2xl md:text-4xl font-black uppercase tracking-tighter truncate">
               {activeView === 'students' && "Alunos"}
               {activeView === 'courses' && "Cursos"}
               {activeView === 'schedules' && "Agenda"}
               {activeView === 'payments' && "Financeiro"}
             </h1>
           </div>
           <div className={`shrink-0 px-4 py-2 rounded-full text-[9px] font-black uppercase ${isSyncing ? 'bg-yellow-500 text-black' : 'bg-green-600 text-white'}`}>
             {isSyncing ? "Processando..." : "Sincronizado"}
           </div>
        </div>

        {activeView === 'students' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
            {students.filter(s => s.role === 'STUDENT').map(s => {
              const info = getStudentCycleInfo(s.id);
              return (
                <div key={s.id} className="p-6 md:p-10 bg-white border border-gray-100 rounded-[2.5rem] md:rounded-[3rem] shadow-sm hover:border-red-600 transition-all">
                  <div className="flex flex-col items-center mb-6">
                    <img src={s.avatar || DEFAULT_AVATARS.male} className="w-20 h-20 rounded-full border-4 border-gray-50 mb-4 object-cover shadow-lg" />
                    <h3 className="font-black uppercase text-lg tracking-tight text-center">{s.name}</h3>
                    <p className="text-[9px] font-black text-red-600 uppercase tracking-widest">{s.instrument} • {s.level}</p>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-2xl mb-6">
                    <div className="flex justify-between text-[10px] font-black uppercase mb-2"><span>Ciclos Completos</span><span>{info?.cycles}</span></div>
                    <div className="flex justify-between text-[10px] font-black uppercase text-red-600"><span>Aula no Ciclo</span><span>{info?.currentCycleClass} de 4</span></div>
                  </div>
                  <button onClick={() => setEditingStudent(s)} className="w-full bg-black text-white py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-red-600 transition-all">Editar Perfil</button>
                </div>
              );
            })}
          </div>
        )}

        {activeView === 'courses' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {courses.map(course => (
                <div key={course.id} className="bg-black text-white p-6 md:p-10 rounded-[2.5rem] md:rounded-[3rem] shadow-xl border border-white/5 relative group">
                  <span className="text-red-600 text-[10px] font-black uppercase tracking-widest block mb-2">{course.instrument} | {course.level}</span>
                  <h3 className="text-xl md:text-2xl font-black uppercase tracking-tighter mb-6">{course.title}</h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <button onClick={() => setManagingAccessCourse(course)} className="bg-white/10 hover:bg-white text-white hover:text-black py-4 rounded-2xl text-[10px] font-black uppercase transition-all">Acessos</button>
                    <button onClick={() => setEditingCourseContent(course)} className="bg-red-600 hover:bg-red-700 text-white py-4 rounded-2xl text-[10px] font-black uppercase transition-all">Editar Aulas</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeView === 'schedules' && (
          <div className="space-y-8">
            <div className="bg-white rounded-[2rem] md:rounded-[2.5rem] border border-gray-100 overflow-x-auto shadow-sm custom-scrollbar">
               <table className="w-full text-left min-w-[600px]">
                 <thead className="bg-gray-50 border-b">
                   <tr>
                     <th className="p-6 md:p-8 text-[10px] font-black uppercase text-gray-400">Aluno</th>
                     <th className="p-6 md:p-8 text-[10px] font-black uppercase text-gray-400">Título / Tema</th>
                     <th className="p-6 md:p-8 text-[10px] font-black uppercase text-gray-400">Data & Hora</th>
                     <th className="p-6 md:p-8 text-[10px] font-black uppercase text-gray-400">Status</th>
                     <th className="p-6 md:p-8 text-[10px] font-black uppercase text-gray-400">Ações</th>
                   </tr>
                 </thead>
                 <tbody>
                   {schedules.map(sc => (
                     <tr key={sc.id} className="border-b last:border-0 hover:bg-gray-50 transition-colors">
                       <td className="p-6 md:p-8 text-xs font-black uppercase">{students.find(s => s.id === sc.studentId)?.name}</td>
                       <td className="p-6 md:p-8 text-xs font-bold text-red-600 italic uppercase">{sc.title}</td>
                       <td className="p-6 md:p-8 text-xs font-bold text-gray-400 uppercase">{new Date(sc.date).toLocaleDateString()} - {sc.time}</td>
                       <td className="p-6 md:p-8">
                         <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase ${
                           sc.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'
                         }`}>{sc.status}</span>
                       </td>
                       <td className="p-6 md:p-8">
                          <button 
                            onClick={() => onUpdateSchedule(sc.id, sc.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED')}
                            className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${
                              sc.status === 'COMPLETED' ? 'bg-gray-100 text-gray-400' : 'bg-red-600 text-white shadow-lg'
                            }`}
                          >
                            {sc.status === 'COMPLETED' ? 'Desmarcar' : 'Concluir Aula'}
                          </button>
                       </td>
                     </tr>
                   ))}
                 </tbody>
               </table>
            </div>
          </div>
        )}

        {activeView === 'payments' && (
          <div className="space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-red-600 p-8 md:p-10 rounded-[2.5rem] md:rounded-[3rem] text-white shadow-2xl shadow-red-600/20">
                <p className="text-[10px] font-black uppercase opacity-60 tracking-widest mb-2">Faturamento Mensal</p>
                <h3 className="text-4xl md:text-5xl font-black tracking-tighter italic">R$ {monthlyTotal.toLocaleString('pt-BR')}</h3>
              </div>
              <div className="bg-black p-8 md:p-10 rounded-[2.5rem] md:rounded-[3rem] text-white shadow-2xl">
                <p className="text-[10px] font-black uppercase opacity-60 tracking-widest mb-2">Faturamento Anual</p>
                <h3 className="text-4xl md:text-5xl font-black tracking-tighter italic">R$ {annualTotal.toLocaleString('pt-BR')}</h3>
              </div>
            </div>
            <div className="bg-white rounded-[2rem] md:rounded-[2.5rem] border border-gray-100 overflow-x-auto shadow-sm custom-scrollbar">
               <table className="w-full text-left min-w-[600px]">
                 <thead className="bg-gray-50 border-b">
                   <tr>
                     <th className="p-6 md:p-8 text-[10px] font-black uppercase text-gray-400">Aluno</th>
                     <th className="p-6 md:p-8 text-[10px] font-black uppercase text-gray-400">Valor</th>
                     <th className="p-6 md:p-8 text-[10px] font-black uppercase text-gray-400">Vencimento</th>
                     <th className="p-6 md:p-8 text-[10px] font-black uppercase text-gray-400">Ações</th>
                   </tr>
                 </thead>
                 <tbody>
                   {payments.map(p => (
                     <tr key={p.id} className="border-b last:border-0 hover:bg-gray-50 transition-colors">
                       <td className="p-6 md:p-8 text-xs font-black uppercase">{students.find(s => s.id === p.studentId)?.name}</td>
                       <td className="p-6 md:p-8 text-xs font-bold">R$ {p.amount.toFixed(2)}</td>
                       <td className="p-6 md:p-8 text-xs font-bold text-gray-400">{new Date(p.dueDate).toLocaleDateString()}</td>
                       <td className="p-6 md:p-8">
                         <button 
                           onClick={() => onUpdatePayment(p.id, { status: p.status === 'PAID' ? 'PENDING' : 'PAID' })}
                           className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase transition-all ${
                             p.status === 'PAID' ? 'bg-green-600 text-white' : 'bg-red-600 text-white'
                           }`}
                         >
                           {p.status === 'PAID' ? 'Pago' : 'Marcar Pago'}
                         </button>
                       </td>
                     </tr>
                   ))}
                 </tbody>
               </table>
            </div>
          </div>
        )}

        {managingAccessCourse && (
          <div className="fixed inset-0 bg-black/95 z-[300] flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-2xl rounded-[3rem] p-8 md:p-10 max-h-[80vh] flex flex-col shadow-2xl">
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-xl font-black uppercase italic tracking-tighter">Acessos: {managingAccessCourse.title}</h3>
                <button onClick={() => setManagingAccessCourse(null)} className="text-3xl font-black hover:text-red-600 transition-colors">&times;</button>
              </div>
              <div className="flex-1 overflow-y-auto space-y-4 pr-4 custom-scrollbar">
                {students.filter(s => s.role === 'STUDENT').map(s => (
                  <label key={s.id} className="flex items-center justify-between p-4 md:p-6 border-2 border-gray-100 rounded-2xl cursor-pointer hover:border-red-600 transition-all">
                    <div className="flex items-center gap-4">
                      <img src={s.avatar} className="w-10 h-10 rounded-full object-cover" />
                      <div>
                        <p className="text-xs font-black uppercase tracking-tight">{s.name}</p>
                        <p className="text-[9px] font-bold text-gray-400 uppercase">{s.instrument}</p>
                      </div>
                    </div>
                    <input 
                      type="checkbox" 
                      checked={managingAccessCourse.studentIds.includes(s.id)}
                      onChange={() => handleToggleAccess(managingAccessCourse.id, s.id)}
                      className="w-5 h-5 accent-red-600"
                    />
                  </label>
                ))}
              </div>
              <button onClick={() => setManagingAccessCourse(null)} className="w-full mt-8 bg-black text-white py-5 rounded-3xl text-xs font-black uppercase shadow-xl">Finalizar Gerenciamento</button>
            </div>
          </div>
        )}

        {editingCourseContent && (
          <div className="fixed inset-0 bg-white z-[400] overflow-y-auto flex flex-col">
            <header className="bg-black text-white p-6 sticky top-0 flex justify-between items-center z-10 shadow-xl">
              <h2 className="text-lg md:text-2xl font-black uppercase tracking-tighter italic truncate mr-4">Editando: {editingCourseContent.title}</h2>
              <div className="flex gap-2 md:gap-4 shrink-0">
                <button onClick={() => setEditingCourseContent(null)} className="px-3 md:px-6 py-2 text-[8px] md:text-[10px] font-black uppercase text-gray-400 hover:text-white">Cancelar</button>
                <button 
                  onClick={async () => { setIsSyncing(true); await onUpdateCourseContent(editingCourseContent); setIsSyncing(false); setEditingCourseContent(null); }}
                  className="bg-red-600 text-white px-4 md:px-8 py-3 rounded-2xl text-[8px] md:text-[10px] font-black uppercase shadow-lg shadow-red-600/30"
                >
                  Salvar Aulas
                </button>
              </div>
            </header>
            <div className="max-w-4xl mx-auto w-full p-6 md:p-12 space-y-12 pb-20">
              <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center border-b-4 border-black pb-4 gap-4">
                <h3 className="text-2xl md:text-3xl font-black uppercase tracking-tighter italic">Módulos & Conteúdo</h3>
                <button onClick={addModule} className="w-full sm:w-auto bg-black text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase hover:bg-red-600 transition-all">+ Novo Módulo</button>
              </div>
              <div className="space-y-12">
                {editingCourseContent.modules?.map((mod) => (
                  <div key={mod.id} className="bg-gray-50 rounded-[2.5rem] md:rounded-[3rem] p-6 md:p-10 border border-gray-200 shadow-sm relative">
                    <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 mb-10">
                      <input 
                        value={mod.title} 
                        onChange={e => { const updated = editingCourseContent.modules.map(m => m.id === mod.id ? { ...m, title: e.target.value } : m); setEditingCourseContent({...editingCourseContent, modules: updated}); }}
                        className="w-full sm:flex-1 bg-transparent text-xl md:text-2xl font-black uppercase tracking-tighter border-b-2 border-gray-300 py-2 outline-none focus:border-red-600 transition-colors"
                      />
                      <button onClick={() => { const updated = editingCourseContent.modules.filter(m => m.id !== mod.id); setEditingCourseContent({...editingCourseContent, modules: updated}); }} className="text-red-600 font-black text-[9px] uppercase hover:underline">Remover Módulo</button>
                    </div>
                    <div className="space-y-8">
                      {mod.lessons.map((lesson) => (
                        <div key={lesson.id} className="bg-white border-2 border-gray-100 p-6 md:p-8 rounded-[2rem] md:rounded-[2.5rem] shadow-sm group hover:border-red-600 transition-all">
                          <div className="flex justify-between items-start mb-8 gap-4">
                            <input 
                              value={lesson.title} 
                              onChange={e => updateLesson(mod.id, lesson.id, { title: e.target.value })}
                              className="font-black uppercase text-sm md:text-base outline-none bg-transparent flex-1 border-b border-dashed border-gray-200 focus:border-red-600" 
                              placeholder="Nome da Aula" 
                            />
                            <button onClick={() => { const updated = editingCourseContent.modules.map(m => m.id === mod.id ? { ...m, lessons: m.lessons.filter(l => l.id !== lesson.id) } : m); setEditingCourseContent({...editingCourseContent, modules: updated}); }} className="text-gray-300 hover:text-red-600 text-[10px] font-black uppercase">Remover</button>
                          </div>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                            <div className="space-y-1">
                              <label className="text-[9px] font-black uppercase text-gray-400 ml-2">ID YouTube (Arranjo)</label>
                              <input value={lesson.videoArranjoUrl} onChange={e => updateLesson(mod.id, lesson.id, { videoArranjoUrl: e.target.value })} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" placeholder="Ex: dQw4w9WgXcQ" />
                            </div>
                            <div className="space-y-1">
                              <label className="text-[9px] font-black uppercase text-gray-400 ml-2">ID YouTube (Ao Vivo)</label>
                              <input value={lesson.videoAoVivoUrl} onChange={e => updateLesson(mod.id, lesson.id, { videoAoVivoUrl: e.target.value })} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold" placeholder="Ex: dQw4w9WgXcQ" />
                            </div>
                          </div>
                          <div className="flex items-center gap-2 mb-2">
                            <label className="text-[9px] font-black uppercase text-gray-400 ml-2">Descrição da Aula</label>
                            <button 
                              onClick={async () => { setIsSyncing(true); const d = await generateLessonDescription(lesson.title, editingCourseContent.instrument, editingCourseContent.level); updateLesson(mod.id, lesson.id, { description: d }); setIsSyncing(false); }}
                              className="text-[9px] font-black text-red-600 uppercase hover:scale-105 transition-transform"
                            >
                              ✨ Gerar com IA
                            </button>
                          </div>
                          <textarea value={lesson.description} onChange={e => updateLesson(mod.id, lesson.id, { description: e.target.value })} className="w-full border-2 border-gray-100 p-6 rounded-[1.5rem] text-xs font-medium resize-none focus:border-red-600 outline-none" rows={3} placeholder="Descreva o que o aluno aprenderá nesta aula..." />
                        </div>
                      ))}
                      <button onClick={() => addLesson(mod.id)} className="w-full border-2 border-dashed border-gray-300 py-6 rounded-[2rem] text-[10px] font-black uppercase text-gray-400 hover:border-red-600 hover:text-red-600 transition-all">+ Adicionar Aula</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {editingStudent && (
          <div className="fixed inset-0 bg-black/95 z-[500] flex items-center justify-center p-4">
            <form onSubmit={async (e) => { e.preventDefault(); await onUpdateStudent(editingStudent); setEditingStudent(null); }} className="bg-white w-full max-w-md rounded-[2.5rem] md:rounded-[3rem] p-8 md:p-10 space-y-8 animate-in zoom-in duration-300 shadow-2xl overflow-y-auto max-h-[90vh] custom-scrollbar">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xl md:text-2xl font-black uppercase italic tracking-tighter">Perfil do Aluno</h3>
                <button type="button" onClick={() => setEditingStudent(null)} className="text-3xl font-black hover:text-red-600 transition-colors">&times;</button>
              </div>
              <div className="flex flex-col items-center gap-6">
                <img src={editingStudent.avatar} className="w-32 h-32 rounded-full border-4 border-red-600 object-cover shadow-2xl" />
                <div className="flex flex-wrap justify-center gap-3">
                  <button type="button" onClick={() => setEditingStudent({...editingStudent, avatar: DEFAULT_AVATARS.male})} className="text-[9px] font-black uppercase bg-gray-100 px-4 py-2 rounded-xl hover:bg-black hover:text-white transition-all">Masc</button>
                  <button type="button" onClick={() => setEditingStudent({...editingStudent, avatar: DEFAULT_AVATARS.female})} className="text-[9px] font-black uppercase bg-gray-100 px-4 py-2 rounded-xl hover:bg-black hover:text-white transition-all">Fem</button>
                  <button type="button" onClick={() => fileInputRef.current?.click()} className="text-[9px] font-black uppercase bg-red-600 text-white px-4 py-2 rounded-xl shadow-lg">Upload</button>
                  <input type="file" ref={fileInputRef} onChange={e => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onloadend = () => setEditingStudent({...editingStudent, avatar: r.result as string}); r.readAsDataURL(f); } }} className="hidden" accept="image/*" />
                </div>
              </div>
              <div className="space-y-6">
                <div className="space-y-1">
                  <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Nome Completo</label>
                  <input value={editingStudent.name} onChange={e => setEditingStudent({...editingStudent, name: e.target.value})} className="w-full border-2 border-gray-100 p-4 rounded-[1.5rem] text-sm font-bold focus:border-red-600 outline-none" />
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Instrumento</label>
                    <select value={editingStudent.instrument} onChange={e => setEditingStudent({...editingStudent, instrument: e.target.value as Instrument})} className="w-full border-2 border-gray-100 p-4 rounded-[1.5rem] text-sm font-bold focus:border-red-600 outline-none">
                      <option value="Violão">Violão</option>
                      <option value="Piano">Piano</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Nível Atual</label>
                    <select value={editingStudent.level} onChange={e => setEditingStudent({...editingStudent, level: e.target.value as Level})} className="w-full border-2 border-gray-100 p-4 rounded-[1.5rem] text-sm font-bold focus:border-red-600 outline-none">
                      <option value="NZ">NZ</option><option value="N1">N1</option><option value="N2">N2</option><option value="N3">N3</option>
                    </select>
                  </div>
                </div>
              </div>
              <button type="submit" className="w-full bg-red-600 text-white py-6 rounded-[2rem] text-xs font-black uppercase shadow-xl hover:bg-black transition-all">Salvar Alterações</button>
            </form>
          </div>
        )}
      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button onClick={onClick} className={`w-full flex items-center px-4 py-4 text-[11px] font-black uppercase tracking-widest rounded-2xl mb-1 transition-all ${active ? 'bg-red-600 text-white shadow-lg shadow-red-600/20' : 'text-gray-500 hover:text-white hover:bg-white/5'}`}><span className="mr-3 text-lg">{icon}</span>{label}</button>
);

export default AdminDashboard;

import React, { useState, useMemo, useRef } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level, Module, Lesson } from '../types';
import { DEFAULT_AVATARS } from '../constants';
import { generateLessonDescription } from '../services/geminiService';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => Promise<void>;
  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onUpdateSchedule: (id: string, status: ScheduledClass['status']) => Promise<void>;
  onAddCourse: (c: Course) => Promise<void>;
  onUpdateCourseContent: (c: Course) => Promise<void>;
  onUpdateCourseAccess: (id: string, ids: string[]) => Promise<void>;
  onAddPayment: (p: Payment) => Promise<void>;
  onUpdatePayment: (id: string, updates: Partial<Payment>) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onUpdateSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment, onUpdatePayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [managingAccessCourse, setManagingAccessCourse] = useState<Course | null>(null);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);
  const [editingCourseContent, setEditingCourseContent] = useState<Course | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const { annualTotal, monthlyTotal } = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const annual = payments.filter(p => p.status === 'PAID' && new Date(p.dueDate).getFullYear() === currentYear).reduce((acc, curr) => acc + Number(curr.amount), 0);
    const monthly = payments.filter(p => { const d = new Date(p.dueDate); return p.status === 'PAID' && d.getMonth() === currentMonth && d.getFullYear() === currentYear; }).reduce((acc, curr) => acc + Number(curr.amount), 0);
    return { annualTotal: annual, monthlyTotal: monthly };
  }, [payments]);

  const getStudentCycleInfo = (studentId: string) => {
    const student = students.find(s => s.id === studentId);
    if (!student) return null;
    const completed = student.totalCompletedClasses || 0;
    const cycles = Math.floor(completed / 4);
    const currentCycleClass = (completed % 4) + 1;
    return { completed, cycles, currentCycleClass };
  };

  const handleToggleAccess = async (courseId: string, studentId: string) => {
    const course = courses.find(c => c.id === courseId);
    if (!course) return;
    let newIds = [...(course.studentIds || [])];
    if (newIds.includes(studentId)) {
      newIds = newIds.filter(id => id !== studentId);
    } else {
      newIds.push(studentId);
    }
    await onUpdateCourseAccess(courseId, newIds);
  };

  const addModule = () => {
    if (!editingCourseContent) return;
    const newModule: Module = { id: `mod-${Date.now()}`, title: `Novo Módulo`, lessons: [] };
    setEditingCourseContent({ ...editingCourseContent, modules: [...(editingCourseContent.modules || []), newModule] });
  };

  const addLesson = (moduleId: string) => {
    if (!editingCourseContent) return;
    const newLesson: Lesson = { id: `lesson-${Date.now()}`, title: 'Nova Aula', videoArranjoUrl: '', videoAoVivoUrl: '', description: '' };
    const updatedModules = editingCourseContent.modules.map(m => m.id === moduleId ? { ...m, lessons: [...m.lessons, newLesson] } : m);
    setEditingCourseContent({ ...editingCourseContent, modules: updatedModules });
  };

  const updateLesson = (modId: string, lesId: string, updates: Partial<Lesson>) => {
    if (!editingCourseContent) return;
    const updated = editingCourseContent.modules.map(m => m.id === modId ? { ...m, lessons: m.lessons.map(l => l.id === lesId ? { ...l, ...updates } : l) } : m);
    setEditingCourseContent({ ...editingCourseContent, modules: updated });
  };

  const SidebarContent = () => (
    <div className="flex flex-col h-full bg-black text-white">
      <div className="p-8 flex justify-between items-center">
        <div className="flex flex-col">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase">Painel</h2>
          <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Administrativo</span>
        </div>
        <button onClick={() => setIsSidebarOpen(false)} className="md:hidden text-white hover:text-red-600 transition-colors">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6L6 18M6 6l12 12"/></svg>
        </button>
      </div>
      <nav className="flex-1 px-4 space-y-2">
        <SidebarLink 
          active={activeView === 'students'} 
          onClick={() => { setActiveView('students'); setIsSidebarOpen(false); }} 
          icon="👥" label="Alunos" 
        />
        <SidebarLink 
          active={activeView === 'courses'} 
          onClick={() => { setActiveView('courses'); setIsSidebarOpen(false); }} 
          icon="🎹" label="Cursos" 
        />
        <SidebarLink 
          active={activeView === 'schedules'} 
          onClick={() => { setActiveView('schedules'); setIsSidebarOpen(false); }} 
          icon="📅" label="Agenda" 
        />
        <SidebarLink 
          active={activeView === 'payments'} 
          onClick={() => { setActiveView('payments'); setIsSidebarOpen(false); }} 
          icon="💰" label="Financeiro" 
        />
      </nav>
      <div className="p-8 border-t border-white/10">
