               <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                 <path d="M4 6H20M4 12H20M4 18H20" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>
               </svg>
             </button>
             <div className="flex flex-col">
               <h1 className="text-xl md:text-3xl font-black uppercase tracking-tighter truncate leading-none">
                 {activeView === 'students' && "Gerenciar Alunos"}
                 {activeView === 'courses' && "Gestão de Cursos"}
                 {activeView === 'schedules' && "Agenda de Aulas"}
                 {activeView === 'payments' && "Relatórios Financeiros"}
               </h1>
               <p className="hidden md:block text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">Escola Como Tocar Hinos</p>
             </div>
           </div>

           <div className="flex items-center gap-4">
             <div className={`shrink-0 px-4 py-1.5 rounded-full text-[8px] md:text-[9px] font-black uppercase ${isSyncing ? 'bg-yellow-500 text-black' : 'bg-green-600 text-white shadow-lg shadow-green-600/20'}`}>
               {isSyncing ? "Sincronizando..." : "Sincronizado"}
             </div>
             <img src={user.avatar} className="w-8 h-8 rounded-full border-2 border-red-600 hidden sm:block" alt="Admin" />
