                  <div className="grid grid-cols-2 gap-3 mt-auto">
                    <button onClick={() => setManagingAccessCourse(course)} className="bg-white/10 hover:bg-white text-white hover:text-black py-4 rounded-2xl text-[9px] font-black uppercase transition-all">Acessos</button>
                    <button onClick={() => setEditingCourseContent(course)} className="bg-red-600 hover:bg-red-700 text-white py-4 rounded-2xl text-[9px] font-black uppercase transition-all shadow-lg shadow-red-600/20">Aulas</button>
                  </div>
                </div>
