                      <input 
                        value={mod.title} 
                        onChange={e => { const updated = editingCourseContent.modules.map(m => m.id === mod.id ? { ...m, title: e.target.value } : m); setEditingCourseContent({...editingCourseContent, modules: updated}); }}
                        className="w-full sm:flex-1 bg-transparent text-2xl font-black uppercase tracking-tighter border-b-2 border-gray-300 py-3 outline-none focus:border-red-600 transition-colors"
                      />
                      <button onClick={() => { const updated = editingCourseContent.modules.filter(m => m.id !== mod.id); setEditingCourseContent({...editingCourseContent, modules: updated}); }} className="text-red-600 font-black text-[10px] uppercase bg-white px-4 py-2 rounded-xl shadow-sm hover:bg-red-600 hover:text-white transition-all">Deletar</button>
                    </div>
                    <div className="space-y-10">
                      {mod.lessons.map((lesson) => (
                        <div key={lesson.id} className="bg-white border border-gray-100 p-8 rounded-[2.5rem] shadow-sm hover:shadow-md transition-all">
                          <div className="flex justify-between items-start mb-8 gap-4">
                            <input 
                              value={lesson.title} 
                              onChange={e => updateLesson(mod.id, lesson.id, { title: e.target.value })}
                              className="font-black uppercase text-base outline-none bg-transparent flex-1 border-b border-dashed border-gray-200 focus:border-red-600" 
                              placeholder="Título da Videoaula" 
                            />
                            <button onClick={() => { const updated = editingCourseContent.modules.map(m => m.id === mod.id ? { ...m, lessons: m.lessons.filter(l => l.id !== lesson.id) } : m); setEditingCourseContent({...editingCourseContent, modules: updated}); }} className="text-gray-300 hover:text-red-600 transition-colors">
                              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M6 18L18 6M6 6l12 12"/></svg>
                            </button>
                          </div>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
                            <div className="space-y-2">
                              <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Link Vídeo (Tutor)</label>
                              <input value={lesson.videoArranjoUrl} onChange={e => updateLesson(mod.id, lesson.id, { videoArranjoUrl: e.target.value })} className="w-full border-2 border-gray-50 p-5 rounded-2xl text-xs font-bold bg-gray-50 focus:bg-white transition-all outline-none" />
                            </div>
                            <div className="space-y-2">
                              <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Link Vídeo (Base)</label>
                              <input value={lesson.videoAoVivoUrl} onChange={e => updateLesson(mod.id, lesson.id, { videoAoVivoUrl: e.target.value })} className="w-full border-2 border-gray-50 p-5 rounded-2xl text-xs font-bold bg-gray-50 focus:bg-white transition-all outline-none" />
                            </div>
                          </div>
                          <div className="flex items-center gap-3 mb-3">
                            <label className="text-[10px] font-black uppercase text-gray-400 ml-4">Sinopse da Aula</label>
                            <button 
                              onClick={async () => { setIsSyncing(true); const d = await generateLessonDescription(lesson.title, editingCourseContent.instrument, editingCourseContent.level); updateLesson(mod.id, lesson.id, { description: d }); setIsSyncing(false); }}
                              className="text-[10px] font-black text-red-600 uppercase flex items-center gap-1 hover:underline"
                            >
                              ✨ Gerar com IA
                            </button>
                          </div>
                          <textarea value={lesson.description} onChange={e => updateLesson(mod.id, lesson.id, { description: e.target.value })} className="w-full border-2 border-gray-50 p-6 rounded-[2rem] text-xs font-medium resize-none bg-gray-50 focus:bg-white outline-none focus:border-red-600 transition-all" rows={4} />
                        </div>
                      ))}
                      <button onClick={() => addLesson(mod.id)} className="w-full border-4 border-dashed border-gray-200 py-10 rounded-[3rem] text-[11px] font-black uppercase text-gray-300 hover:border-red-600 hover:text-red-600 transition-all">+ Nova Aula neste Módulo</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {editingStudent && (
          <div className="fixed inset-0 bg-black/95 z-[500] flex items-center justify-center p-4 backdrop-blur-md">
            <form onSubmit={async (e) => { e.preventDefault(); await onUpdateStudent(editingStudent); setEditingStudent(null); }} className="bg-white w-full max-w-md rounded-[4rem] p-10 space-y-10 animate-in zoom-in duration-300 shadow-2xl overflow-y-auto max-h-[95vh] custom-scrollbar relative">
              <div className="flex justify-between items-center">
                <h3 className="text-3xl font-black uppercase italic tracking-tighter">Ficha Aluno</h3>
                <button type="button" onClick={() => setEditingStudent(null)} className="text-4xl font-black hover:text-red-600 transition-colors">&times;</button>
              </div>
              <div className="flex flex-col items-center gap-6">
                <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                   <img src={editingStudent.avatar} className="w-40 h-40 rounded-full border-4 border-red-600 object-cover shadow-2xl transition-transform group-hover:scale-105" alt="Avatar" />
                   <div className="absolute bottom-2 right-2 bg-black text-white p-2 rounded-full border-2 border-white">📸</div>
                   <input type="file" ref={fileInputRef} onChange={e => { const f = e.target.files?.[0]; if (f) { const r = new FileReader(); r.onloadend = () => setEditingStudent({...editingStudent, avatar: r.result as string}); r.readAsDataURL(f); } }} className="hidden" accept="image/*" />
                </div>
                <div className="flex gap-4">
                  <button type="button" onClick={() => setEditingStudent({...editingStudent, avatar: DEFAULT_AVATARS.male})} className="text-[10px] font-black uppercase bg-gray-100 px-6 py-2.5 rounded-2xl hover:bg-black hover:text-white transition-all">Masculino</button>
                  <button type="button" onClick={() => setEditingStudent({...editingStudent, avatar: DEFAULT_AVATARS.female})} className="text-[10px] font-black uppercase bg-gray-100 px-6 py-2.5 rounded-2xl hover:bg-black hover:text-white transition-all">Feminino</button>
                </div>
              </div>
              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-gray-400 ml-6">Nome Completo</label>
                  <input value={editingStudent.name} onChange={e => setEditingStudent({...editingStudent, name: e.target.value})} className="w-full border-2 border-gray-100 p-5 rounded-[2.5rem] text-sm font-bold focus:border-red-600 outline-none transition-all shadow-sm" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-6">Instrumento</label>
                    <select value={editingStudent.instrument} onChange={e => setEditingStudent({...editingStudent, instrument: e.target.value as Instrument})} className="w-full border-2 border-gray-100 p-5 rounded-[2.5rem] text-sm font-bold focus:border-red-600 outline-none appearance-none">
                      <option value="Violão">Violão</option>
                      <option value="Piano">Piano</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-6">Nível</label>
                    <select value={editingStudent.level} onChange={e => setEditingStudent({...editingStudent, level: e.target.value as Level})} className="w-full border-2 border-gray-100 p-5 rounded-[2.5rem] text-sm font-bold focus:border-red-600 outline-none appearance-none">
                      <option value="NZ">NZ</option><option value="N1">N1</option><option value="N2">N2</option><option value="N3">N3</option>
                    </select>
                  </div>
                </div>
              </div>
              <button type="submit" className="w-full bg-red-600 text-white py-6 rounded-[2.5rem] text-xs font-black uppercase shadow-2xl hover:bg-black transition-all active:scale-95">Salvar Prontuário</button>
            </form>
          </div>
        )}
      </main>
    </div>
  );
};

const SidebarLink: React.FC<{ active: boolean; onClick: () => void; icon: string; label: string }> = ({ active, onClick, icon, label }) => (
  <button onClick={onClick} className={`w-full flex items-center px-6 py-5 text-[11px] font-black uppercase tracking-[0.2em] rounded-3xl mb-1 transition-all active:scale-95 ${active ? 'bg-red-600 text-white shadow-xl shadow-red-600/30' : 'text-gray-500 hover:text-white hover:bg-white/5'}`}>
    <span className="mr-4 text-xl">{icon}</span>
    {label}
  </button>
);

export default AdminDashboard;

import React, { useState, useMemo, useRef } from 'react';
import { User, Course, ScheduledClass, Payment, Material, Instrument, Level, Module, Lesson } from '../types';
import { DEFAULT_AVATARS } from '../constants';
import { generateLessonDescription } from '../services/geminiService';

interface AdminDashboardProps {
  user: User;
  onLogout: () => void;
  students: User[];
  courses: Course[];
  schedules: ScheduledClass[];
  payments: Payment[];
  materials: Material[];
  onAddStudent: (s: User) => Promise<void>;
  onUpdateStudent: (s: User) => Promise<void>;
  onAddSchedule: (sc: ScheduledClass) => Promise<void>;
  onUpdateSchedule: (id: string, status: ScheduledClass['status']) => Promise<void>;
  onAddCourse: (c: Course) => Promise<void>;
  onUpdateCourseContent: (c: Course) => Promise<void>;
  onUpdateCourseAccess: (id: string, ids: string[]) => Promise<void>;
  onAddPayment: (p: Payment) => Promise<void>;
  onUpdatePayment: (id: string, updates: Partial<Payment>) => Promise<void>;
}

type AdminView = 'students' | 'courses' | 'schedules' | 'payments';

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  user, onLogout, students, courses, schedules, payments, materials, 
  onAddStudent, onUpdateStudent, onAddSchedule, onUpdateSchedule, onAddCourse, onUpdateCourseContent, onUpdateCourseAccess, onAddPayment, onUpdatePayment 
}) => {
  const [activeView, setActiveView] = useState<AdminView>('students');
  const [isSyncing, setIsSyncing] = useState(false);
  const [managingAccessCourse, setManagingAccessCourse] = useState<Course | null>(null);
  const [editingStudent, setEditingStudent] = useState<User | null>(null);
  const [editingCourseContent, setEditingCourseContent] = useState<Course | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const { annualTotal, monthlyTotal } = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const annual = payments.filter(p => p.status === 'PAID' && new Date(p.dueDate).getFullYear() === currentYear).reduce((acc, curr) => acc + Number(curr.amount), 0);
    const monthly = payments.filter(p => { const d = new Date(p.dueDate); return p.status === 'PAID' && d.getMonth() === currentMonth && d.getFullYear() === currentYear; }).reduce((acc, curr) => acc + Number(curr.amount), 0);
    return { annualTotal: annual, monthlyTotal: monthly };
  }, [payments]);

  const getStudentCycleInfo = (studentId: string) => {
    const student = students.find(s => s.id === studentId);
    if (!student) return null;
    const completed = student.totalCompletedClasses || 0;
    const cycles = Math.floor(completed / 4);
    const currentCycleClass = (completed % 4) + 1;
    return { completed, cycles, currentCycleClass };
  };

  const handleToggleAccess = async (courseId: string, studentId: string) => {
    const course = courses.find(c => c.id === courseId);
    if (!course) return;
    let newIds = [...(course.studentIds || [])];
    if (newIds.includes(studentId)) {
      newIds = newIds.filter(id => id !== studentId);
    } else {
      newIds.push(studentId);
    }
    await onUpdateCourseAccess(courseId, newIds);
  };

  const addModule = () => {
    if (!editingCourseContent) return;
    const newModule: Module = { id: `mod-${Date.now()}`, title: `Novo Módulo`, lessons: [] };
    setEditingCourseContent({ ...editingCourseContent, modules: [...(editingCourseContent.modules || []), newModule] });
  };

  const addLesson = (moduleId: string) => {
    if (!editingCourseContent) return;
    const newLesson: Lesson = { id: `lesson-${Date.now()}`, title: 'Nova Aula', videoArranjoUrl: '', videoAoVivoUrl: '', description: '' };
    const updatedModules = editingCourseContent.modules.map(m => m.id === moduleId ? { ...m, lessons: [...m.lessons, newLesson] } : m);
    setEditingCourseContent({ ...editingCourseContent, modules: updatedModules });
  };

  const updateLesson = (modId: string, lesId: string, updates: Partial<Lesson>) => {
    if (!editingCourseContent) return;
    const updated = editingCourseContent.modules.map(m => m.id === modId ? { ...m, lessons: m.lessons.map(l => l.id === lesId ? { ...l, ...updates } : l) } : m);
    setEditingCourseContent({ ...editingCourseContent, modules: updated });
  };

  const SidebarContent = () => (
    <div className="flex flex-col h-full bg-black text-white">
      <div className="p-8 flex justify-between items-center">
        <div className="flex flex-col">
          <h2 className="text-2xl font-black text-red-600 tracking-tighter uppercase">Painel</h2>
          <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Administrativo</span>
        </div>
        <button onClick={() => setIsSidebarOpen(false)} className="md:hidden text-white hover:text-red-600 transition-colors">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6L6 18M6 6l12 12"/></svg>
        </button>
      </div>
      <nav className="flex-1 px-4 space-y-2">
        <SidebarLink 
          active={activeView === 'students'} 
          onClick={() => { setActiveView('students'); setIsSidebarOpen(false); }} 
          icon="👥" label="Alunos" 
        />
        <SidebarLink 
          active={activeView === 'courses'} 
          onClick={() => { setActiveView('courses'); setIsSidebarOpen(false); }} 
          icon="🎹" label="Cursos" 
        />
        <SidebarLink 
          active={activeView === 'schedules'} 
          onClick={() => { setActiveView('schedules'); setIsSidebarOpen(false); }} 
          icon="📅" label="Agenda" 
        />
        <SidebarLink 
          active={activeView === 'payments'} 
          onClick={() => { setActiveView('payments'); setIsSidebarOpen(false); }} 
          icon="💰" label="Financeiro" 
        />
      </nav>
      <div className="p-8 border-t border-white/10">
        <button onClick={onLogout} className="text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all w-full text-left flex items-center gap-2">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
          Sair do Admin
        </button>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-white overflow-hidden relative">
      {/* Sidebar Desktop */}
      <aside className="w-64 hidden md:block shrink-0 border-r border-gray-100">
        <SidebarContent />
      </aside>

      {/* Sidebar Mobile (Floating Drawer) */}
      <div 
        className={`fixed inset-0 bg-black/80 backdrop-blur-sm z-[300] md:hidden transition-opacity duration-300 ${isSidebarOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`} 
        onClick={() => setIsSidebarOpen(false)}
      >
        <aside 
          className={`w-72 h-full bg-black transform transition-transform duration-300 ease-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}
          onClick={(e) => e.stopPropagation()}
        >
          <SidebarContent />
        </aside>
      </div>

      <main className="flex-1 flex flex-col min-w-0 bg-white">
        {/* Sticky Header Mobile & Desktop */}
        <header className="sticky top-0 z-[200] bg-white/90 backdrop-blur-md px-4 md:px-8 py-3 md:py-6 flex justify-between items-center border-b border-gray-50">
           <div className="flex items-center gap-3 md:gap-4">
             <button 
               onClick={() => setIsSidebarOpen(true)} 
               className="md:hidden bg-black text-white p-2.5 rounded-xl shadow-xl active:scale-95 transition-transform"
             >
               <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                 <path d="M4 6H20M4 12H20M4 18H20" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>
               </svg>
             </button>
             <div className="flex flex-col">
               <h1 className="text-lg md:text-3xl font-black uppercase tracking-tighter truncate leading-none">
                 {activeView === 'students' && "Alunos"}
                 {activeView === 'courses' && "Cursos"}
                 {activeView === 'schedules' && "Agenda"}
                 {activeView === 'payments' && "Financeiro"}
               </h1>
               <p className="hidden md:block text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">Escola Como Tocar Hinos</p>
             </div>
           </div>

           <div className="flex items-center gap-3">
             <div className={`shrink-0 px-3 py-1 rounded-full text-[7px] md:text-[9px] font-black uppercase ${isSyncing ? 'bg-yellow-500 text-black' : 'bg-green-600 text-white shadow-lg shadow-green-600/20'}`}>
               {isSyncing ? "..." : "OK"}
             </div>
             <img src={user.avatar} className="w-7 h-7 md:w-8 md:h-8 rounded-full border-2 border-red-600" alt="Admin" />
           </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {activeView === 'students' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-8">
              {students.filter(s => s.role === 'STUDENT').map(s => {
                const info = getStudentCycleInfo(s.id);
                return (
                  <div key={s.id} className="p-4 md:p-8 bg-white border border-gray-100 rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm hover:border-red-600 hover:shadow-lg transition-all group">
                    <div className="flex flex-col items-center mb-4 md:mb-6">
                      <div className="relative mb-3 md:mb-4">
                        <img src={s.avatar || DEFAULT_AVATARS.male} className="w-16 h-16 md:w-20 md:h-20 rounded-full border-4 border-gray-50 object-cover shadow-lg group-hover:scale-105 transition-transform" />
                        <div className="absolute bottom-0 right-0 w-5 h-5 bg-green-500 border-[3px] border-white rounded-full"></div>
                      </div>
                      <h3 className="font-black uppercase text-sm md:text-base tracking-tight text-center line-clamp-1">{s.name}</h3>
                      <p className="text-[8px] md:text-[9px] font-black text-red-600 uppercase tracking-widest mt-0.5">{s.instrument} • {s.level}</p>
                    </div>
                    <div className="bg-gray-50 p-3 md:p-4 rounded-xl md:rounded-2xl mb-4 md:mb-6 space-y-1 md:space-y-2">
                      <div className="flex justify-between text-[8px] md:text-[9px] font-black uppercase">
                        <span className="text-gray-400">Ciclos</span>
                        <span>{info?.cycles}</span>
                      </div>
                      <div className="flex justify-between text-[8px] md:text-[9px] font-black uppercase text-red-600">
                        <span>Aula</span>
                        <span>{info?.currentCycleClass} / 4</span>
                      </div>
                    </div>
                    <button 
                      onClick={() => setEditingStudent(s)} 
                      className="w-full bg-black text-white py-3 md:py-4 rounded-xl md:rounded-2xl text-[8px] md:text-[9px] font-black uppercase hover:bg-red-600 transition-all active:scale-95 shadow-lg"
                    >
                      Editar
                    </button>
                  </div>
                );
              })}
            </div>
          )}

          {activeView === 'courses' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-8">
              {courses.map(course => (
                <div key={course.id} className="bg-gray-950 text-white p-5 md:p-10 rounded-[2rem] md:rounded-[3rem] shadow-2xl border border-white/5 relative flex flex-col h-full">
                  <div className="flex justify-between items-start mb-3 md:mb-4">
                    <span className="text-red-600 text-[8px] md:text-[10px] font-black uppercase tracking-widest">{course.instrument} | {course.level}</span>
                    <span className="bg-white/10 px-2.5 py-1 rounded-full text-[7px] md:text-[8px] font-black uppercase">{course.modules?.length || 0} Mód.</span>
                  </div>
                  <h3 className="text-lg md:text-2xl font-black uppercase tracking-tighter mb-6 md:mb-8 leading-tight flex-1">{course.title}</h3>
                  <div className="grid grid-cols-2 gap-2 md:gap-3 mt-auto">
                    <button onClick={() => setManagingAccessCourse(course)} className="bg-white/10 hover:bg-white text-white hover:text-black py-3 md:py-4 rounded-xl md:rounded-2xl text-[8px] md:text-[9px] font-black uppercase transition-all">Acessos</button>
                    <button onClick={() => setEditingCourseContent(course)} className="bg-red-600 hover:bg-red-700 text-white py-3 md:py-4 rounded-xl md:rounded-2xl text-[8px] md:text-[9px] font-black uppercase transition-all shadow-lg">Aulas</button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {activeView === 'schedules' && (
            <div className="bg-white rounded-[1.5rem] md:rounded-[2.5rem] border border-gray-100 shadow-sm overflow-hidden">
               <div className="overflow-x-auto custom-scrollbar">
                 <table className="w-full text-left min-w-[800px]">
                   <thead className="bg-gray-50 border-b">
                     <tr>
                       <th className="p-6 md:p-8 text-[9px] md:text-[10px] font-black uppercase text-gray-400">Aluno</th>
                       <th className="p-6 md:p-8 text-[9px] md:text-[10px] font-black uppercase text-gray-400">Conteúdo</th>
                       <th className="p-6 md:p-8 text-[9px] md:text-[10px] font-black uppercase text-gray-400">Agendamento</th>
                       <th className="p-6 md:p-8 text-[9px] md:text-[10px] font-black uppercase text-gray-400">Status</th>
                       <th className="p-6 md:p-8 text-[9px] md:text-[10px] font-black uppercase text-gray-400 text-center">Ação</th>
                     </tr>
                   </thead>
                   <tbody>
                     {schedules.map(sc => (
                       <tr key={sc.id} className="border-b last:border-0 hover:bg-gray-50 transition-colors group">
                         <td className="p-6 md:p-8">
                            <div className="flex items-center gap-2 md:gap-3">
                              <img src={students.find(s => s.id === sc.studentId)?.avatar} className="w-7 h-7 md:w-8 md:h-8 rounded-full" alt="S" />
                              <span className="text-[10px] md:text-xs font-black uppercase">{students.find(s => s.id === sc.studentId)?.name}</span>
                            </div>
                         </td>
                         <td className="p-6 md:p-8 text-[10px] md:text-xs font-bold text-red-600 italic uppercase">{sc.title || 'Aula Individual'}</td>
                         <td className="p-6 md:p-8">
                            <p className="text-[10px] md:text-xs font-black uppercase">{new Date(sc.date).toLocaleDateString()}</p>
                            <p className="text-[9px] md:text-[10px] font-bold text-gray-400 uppercase">{sc.time}</p>
                         </td>
                         <td className="p-6 md:p-8">
                           <span className={`px-3 md:px-4 py-1.5 rounded-full text-[7px] md:text-[8px] font-black uppercase ${
                             sc.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'
                           }`}>{sc.status === 'COMPLETED' ? 'OK' : 'Pendente'}</span>
                         </td>
                         <td className="p-6 md:p-8 text-center">
                            <button 
                              onClick={() => onUpdateSchedule(sc.id, sc.status === 'COMPLETED' ? 'PENDING' : 'COMPLETED')}
                              className={`px-4 md:px-6 py-2 md:py-3 rounded-xl text-[8px] md:text-[9px] font-black uppercase transition-all active:scale-95 ${
