                    </select>
                  </div>
                </div>
              </div>
              <button type="submit" className="w-full bg-red-600 text-white py-4 md:py-6 rounded-2xl md:rounded-[2.5rem] text-[10px] md:text-xs font-black uppercase shadow-2xl hover:bg-black transition-all">Salvar</button>
