import React, { useState, useRef } from 'react';
import { User, Course, ScheduledClass, Material, Payment } from '../types';
import CoursePlayer from './CoursePlayer';
import { DEFAULT_AVATARS } from '../constants';

interface StudentDashboardProps {
  user: User;
  onLogout: () => void;
  courses: Course[];
  schedules: ScheduledClass[];
  materials: Material[];
  payments: Payment[];
  onUpdateProfile: (user: User) => Promise<void>;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ 
  user, onLogout, courses, schedules, materials, payments, onUpdateProfile
}) => {
  const [viewingCourse, setViewingCourse] = useState<Course | null>(null);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileForm, setProfileForm] = useState<User>(user);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const myCourses = courses.filter(c => c.studentIds?.includes(user.id));
  const mySchedules = schedules.filter(s => s.studentId === user.id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const handleProfileSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    await onUpdateProfile(profileForm);
    setIsSaving(false);
    setIsEditingProfile(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfileForm({ ...profileForm, avatar: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const MusicNoteIcon = () => (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className="text-white">
      <path d="M9 18V5L21 3V16" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
      <circle cx="6" cy="18" r="3" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
      <circle cx="18" cy="16" r="3" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
    </svg>
  );

  if (viewingCourse) {
    return (
      <div className="min-h-screen bg-white">
        <header className="bg-black text-white h-14 md:h-16 flex items-center px-4 md:px-8 border-b border-white/5">
          <div className="flex-1 font-black uppercase italic tracking-tighter text-lg md:text-2xl flex items-center gap-2">
             <div className="bg-red-600 p-1 rounded-md md:p-1.5 md:rounded-lg">
               <MusicNoteIcon />
             </div>
             <span>Aula Online</span>
          </div>
          <button onClick={() => setViewingCourse(null)} className="bg-red-600 text-white px-4 md:px-8 py-2 rounded-xl text-[9px] md:text-[10px] font-black uppercase shadow-lg shadow-red-600/30">Painel</button>
        </header>
        <CoursePlayer course={viewingCourse} onBack={() => setViewingCourse(null)} materials={materials} />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white pb-20">
      <header className="bg-black text-white px-4 md:px-8 py-3 md:py-6 flex justify-between items-center sticky top-0 z-50 border-b border-white/5 backdrop-blur-md bg-black/95">
        <div className="flex items-center gap-2 md:gap-3">
          <div className="bg-white/10 p-1.5 md:p-2 rounded-lg border border-white/10">
            <MusicNoteIcon />
          </div>
          <div className="hidden sm:block">
            <h1 className="text-lg md:text-xl font-black uppercase tracking-tighter leading-none">
              Como <span className="text-red-600">Tocar</span> Hinos
            </h1>
            <p className="text-[8px] md:text-[9px] font-black text-red-600 uppercase tracking-widest leading-none mt-1">Toque Sacro de Forma Fácil</p>
          </div>
        </div>
        <div className="flex items-center gap-3 md:gap-6">
          <div className="flex items-center gap-3 md:gap-4 text-right">
            <div className="hidden md:block">
              <p className="text-sm font-black uppercase leading-none">{user.name}</p>
              <p className="text-[9px] text-gray-500 uppercase font-black tracking-widest mt-1.5">{user.instrument} • {user.level}</p>
            </div>
            <img 
              src={user.avatar || DEFAULT_AVATARS.male} 
              className="w-8 h-8 md:w-10 md:h-10 rounded-full border-2 border-red-600 object-cover shadow-lg cursor-pointer hover:scale-110 transition-transform" 
              onClick={() => setIsEditingProfile(true)}
              alt="Avatar"
            />
          </div>
          <button onClick={onLogout} className="bg-white/10 px-4 md:px-6 py-2 md:py-2.5 rounded-xl text-[9px] md:text-[10px] font-black uppercase hover:bg-red-600 transition-all">Sair</button>
        </div>
