import React, { useState, useEffect, useRef } from 'react';

const Metronome: React.FC = () => {
  const [bpm, setBpm] = useState(60);
  const [playing, setPlaying] = useState(false);
  const timer = useRef<number | null>(null);
  const audioCtx = useRef<AudioContext | null>(null);

  const playClick = () => {
    if (!audioCtx.current) audioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    const osc = audioCtx.current.createOscillator();
    const envelope = audioCtx.current.createGain();

    osc.frequency.value = 880;
    envelope.gain.value = 1;
    envelope.gain.exponentialRampToValueAtTime(0.001, audioCtx.current.currentTime + 0.1);

    osc.connect(envelope);
    envelope.connect(audioCtx.current.destination);

    osc.start();
    osc.stop(audioCtx.current.currentTime + 0.1);
  };

  const toggleMetronome = () => {
    if (playing) {
      if (timer.current) clearInterval(timer.current);
      setPlaying(false);
    } else {
      const interval = (60 / bpm) * 1000;
      timer.current = window.setInterval(playClick, interval);
      setPlaying(true);
      playClick();
    }
  };

  useEffect(() => {
    if (playing) {
      if (timer.current) clearInterval(timer.current);
      const interval = (60 / bpm) * 1000;
      timer.current = window.setInterval(playClick, interval);
    }
    return () => { if (timer.current) clearInterval(timer.current); };
  }, [bpm, playing]);

  return (
    <div className="bg-black text-white p-6 md:p-10 rounded-[2.5rem] shadow-xl border border-gray-800">
      <div className="flex items-center justify-between mb-6">
        <span className="text-[9px] font-black uppercase text-red-600 tracking-widest">METRÔNOMO</span>
        <span className="text-2xl font-black italic">{bpm} BPM</span>
      </div>
      <input 
        type="range" min="40" max="220" value={bpm} 
        onChange={(e) => setBpm(parseInt(e.target.value))}
        className="w-full h-1.5 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-red-600 mb-8"
      />
      <button 
        onClick={toggleMetronome}
        className={`w-full py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all shadow-lg active:scale-95 ${
          playing ? 'bg-white text-black' : 'bg-red-600 text-white'
        }`}
      >
        {playing ? 'PARAR' : 'INICIAR'}
      </button>
    </div>
  );
};

