  const timer = useRef<number | null>(null);
  const audioCtx = useRef<AudioContext | null>(null);

  const initAudio = async () => {
    if (!audioCtx.current) {
      audioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtx.current.state === 'suspended') {
      await audioCtx.current.resume();
    }
  };

  const playClick = () => {
    if (!audioCtx.current) return;

    const osc = audioCtx.current.createOscillator();
    const envelope = audioCtx.current.createGain();

    osc.frequency.value = 880;
    envelope.gain.value = 1;
    envelope.gain.exponentialRampToValueAtTime(0.001, audioCtx.current.currentTime + 0.1);

    osc.connect(envelope);
    envelope.connect(audioCtx.current.destination);

    osc.start();
    osc.stop(audioCtx.current.currentTime + 0.1);
  };

  const toggleMetronome = async () => {
    await initAudio();

    if (playing) {
      if (timer.current) clearInterval(timer.current);
      setPlaying(false);
    } else {
      const interval = (60 / bpm) * 1000;
      timer.current = window.setInterval(playClick, interval);
      setPlaying(true);
      playClick();
    }
  };

  useEffect(() => {
    if (playing) {
      if (timer.current) clearInterval(timer.current);
      const interval = (60 / bpm) * 1000;
      timer.current = window.setInterval(playClick, interval);
    }
    return () => { if (timer.current) clearInterval(timer.current); };
  }, [bpm, playing]);

  return (
    <div className="bg-black text-white p-6 md:p-10 rounded-[2.5rem] shadow-xl border border-gray-800">
