import React, { useState, useEffect, useRef } from 'react';

const NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

const Tuner: React.FC = () => {
  const [isActive, setIsActive] = useState(false);
  const [note, setNote] = useState('--');
  const [cents, setCents] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const audioCtx = useRef<AudioContext | null>(null);
  const analyser = useRef<AnalyserNode | null>(null);
  const stream = useRef<MediaStream | null>(null);
  const animationRef = useRef<number | null>(null);

  const startTuner = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.current = mediaStream;

      audioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      analyser.current = audioCtx.current.createAnalyser();
      analyser.current.fftSize = 2048;

      const source = audioCtx.current.createMediaStreamSource(mediaStream);
      source.connect(analyser.current);

      setIsActive(true);
      setError(null);
      updatePitch();
    } catch (err) {
      setError('Acesso ao microfone negado ou não suportado.');
      console.error(err);
    }
  };

  const stopTuner = () => {
    setIsActive(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
    if (stream.current) {
      stream.current.getTracks().forEach(track => track.stop());
    }
    if (audioCtx.current) {
      audioCtx.current.close();
    }
    setNote('--');
    setCents(0);
  };

  const updatePitch = () => {
    if (!analyser.current) return;

    const bufferLength = analyser.current.fftSize;
    const buffer = new Float32Array(bufferLength);
    analyser.current.getFloatTimeDomainData(buffer);

    const pitch = autoCorrelate(buffer, audioCtx.current!.sampleRate);

    if (pitch !== -1) {
      const noteNum = 12 * (Math.log(pitch / 440) / Math.log(2));
      const roundedNote = Math.round(noteNum) + 69;
      const frequencyFromNote = 440 * Math.pow(2, (roundedNote - 69) / 12);
      const diffCents = Math.floor(1200 * (Math.log(pitch / frequencyFromNote) / Math.log(2)));

      setNote(NOTES[roundedNote % 12]);
      setCents(diffCents);
    }

    animationRef.current = requestAnimationFrame(updatePitch);
  };

  // Algoritmo de Autocorrelação para detecção de tom
  const autoCorrelate = (buffer: Float32Array, sampleRate: number) => {
    let size = buffer.length;
    let rms = 0;

    for (let i = 0; i < size; i++) {
      rms += buffer[i] * buffer[i];
    }
    rms = Math.sqrt(rms / size);
    if (rms < 0.01) return -1; // Sinal muito fraco

    let r1 = 0, r2 = size - 1, thres = 0.2;
    for (let i = 0; i < size / 2; i++) {
      if (Math.abs(buffer[i]) < thres) { r1 = i; break; }
    }
    for (let i = 1; i < size / 2; i++) {
      if (Math.abs(buffer[size - i]) < thres) { r2 = size - i; break; }
    }

    const buf = buffer.slice(r1, r2);
    size = buf.length;

    const c = new Float32Array(size);
    for (let i = 0; i < size; i++) {
      for (let j = 0; j < size - i; j++) {
        c[i] = c[i] + buf[j] * buf[j + i];
      }
    }

    let d = 0;
    while (c[d] > c[d + 1]) d++;
    let maxval = -1, maxpos = -1;
    for (let i = d; i < size; i++) {
      if (c[i] > maxval) {
        maxval = c[i];
        maxpos = i;
      }
    }

    let T0 = maxpos;
    return sampleRate / T0;
  };

  useEffect(() => {
    return () => stopTuner();
  }, []);

  return (
    <div className="bg-black text-white p-6 md:p-8 rounded-[2rem] border border-gray-800 shadow-xl flex flex-col justify-between min-h-[180px]">
      <div className="flex justify-between items-center mb-4">
        <span className="text-[8px] font-black uppercase text-red-600 tracking-widest">AFINADOR DIGITAL</span>
        <div className={`w-2 h-2 rounded-full shadow-[0_0_8px] transition-colors ${isActive ? 'bg-green-500 shadow-green-500 animate-pulse' : 'bg-gray-700'}`}></div>
      </div>

      {error ? (
        <p className="text-[8px] text-red-500 font-bold uppercase text-center">{error}</p>
      ) : (
        <>
          <div className="text-center py-2">
            <div className="text-4xl font-black tracking-tighter italic">{note}</div>
            <p className="text-[8px] uppercase font-bold text-gray-500 mt-1">
              {isActive ? (Math.abs(cents) < 5 ? 'AFINADO' : cents > 0 ? 'MUITO ALTO' : 'MUITO BAIXO') : 'PRONTO'}
            </p>
          </div>

          <div className="relative h-1 bg-gray-800 rounded-full mt-4 overflow-hidden">
            <div 
              className={`absolute top-0 bottom-0 w-1 transition-all duration-100 ${Math.abs(cents) < 5 ? 'bg-green-500' : 'bg-red-600'}`}
              style={{ left: `${50 + (cents / 50) * 50}%` }}
            ></div>
            <div className="absolute left-1/2 -translate-x-1/2 top-0 bottom-0 w-px bg-white/20"></div>
          </div>
        </>
      )}

      <button 
        onClick={isActive ? stopTuner : startTuner}
        className={`mt-6 py-2.5 rounded-xl text-[8px] font-black uppercase transition-all active:scale-95 ${isActive ? 'bg-gray-800 text-white' : 'bg-red-600 text-white shadow-lg shadow-red-600/20'}`}
      >
        {isActive ? 'DESLIGAR' : 'ATIVAR MICROFONE'}
      </button>
    </div>
  );
};

