import React, { useState, useEffect, useRef } from 'react';

const NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

const Tuner: React.FC = () => {
  const [isActive, setIsActive] = useState(false);
  const [note, setNote] = useState('--');
  const [cents, setCents] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  const audioCtx = useRef<AudioContext | null>(null);
  const analyser = useRef<AnalyserNode | null>(null);
  const stream = useRef<MediaStream | null>(null);
  const animationRef = useRef<number | null>(null);

  // Busca dispositivos de áudio disponíveis
  const getDevices = async () => {
    try {
      // Solicita permissão básica primeiro para que os nomes dos dispositivos apareçam
      const initialStream = await navigator.mediaDevices.getUserMedia({ audio: true });
      initialStream.getTracks().forEach(track => track.stop());

      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const audioInputs = allDevices.filter(device => device.kind === 'audioinput');
      setDevices(audioInputs);
      if (audioInputs.length > 0 && !selectedDeviceId) {
        setSelectedDeviceId(audioInputs[0].deviceId);
      }
    } catch (err) {
      console.error("Erro ao listar dispositivos:", err);
      setError("Permissão de áudio necessária para listar interfaces.");
    }
  };

  const startTuner = async () => {
    try {
      const constraints = {
        audio: selectedDeviceId ? { deviceId: { exact: selectedDeviceId } } : true
      };

      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      stream.current = mediaStream;

      audioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      analyser.current = audioCtx.current.createAnalyser();
      analyser.current.fftSize = 2048;

      const source = audioCtx.current.createMediaStreamSource(mediaStream);
      source.connect(analyser.current);

      setIsActive(true);
      setError(null);
      updatePitch();
    } catch (err) {
      setError('Erro ao acessar a interface selecionada.');
      console.error(err);
    }
  };

  const stopTuner = () => {
    setIsActive(false);
    if (animationRef.current) cancelAnimationFrame(animationRef.current);
    if (stream.current) {
      stream.current.getTracks().forEach(track => track.stop());
    }
    if (audioCtx.current) {
      audioCtx.current.close();
    }
    setNote('--');
    setCents(0);
  };

  const updatePitch = () => {
    if (!analyser.current) return;

    const bufferLength = analyser.current.fftSize;
    const buffer = new Float32Array(bufferLength);
    analyser.current.getFloatTimeDomainData(buffer);

    const pitch = autoCorrelate(buffer, audioCtx.current!.sampleRate);

    if (pitch !== -1) {
      const noteNum = 12 * (Math.log(pitch / 440) / Math.log(2));
      const roundedNote = Math.round(noteNum) + 69;
      const frequencyFromNote = 440 * Math.pow(2, (roundedNote - 69) / 12);
      const diffCents = Math.floor(1200 * (Math.log(pitch / frequencyFromNote) / Math.log(2)));

      setNote(NOTES[roundedNote % 12]);
      setCents(diffCents);
    }

    animationRef.current = requestAnimationFrame(updatePitch);
  };

  const autoCorrelate = (buffer: Float32Array, sampleRate: number) => {
    let size = buffer.length;
    let rms = 0;

    for (let i = 0; i < size; i++) {
      rms += buffer[i] * buffer[i];
    }
    rms = Math.sqrt(rms / size);
    if (rms < 0.01) return -1;

    let r1 = 0, r2 = size - 1, thres = 0.2;
    for (let i = 0; i < size / 2; i++) {
      if (Math.abs(buffer[i]) < thres) { r1 = i; break; }
    }
    for (let i = 1; i < size / 2; i++) {
      if (Math.abs(buffer[size - i]) < thres) { r2 = size - i; break; }
    }

    const buf = buffer.slice(r1, r2);
    size = buf.length;

    const c = new Float32Array(size);
    for (let i = 0; i < size; i++) {
      for (let j = 0; j < size - i; j++) {
        c[i] = c[i] + buf[j] * buf[j + i];
      }
    }

    let d = 0;
    while (c[d] > c[d + 1]) d++;
    let maxval = -1, maxpos = -1;
    for (let i = d; i < size; i++) {
      if (c[i] > maxval) {
        maxval = c[i];
        maxpos = i;
      }
    }

    let T0 = maxpos;
    return sampleRate / T0;
  };

  useEffect(() => {
    getDevices();
    return () => stopTuner();
  }, []);

  return (
    <div className="bg-black text-white p-6 md:p-8 rounded-[2rem] border border-gray-800 shadow-xl flex flex-col justify-between min-h-[220px]">
      <div className="flex justify-between items-center mb-2">
        <span className="text-[8px] font-black uppercase text-red-600 tracking-widest">AFINADOR DIGITAL</span>
        <div className={`w-2 h-2 rounded-full shadow-[0_0_8px] transition-colors ${isActive ? 'bg-green-500 shadow-green-500 animate-pulse' : 'bg-gray-700'}`}></div>
      </div>

      <div className="mb-4">
        <label className="text-[7px] font-black uppercase text-gray-500 mb-1 block">Interface de Áudio</label>
        <select 
          disabled={isActive}
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="w-full bg-gray-900 border border-gray-800 rounded-lg p-1.5 text-[8px] font-black uppercase outline-none focus:border-red-600 disabled:opacity-50"
        >
          {devices.length === 0 && <option value="">Buscando interfaces...</option>}
          {devices.map(device => (
            <option key={device.deviceId} value={device.deviceId}>
              {device.label || `Interface ${device.deviceId.slice(0, 5)}...`}
            </option>
          ))}
        </select>
      </div>

      {error ? (
        <p className="text-[8px] text-red-500 font-bold uppercase text-center py-2">{error}</p>
      ) : (
        <>
          <div className="text-center py-1">
            <div className="text-4xl font-black tracking-tighter italic leading-none">{note}</div>
            <p className="text-[8px] uppercase font-bold text-gray-500 mt-1">
              {isActive ? (Math.abs(cents) < 5 ? 'AFINADO' : cents > 0 ? 'MUITO ALTO' : 'MUITO BAIXO') : 'PRONTO'}
            </p>
          </div>

          <div className="relative h-1 bg-gray-800 rounded-full mt-4 overflow-hidden">
            <div 
              className={`absolute top-0 bottom-0 w-1 transition-all duration-100 ${Math.abs(cents) < 5 ? 'bg-green-500' : 'bg-red-600'}`}
              style={{ left: `${50 + (cents / 50) * 50}%` }}
            ></div>
            <div className="absolute left-1/2 -translate-x-1/2 top-0 bottom-0 w-px bg-white/20"></div>
          </div>
        </>
      )}

      <button 
        onClick={isActive ? stopTuner : startTuner}
        className={`mt-4 py-3 rounded-xl text-[8px] font-black uppercase transition-all active:scale-95 ${isActive ? 'bg-gray-800 text-white' : 'bg-red-600 text-white shadow-lg shadow-red-600/20'}`}
      >
        {isActive ? 'DESLIGAR AFINADOR' : 'INICIAR AFINAÇÃO'}
      </button>
    </div>
  );
};

export default Tuner;

import React, { useState, useEffect, useRef } from 'react';

const Metronome: React.FC = () => {
  const [bpm, setBpm] = useState(60);
  const [playing, setPlaying] = useState(false);
  const timer = useRef<number | null>(null);
  const audioCtx = useRef<AudioContext | null>(null);

  // Função interna para tocar o som
  const playClick = () => {
    if (!audioCtx.current || audioCtx.current.state === 'suspended') return;

    const osc = audioCtx.current.createOscillator();
    const envelope = audioCtx.current.createGain();

    osc.frequency.value = 880;
    envelope.gain.value = 1;
    envelope.gain.exponentialRampToValueAtTime(0.001, audioCtx.current.currentTime + 0.1);

    osc.connect(envelope);
    envelope.connect(audioCtx.current.destination);

    osc.start();
    osc.stop(audioCtx.current.currentTime + 0.1);
  };

  const toggleMetronome = () => {
    // 1. Inicializa ou recupera o contexto imediatamente no clique
    if (!audioCtx.current) {
      audioCtx.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }

    // 2. Chama o resume imediatamente (sem await anterior) para satisfazer o Safari/iOS
    const resumePromise = audioCtx.current.state === 'suspended' 
      ? audioCtx.current.resume() 
      : Promise.resolve();

    resumePromise.then(() => {
      if (playing) {
        if (timer.current) clearInterval(timer.current);
        setPlaying(false);
      } else {
        // Toca o primeiro som imediatamente para confirmar a ativação
        playClick();

        const interval = (60 / bpm) * 1000;
        if (timer.current) clearInterval(timer.current);
        timer.current = window.setInterval(playClick, interval);
        setPlaying(true);
      }
    }).catch(err => {
      console.error("Erro ao ativar áudio no iOS:", err);
    });
  };

  // Efeito para atualizar o tempo se o BPM mudar enquanto toca
  useEffect(() => {
    if (playing) {
      if (timer.current) clearInterval(timer.current);
      const interval = (60 / bpm) * 1000;
      timer.current = window.setInterval(playClick, interval);
    }
    return () => { if (timer.current) clearInterval(timer.current); };
  }, [bpm, playing]);

  return (
    <div className="bg-black text-white p-6 md:p-10 rounded-[2.5rem] shadow-xl border border-gray-800">
      <div className="flex items-center justify-between mb-6">
        <span className="text-[9px] font-black uppercase text-red-600 tracking-widest">METRÔNOMO</span>
        <span className="text-2xl font-black italic">{bpm} BPM</span>
      </div>
      <input 
        type="range" min="40" max="220" value={bpm} 
        onChange={(e) => setBpm(parseInt(e.target.value))}
        className="w-full h-1.5 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-red-600 mb-8"
      />
      <button 
        onClick={toggleMetronome}
        className={`w-full py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all shadow-lg active:scale-95 ${
          playing ? 'bg-white text-black' : 'bg-red-600 text-white shadow-red-600/20'
        }`}
      >
        {playing ? 'PARAR' : 'INICIAR'}
      </button>
    </div>
  );
};

