      if (session?.user) {
        const { data: profile } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', session.user.id)
          .single();

        if (profile) {
          setUser({
            ...profile,
            role: profile.role.toUpperCase()
          });
        }
      }
      setLoading(false);
    };

    fetchData();
    checkSession();
  }, [fetchData]);

  const handleLogin = async (email: string, password: string, role: UserRole) => {
    setLoading(true);

    // Caso especial para o Admin fixo se desejar manter lógica local, 
    // mas o ideal é usar Supabase Auth para todos.
    const ADMIN_EMAIL = 'comotocarhinos@gmail.com';
    const ADMIN_PASSWORD = 'MusicaSacra2026*';

    if (role === 'ADMIN' && email.toLowerCase() === ADMIN_EMAIL.toLowerCase() && password === ADMIN_PASSWORD) {
      setUser(MOCK_ADMIN);
      setLoading(false);
      return;
    }

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) throw error;

      if (data.user) {
        const { data: profile, error: profileError } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', data.user.id)
          .single();

        if (profileError) throw profileError;

        if (profile) {
          if (profile.role.toUpperCase() !== role) {
            await supabase.auth.signOut();
            alert(`Este usuário não tem permissão de ${role}.`);
            setLoading(false);
            return;
          }
          setUser({ ...profile, role: profile.role.toUpperCase() });
        }
      }
    } catch (err: any) {
      alert("Erro ao entrar: " + (err.message || "Dados inválidos"));
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (data: { email: string; password: string; name: string; instrument: Instrument; level: Level }) => {
    setLoading(true);
    try {
