        email: data.email,
        password: data.password,
      });

      if (authError) throw authError;

      if (authData.user) {
        const newProfile = {
          id: authData.user.id,
          name: data.name,
          email: data.email,
          role: 'STUDENT',
          instrument: data.instrument,
          level: data.level,
          avatar: DEFAULT_AVATARS.male,
          total_completed_classes: 0
        };

        const { error: profileError } = await supabase
          .from('profiles')
          .insert([newProfile]);

        if (profileError) throw profileError;

        alert("Cadastro realizado com sucesso! Você já pode entrar.");
        // Opcional: Logar automaticamente ou mudar para tela de login
      }
    } catch (err: any) {
      alert("Erro ao cadastrar: " + (err.message || "Tente novamente mais tarde"));
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  const updateScheduleStatus = async (id: string, newStatus: ScheduledClass['status']) => {
    const classToUpdate = schedules.find(s => s.id === id);
    if (!classToUpdate) return;

    const { error } = await supabase.from('schedules').update({ status: newStatus }).eq('id', id);
    if (!error) {
      if (newStatus === 'COMPLETED' && classToUpdate.status !== 'COMPLETED') {
        const student = students.find(s => s.id === classToUpdate.studentId);
        if (student) {
          const newCount = (student.totalCompletedClasses || 0) + 1;
          await supabase.from('profiles').update({ total_completed_classes: newCount }).eq('id', student.id);
        }
      }
      await fetchData();
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><div className="animate-spin rounded-full h-12 w-12 border-b-4 border-red-600"></div></div>;
  if (!user) return <Login onLogin={handleLogin} onRegister={handleRegister} />;

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard 
          user={user} onLogout={handleLogout}
          students={students} courses={courses} schedules={schedules}
          payments={payments} materials={materials}
          onAddStudent={async (s) => { await supabase.from('profiles').insert([s]); await fetchData(); }}
          onUpdateStudent={async (s) => { await supabase.from('profiles').update({ name: s.name, instrument: s.instrument, level: s.level, avatar: s.avatar, whatsapp: s.whatsapp }).eq('id', s.id); await fetchData(); }}
          onAddSchedule={async (sc) => { await supabase.from('schedules').insert([{ id: sc.id, student_id: sc.studentId, teacher_id: sc.teacherId, date: sc.date, time: sc.time, instrument: sc.instrument, status: sc.status, title: sc.title }]); await fetchData(); }}
          onUpdateSchedule={updateScheduleStatus}
