  const [payments, setPayments] = useState<Payment[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);

  const fetchData = useCallback(async () => {
    try {
      const { data: profiles, error: pError } = await supabase.from('profiles').select('*');
      if (pError) console.warn("Erro ao buscar perfis, usando mocks:", pError);

      if (profiles && profiles.length > 0) {
        setStudents(profiles.map((p: any) => ({ 
          ...p, 
          role: (p.role || 'STUDENT').toUpperCase(),
          totalCompletedClasses: p.total_completed_classes || 0
        })));
      } else {
        setStudents(MOCK_STUDENTS);
      }

      const { data: dbCourses } = await supabase.from('courses').select('*');
      if (dbCourses && dbCourses.length > 0) {
        setCourses(dbCourses.map((c: any) => ({ ...c, studentIds: c.student_ids || [] })));
      } else {
        setCourses(MOCK_COURSES);
      }

      const { data: dbSchedules } = await supabase.from('schedules').select('*');
      if (dbSchedules && dbSchedules.length > 0) {
        setSchedules(dbSchedules.map((s: any) => ({ 
          ...s, 
          studentId: s.student_id,
          teacherId: s.teacher_id,
          status: s.status?.toUpperCase() || 'PENDING'
        })));
      } else {
        setSchedules(MOCK_SCHEDULES);
      }

      const { data: dbPayments } = await supabase.from('payments').select('*');
      if (dbPayments && dbPayments.length > 0) {
        setPayments(dbPayments.map((p: any) => ({ 
          ...p, 
          studentId: p.student_id, 
          dueDate: p.due_date,
          status: (p.status || 'PENDING').toUpperCase()
        })));
      } else {
        setPayments(MOCK_PAYMENTS);
      }
    } catch (err) {
      console.error("Erro fatal ao carregar dados:", err);
    }
  }, []);

  useEffect(() => {
    const checkSession = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          console.log("Sessão ativa encontrada para:", session.user.email);
          const { data: profile, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', session.user.id)
            .single();

          if (profile) {
            setUser({ ...profile, role: profile.role.toUpperCase() });
          } else if (!error) {
             // Caso o Auth exista mas o perfil não (raro), cria um perfil temporário
             setUser({
               id: session.user.id,
               name: session.user.email?.split('@')[0] || 'Aluno',
               email: session.user.email || '',
               role: 'STUDENT'
             });
          }
        }
      } catch (e) {
        console.error("Erro ao verificar sessão:", e);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
    checkSession();
  }, [fetchData]);

  const handleLogin = async (email: string, password: string, role: UserRole) => {
    setLoading(true);
    console.log(`Tentando login como ${role} para ${email}...`);

    // Login Admin fixo (Emergencial)
    const ADMIN_EMAIL = 'comotocarhinos@gmail.com';
    const ADMIN_PASSWORD = 'MusicaSacra2026*';

    if (role === 'ADMIN' && email.toLowerCase() === ADMIN_EMAIL.toLowerCase() && password === ADMIN_PASSWORD) {
      setUser(MOCK_ADMIN);
      setLoading(false);
      return;
    }

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: email.trim(),
        password,
      });

      if (error) {
        if (error.message.includes("Email not confirmed")) {
          throw new Error("Seu e-mail ainda não foi confirmado. Verifique sua caixa de entrada.");
        }
        throw error;
      }

      if (data.user) {
        console.log("Auth bem-sucedido. Buscando perfil...");
        const { data: profile, error: profileError } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', data.user.id)
          .single();

        if (profileError) {
          console.warn("Usuário autenticado mas perfil não encontrado no banco.");
          // Se o perfil sumiu mas o auth existe, podemos criar um na hora ou dar erro
          throw new Error("Perfil de aluno não encontrado. Entre em contato com o suporte.");
        }

        if (profile) {
          const profileRole = profile.role.toUpperCase();
