  const ensureProfileExists = async (authUser: any) => {
    const { data: profile } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', authUser.id)
      .single();

    if (!profile) {
      console.log("Perfil não encontrado, criando a partir dos metadados...");
      const meta = authUser.user_metadata;
      const newProfile = {
        id: authUser.id,
        name: meta.name || authUser.email.split('@')[0],
        email: authUser.email,
        role: 'STUDENT',
        instrument: meta.instrument || 'Violão',
        level: meta.level || 'NZ',
        avatar: DEFAULT_AVATARS.male,
        total_completed_classes: 0
      };

      const { data: created, error } = await supabase.from('profiles').insert([newProfile]).select().single();
      if (error) {
        console.error("Erro ao criar perfil automático:", error);
        return newProfile; // Retorna o objeto mesmo com erro para não travar o login
      }
      return created;
    }
    return profile;
  };

