        const newProfile = {
          id: authData.user.id,
          name: data.name,
          email: data.email.trim(),
          role: 'STUDENT',
          instrument: data.instrument,
          level: data.level,
          avatar: DEFAULT_AVATARS.male,
          total_completed_classes: 0
        };

