import React, { useState, useEffect, useCallback } from 'react';
import { User, UserRole, Course, ScheduledClass, Payment, Material, Instrument, Level } from './types';
import { MOCK_ADMIN, MOCK_STUDENTS, MOCK_COURSES, MOCK_SCHEDULES, MOCK_PAYMENTS, MOCK_MATERIALS, DEFAULT_AVATARS } from './constants';
import AdminDashboard from './components/AdminDashboard';
import StudentDashboard from './components/StudentDashboard';
import Login from './components/Login';
import { supabase } from './services/supabase';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [schedules, setSchedules] = useState<ScheduledClass[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);

  const fetchData = useCallback(async () => {
    try {
      const { data: profiles, error: pError } = await supabase.from('profiles').select('*');
      if (profiles && profiles.length > 0) {
        setStudents(profiles.map((p: any) => ({ 
          ...p, 
          role: (p.role || 'STUDENT').toUpperCase(),
          totalCompletedClasses: p.total_completed_classes || 0
        })));
      } else {
        console.warn("Nenhum perfil encontrado no DB, usando mocks temporários.");
        setStudents(MOCK_STUDENTS);
      }

      const { data: dbCourses } = await supabase.from('courses').select('*');
      if (dbCourses) setCourses(dbCourses.map((c: any) => ({ ...c, studentIds: c.student_ids || [] })));

      const { data: dbSchedules } = await supabase.from('schedules').select('*');
      if (dbSchedules) setSchedules(dbSchedules.map((s: any) => ({ ...s, studentId: s.student_id, teacherId: s.teacher_id, status: s.status?.toUpperCase() || 'PENDING' })));

      const { data: dbPayments } = await supabase.from('payments').select('*');
      if (dbPayments) setPayments(dbPayments.map((p: any) => ({ ...p, studentId: p.student_id, dueDate: p.due_date, status: (p.status || 'PENDING').toUpperCase() })));
    } catch (err) {
      console.error("Erro na busca de dados:", err);
    }
  }, []);

  // FUNÇÃO CRÍTICA: Garante que o usuário tenha um perfil, mesmo que o DB esteja com erro
  const ensureProfileExists = async (authUser: any): Promise<User> => {
    console.log("Verificando integridade do perfil para:", authUser.id);

    // 1. Tentar buscar o perfil no banco
    const { data: profile, error: selectError } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', authUser.id)
      .single();

    if (profile) {
      console.log("Perfil encontrado no banco de dados.");
      return { ...profile, role: profile.role.toUpperCase() };
    }

    // 2. Se não existe ou deu erro, usar metadados do Auth como redundância
    console.warn("Perfil não existe no banco. Tentando criar a partir de metadados...");
    const meta = authUser.user_metadata || {};
    const fallbackProfile: User = {
      id: authUser.id,
      name: meta.name || authUser.email?.split('@')[0] || 'Aluno',
      email: authUser.email || '',
      role: 'STUDENT',
      instrument: (meta.instrument as Instrument) || 'Violão',
      level: (meta.level as Level) || 'NZ',
      avatar: meta.avatar || DEFAULT_AVATARS.male,
      totalCompletedClasses: 0
    };

    // 3. Tentar inserir no banco (pode falhar por RLS, mas tentamos)
    const { error: insertError } = await supabase.from('profiles').insert([{
      id: fallbackProfile.id,
      name: fallbackProfile.name,
      email: fallbackProfile.email,
      role: fallbackProfile.role,
      instrument: fallbackProfile.instrument,
      level: fallbackProfile.level,
      avatar: fallbackProfile.avatar,
      total_completed_classes: 0
    }]);

    if (insertError) {
      console.error("Erro ao persistir perfil no banco (RLS?):", insertError.message);
      // Se falhar a gravação, retornamos o objeto local para não bloquear o acesso do aluno
    } else {
      console.log("Perfil sincronizado com sucesso no banco de dados.");
    }

    return fallbackProfile;
  };

  useEffect(() => {
    const checkSession = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          const profile = await ensureProfileExists(session.user);
          setUser(profile);
        }
      } catch (e) {
        console.error("Erro ao checar sessão inicial:", e);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
    checkSession();
  }, [fetchData]);

  const handleLogin = async (email: string, password: string, role: UserRole) => {
    setLoading(true);
    console.log(`Tentando login: ${email} como ${role}`);

    const ADMIN_EMAIL = 'comotocarhinos@gmail.com';
    const ADMIN_PASSWORD = 'MusicaSacra2026*';

    if (role === 'ADMIN' && email.toLowerCase() === ADMIN_EMAIL.toLowerCase() && password === ADMIN_PASSWORD) {
      setUser(MOCK_ADMIN);
      setLoading(false);
      return;
    }

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: email.trim(),
        password,
      });

      if (error) {
        if (error.message.includes("Email not confirmed")) {
          throw new Error("⚠️ Seu e-mail foi cadastrado mas falta confirmar o link enviado para sua caixa de entrada.");
        }
        if (error.message.includes("Invalid login credentials")) {
          throw new Error("❌ E-mail ou senha incorretos.");
        }
        throw error;
      }

      if (data.user) {
        const profile = await ensureProfileExists(data.user);

        // Bloqueia se um aluno tentar entrar no painel de admin ou vice-versa
        if (profile.role !== role) {
          await supabase.auth.signOut();
          throw new Error(`Este usuário é um ${profile.role}. Selecione '${profile.role === 'ADMIN' ? 'Admin' : 'Aluno'}' acima.`);
        }

        setUser(profile);
        console.log("Login realizado com sucesso!");
      }
    } catch (err: any) {
      alert(err.message || "Ocorreu um erro inesperado ao entrar.");
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (data: { email: string; password: string; name: string; instrument: Instrument; level: Level }) => {
    setLoading(true);
    try {
      console.log("Registrando novo usuário...");
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: data.email.trim(),
        password: data.password,
        options: {
          data: {
            name: data.name,
            instrument: data.instrument,
            level: data.level,
            avatar: DEFAULT_AVATARS.male
          }
        }
      });

      if (authError) throw authError;

      if (authData.user) {
        // Tenta criar o perfil imediatamente por conveniência
        await supabase.from('profiles').insert([{
          id: authData.user.id,
          name: data.name,
          email: data.email.trim(),
          role: 'STUDENT',
          instrument: data.instrument,
          level: data.level,
          avatar: DEFAULT_AVATARS.male,
          total_completed_classes: 0
        }]);

        if (!authData.session) {
          alert("✅ CONTA CRIADA! Verifique seu e-mail agora. Você PRECISA clicar no link de confirmação para poder entrar.");
        } else {
          // Caso o Supabase esteja configurado para logar direto sem confirmação
          const profile = await ensureProfileExists(authData.user);
          setUser(profile);
        }
      }
    } catch (err: any) {
      alert("Erro ao cadastrar: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  if (loading) return (
    <div className="h-screen flex flex-col items-center justify-center bg-white">
      <div className="animate-spin rounded-full h-12 w-12 border-b-4 border-red-600 mb-4"></div>
      <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">Sincronizando com a Escola...</p>
    </div>
  );

  if (!user) return <Login onLogin={handleLogin} onRegister={handleRegister} />;

  return (
    <div className="min-h-screen bg-gray-50">
      {user.role === 'ADMIN' ? (
        <AdminDashboard 
          user={user} onLogout={handleLogout}
          students={students} courses={courses} schedules={schedules}
          payments={payments} materials={materials}
          onAddStudent={async (s) => { await supabase.from('profiles').insert([s]); await fetchData(); }}
          onUpdateStudent={async (s) => { await supabase.from('profiles').update({ name: s.name, instrument: s.instrument, level: s.level, avatar: s.avatar, whatsapp: s.whatsapp }).eq('id', s.id); await fetchData(); }}
          onAddSchedule={async (sc) => { await supabase.from('schedules').insert([{ id: sc.id, student_id: sc.studentId, teacher_id: sc.teacherId, date: sc.date, time: sc.time, instrument: sc.instrument, status: sc.status, title: sc.title }]); await fetchData(); }}
          onUpdateSchedule={async (id, status) => { await supabase.from('schedules').update({ status }).eq('id', id); await fetchData(); }}
          onAddCourse={async (c) => { await supabase.from('courses').insert([{ id: c.id, title: c.title, instrument: c.instrument, level: c.level, description: c.description, modules: c.modules, student_ids: c.studentIds }]); await fetchData(); }}
          onUpdateCourseContent={async (c) => { await supabase.from('courses').update({ modules: c.modules, description: c.description }).eq('id', c.id); await fetchData(); }}
          onUpdateCourseAccess={async (id, ids) => { await supabase.from('courses').update({ student_ids: ids }).eq('id', id); await fetchData(); }}
          onAddPayment={async (p) => { await supabase.from('payments').insert([p]); await fetchData(); }}
          onUpdatePayment={async (id, u) => { await supabase.from('payments').update({ status: u.status }).eq('id', id); await fetchData(); }}
        />
      ) : (
        <StudentDashboard 
          user={user} onLogout={handleLogout}
          courses={courses} schedules={schedules}
          materials={materials} payments={payments}
          onUpdateProfile={async (u) => { await supabase.from('profiles').update({ name: u.name, whatsapp: u.whatsapp, avatar: u.avatar }).eq('id', u.id); setUser(u); await fetchData(); }}
        />
      )}
    </div>
  );
};

export default App;

