               <h3 className="text-xl md:text-2xl font-black uppercase tracking-tighter italic">Meus Dados</h3>
               <button type="button" onClick={() => setIsEditingProfile(false)} className="text-3xl font-black hover:text-red-600 transition-colors">&times;</button>
             </div>
             <div className="flex flex-col items-center mb-8 md:mb-10">
                <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                   <img src={profileForm.avatar || DEFAULT_AVATARS.male} className="w-24 h-24 md:w-32 md:h-32 rounded-full border-4 border-red-600 object-cover shadow-2xl mb-4 md:mb-6 transition-transform group-hover:scale-105" />
                   <div className="absolute -bottom-1 -right-1 bg-black text-white p-1.5 rounded-full border-2 border-white shadow-lg text-xs">📸</div>
                   <input 
                     type="file" 
                     ref={fileInputRef} 
                     onChange={handleFileUpload} 
                     className="hidden" 
                     accept="image/*" 
                   />
                </div>
                <div className="flex flex-col gap-2 w-full">
                  <div className="flex gap-2 w-full">
                    <button type="button" onClick={() => setProfileForm({...profileForm, avatar: DEFAULT_AVATARS.male})} className="flex-1 bg-gray-100 text-[9px] font-black uppercase px-4 py-2.5 rounded-xl hover:bg-black hover:text-white transition-all">Masc</button>
                    <button type="button" onClick={() => setProfileForm({...profileForm, avatar: DEFAULT_AVATARS.female})} className="flex-1 bg-gray-100 text-[9px] font-black uppercase px-4 py-2.5 rounded-xl hover:bg-black hover:text-white transition-all">Fem</button>
                  </div>
                </div>
             </div>
             <div className="space-y-4 md:space-y-6 mb-8 md:mb-10">
                <div className="space-y-1">
                  <label className="text-[9px] font-black uppercase text-gray-400 ml-4">Seu Nome</label>
                  <input type="text" value={profileForm.name} onChange={e => setProfileForm({...profileForm, name: e.target.value})} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold outline-none focus:border-red-600 transition-all" />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black uppercase text-gray-400 ml-4">WhatsApp</label>
                  <input type="text" value={profileForm.whatsapp || ''} onChange={e => setProfileForm({...profileForm, whatsapp: e.target.value})} className="w-full border-2 border-gray-100 p-4 rounded-2xl text-xs font-bold outline-none focus:border-red-600 transition-all" placeholder="(00) 00000-0000" />
                </div>
             </div>
             <button type="submit" disabled={isSaving} className="w-full bg-red-600 text-white py-4 md:py-6 rounded-2xl text-[10px] md:text-[12px] font-black uppercase shadow-xl shadow-red-600/30 hover:bg-black transition-all active:scale-95">
               {isSaving ? "Gravando..." : "Confirmar Alterações"}
             </button>
          </form>
        </div>
      )}
    </div>
  );
};

export default StudentDashboard;
